import{n as o}from"./shared-CAKwAg2C.js";const s={"LEARN HOW THE INTERNET WORKS":"ONTDEK HOE HET INTERNET WERKT","NOW LEARNING":"NU AAN HET LEREN","OSI LAYER":"OSI-LAAG","LEARNING PROGRESS":"JOUW VOORTGANG",COMPLETE:"VOLTOOID","IN PROGRESS":"BEZIG","{pct}% complete":"{pct}% voltooid","DESIGNED BY":"ONTWORPEN DOOR","Dilum Sanjaya on X":"Dilum Sanjaya op X","Layer {n}: {name}":"Laag {n}: {name}",Physical:"Fysiek","Data Link":"Datalink",Network:"Netwerk",Transport:"Transport",Session:"Sessie",Presentation:"Presentatie",Application:"Applicatie","OVERVIEW · {n} STEPS":"OVERZICHT · {n} STAPPEN","STEP {n}/{total} · {title}":"STAP {n}/{total} · {title}","LESSON COMPLETE":"LES VOLTOOID",PROTOCOLS:"PROTOCOLLEN",Protocols:"Protocollen",Language:"Taal",Theme:"Thema","Light mode":"Lichte modus","Dark mode":"Donkere modus","INTERNET PROTOCOLS":"INTERNETPROTOCOLLEN","Close the protocol list":"Protocollijst sluiten","Close (Esc)":"Sluiten (Esc)",ALL:"ALLE",CORE:"BASIS",APPLICATION:"APPLICATIES",SECURITY:"BEVEILIGING",NETWORK:"NETWERK",SEQUENCE:"SEQUENTIE",View:"Weergave","Switch view (V)":"Weergave wisselen (V)","Network diagram":"Netwerkdiagram","Sequence diagram":"Sequentiediagram","STEP {n}":"STAP {n}","PROTOCOL OVERVIEW":"PROTOCOLOVERZICHT","STEP DETAILS":"STAPDETAILS","LESSON SUMMARY":"SAMENVATTING VAN DE LES",OVERVIEW:"OVERZICHT",ACTIVE:"ACTIEF","STEP {n} OF {total}":"STAP {n} VAN {total}","PACKET {n} OF {total}":"PAKKET {n} VAN {total}","PACKETS {from}–{to} OF {total}":"PAKKETTEN {from}–{to} VAN {total}","{n} LOST":"{n} VERLOREN","1 LOST":"1 VERLOREN",ENCRYPTED:"VERSLEUTELD","LOST ON THE WAY":"ONDERWEG VERLOREN","PACKET FLOW":"PAKKETSTROOM","Colour key":"Kleurlegenda","Playback speed":"Afspeelsnelheid","Previous step (←)":"Vorige stap (←)","Previous step":"Vorige stap","Play / pause (Space)":"Afspelen / pauzeren (spatie)",PLAY:"AFSPELEN",PAUSE:"PAUZE",REPLAY:"OPNIEUW",STEP:"STAP","One packet at a time":"Eén pakket tegelijk",RESET:"RESET",Reset:"Reset","Back to the overview (Esc)":"Terug naar het overzicht (Esc)","NO.":"NR.",TIME:"TIJD",SOURCE:"BRON",DESTINATION:"BESTEMMING",PROTOCOL:"PROTOCOL",INFO:"INFO",SIZE:"GROOTTE","No packets on the wire yet.":"Nog geen pakketten onderweg.",LOST:"VERLOREN","Packet inspector":"Pakketinspector","Previous packet":"Vorig pakket","Previous packet (←)":"Vorig pakket (←)","Next packet":"Volgend pakket","Next packet (→)":"Volgend pakket (→)",Close:"Sluiten","E.G.":"BV.","an example value: it differs in every real capture":"een voorbeeldwaarde: die is in elke echte opname anders","bytes the lesson can’t show: encrypted, random, or a file’s contents":"bytes die de les niet kan laten zien: versleuteld, willekeurig of de inhoud van een bestand",BYTES:"BYTES","{n} in this frame":"{n} in dit frame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Deze rij staat voor {n} TCP-segmenten met een bericht van {size} bytes; het eerste segment wordt getoond","This packet was lost on the way":"Dit pakket is onderweg verloren gegaan",Padding:"Opvulling","One packet at a time (S)":"Eén pakket tegelijk (S)","KEYBOARD SHORTCUTS":"SNELTOETSEN","Press {key} any time to see these again.":"Druk op elk moment op {key} om ze opnieuw te zien.","Search protocols":"Protocollen zoeken","Search protocols and steps":"Protocollen en stappen zoeken","Nothing matches.":"Niets gevonden.","to move":"om te bewegen","to open":"om te openen","Protocol list":"Protocollijst","Diagram only":"Alleen het diagram",Fullscreen:"Volledig scherm","Keyboard shortcuts":"Sneltoetsen",Playback:"Afspelen","Hide the protocol list (L)":"Protocollijst verbergen (L)","Diagram only (D)":"Alleen het diagram (D)","Fullscreen (F)":"Volledig scherm (F)","Keyboard shortcuts (?)":"Sneltoetsen (?)","Show the protocol list (L)":"Protocollijst tonen (L)","Show all panels (D)":"Alle panelen tonen (D)","Exit fullscreen (F)":"Volledig scherm verlaten (F)","Play or pause":"Afspelen of pauzeren","Next step":"Volgende stap","Go to step 1 to 9":"Naar stap 1 tot 9","Slower, faster":"Langzamer, sneller","Back to the overview":"Terug naar het overzicht","Network or sequence view":"Netwerk- of sequentieweergave","Show or hide the protocol list":"Protocollijst tonen of verbergen","Light or dark theme":"Licht of donker thema",Find:"Zoeken","Next or previous protocol":"Volgend of vorig protocol","These shortcuts":"Deze sneltoetsen","Previous or next packet":"Vorig of volgend pakket","Close it":"Sluiten"},i={"Hypertext Transfer Protocol":"Hypertext Transfer Protocol","HTTP Secure":"Beveiligd HTTP","Transmission Control Protocol":"Transmission Control Protocol","User Datagram Protocol":"User Datagram Protocol","Internet Protocol":"Internet Protocol","Domain Name System":"Domain Name System","Dynamic Host Configuration":"Dynamische hostconfiguratie","Internet Control Message":"Internet Control Message","Simple Mail Transfer Protocol":"Simple Mail Transfer Protocol","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Internet Message Access","File Transfer Protocol":"File Transfer Protocol","Secure Shell":"Secure Shell","Transport Layer Security":"Transport Layer Security",Internet:"Internet",Client:"Client",Router:"Router","DNS Resolver":"DNS-resolver","Web Server":"Webserver","Root Server":"Rootserver",".com TLD Server":".com-TLD-server","Authoritative Server":"Gezaghebbende server","Mail Server":"Mailserver",".com Server":".com-server",Authoritative:"Gezaghebbend",Server:"Server","Web Communication":"Webcommunicatie",Request:"Verzoek",Response:"Antwoord","Data ACKs not shown":"ACK’s voor data niet getoond","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP is het protocol van het web: een client vraagt om een bron, zoals een HTML-pagina, en de server antwoordt met een statuscode, headers en meestal een body. Elke uitwisseling is één verzoek en één antwoord, als leesbare tekst geschreven in HTTP/1.1.",Layer:"Laag","Application (Layer 7)":"Applicatie (laag 7)","Default Port":"Standaardpoort","Data Format":"Gegevensformaat","Text (headers + optional body)":"Tekst (headers + optionele body)","Common Methods":"Veelgebruikte methoden","Defined In":"Vastgelegd in","Page delivered":"Pagina afgeleverd","One request, one response":"Eén verzoek, één antwoord","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"In minder dan een tiende seconde zocht de laptop een adres op, opende een TCP-verbinding en wisselde één HTTP-verzoek en -antwoord uit, allemaal leesbaar voor iedereen onderweg. Druk op OPNIEUW om het nog eens te bekijken.","Round trips":"Rondreizen","Total time":"Totale tijd","Page size":"Paginagrootte","Sent as 9 TCP segments":"Verstuurd als 9 TCP-segmenten","Client Request":"Verzoek van de client","Browser prepares the request":"De browser bereidt het verzoek voor","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Je opent http://www.example.com. De browser gaat een GET-verzoek sturen, maar pakketten reizen naar IP-adressen, niet naar namen, dus eerst heeft hij het adres van de server nodig. (Browsers proberen nu eerst https://; dit is de onversleutelde versie.)",Method:"Methode","Next hop":"Volgende hop","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"DNS-resolutie","Finds the server’s IP address":"Vindt het IP-adres van de server","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"De laptop vraagt de DNS-server die hij via DHCP kreeg, 8.8.8.8, om het adres van www.example.com. De vraag gaat via UDP-poort 53 en het antwoord is een A-record met het IPv4-adres. (Op een netwerk met IPv6 zou hij ook om een AAAA-record vragen.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (had het in de cache)","UDP, port 53":"UDP, poort 53",Answer:"Antwoord","DNS QUERY":"DNS-VRAAG","DNS REPLY":"DNS-ANTWOORD","TCP Connection":"TCP-verbinding","Establishes a reliable link":"Zet een betrouwbare verbinding op","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP draait boven op TCP. Voordat er paginadata gaat stromen, openen de laptop en de server een verbinding naar poort 80 met een three-way handshake: SYN, SYN-ACK, ACK.","Server port":"Serverpoort","Client port":"Clientpoort",Handshake:"Handshake","HTTP Exchange":"HTTP-uitwisseling","Request and response messages":"Verzoek- en antwoordberichten","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"De browser stuurt een GET-verzoek met een Host-header. De server antwoordt 200 OK met de HTML in de body: 12.2 KB, te groot voor één pakket, dus TCP splitst het in 9 segmenten van maximaal 1460 bytes (hier als één getekend).",Status:"Status",Body:"Body","text/html, 12.2 KB":"text/html, 12.2 KB","Sent as":"Verstuurd als","12.2 KB in 9 segments":"12.2 KB in 9 segmenten","Page Rendering":"Pagina weergeven","Browser displays the content":"De browser toont de inhoud","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"De browser leest de HTML en tekent de pagina. Gekoppelde CSS, afbeeldingen en scripts zouden elk nieuwe verzoeken starten zoals dit, en waar het kan de open verbinding hergebruiken.",Document:"Document",Connection:"Verbinding","Kept open for reuse":"Open gehouden voor hergebruik","Seen on the laptop’s home network":"Gezien op het thuisnetwerk van de laptop",Destination:"Bestemming","The router: anything beyond the home network goes to it first.":"De router: alles buiten het thuisnetwerk gaat eerst naar hem.",Source:"Bron","The laptop’s network card.":"De netwerkkaart van de laptop.",Type:"Type","What the frame carries.":"Wat het frame vervoert.","Version, header length":"Versie, headerlengte","4, 20 bytes":"4, 20 bytes","IPv4, with no options.":"IPv4, zonder opties.","Priority and congestion marks; 0 means ordinary traffic.":"Prioriteit en congestiemarkeringen; 0 betekent gewoon verkeer.","Total length":"Totale lengte","This header and everything inside it.":"Deze header en alles erin.",Identification:"Identificatie","Lets the receiver reassemble the pieces if the packet gets split.":"Laat de ontvanger de stukken weer samenvoegen als het pakket wordt opgesplitst.",Flags:"Vlaggen",none:"geen","Routers may split it if a link is too small.":"Routers mogen het opsplitsen als een verbinding te klein is.","Time to live":"Time to live","Windows starts at 128.":"Windows begint bij 128.",Protocol:"Protocol","Header checksum":"Header-checksum","Covers this header only; every router recomputes it after lowering the TTL.":"Dekt alleen deze header; elke router berekent hem opnieuw na het verlagen van de TTL.","Source port":"Bronpoort","Destination port":"Bestemmingspoort",Length:"Lengte","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"UDP-header en data. Meer is UDP niet: geen nummering, geen bevestigingen.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Dekt de header, de data en de IP-adressen.","Transaction ID":"Transactie-ID","Picked at random; the answer must carry the same one.":"Willekeurig gekozen; het antwoord moet dezelfde bevatten.","0x0100: query, RD (recursion desired)":"0x0100: vraag, RD (recursie gewenst)",Questions:"Vragen",Answers:"Antwoorden","Authority records":"Autoriteitsrecords","Additional records":"Extra records",Question:"Vraag","www.example.com, type A, class IN":"www.example.com, type A, klasse IN","The laptop.":"De laptop.","The router’s side facing the home network.":"De kant van de router die naar het thuisnetwerk wijst.","Started at 128; 10 routers on the way each took 1.":"Begon bij 128; 10 routers onderweg haalden er elk 1 af.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: antwoord, RD (recursie gewenst), RA (recursie beschikbaar)","DF (don’t fragment)":"DF (niet fragmenteren)","Routers must not split it; if it’s too big they report back instead.":"Routers mogen het niet opsplitsen; is het te groot, dan melden ze dat terug.","Picked by the laptop’s system for this connection.":"Gekozen door het systeem van de laptop voor deze verbinding.","Sequence number":"Volgnummer","This side’s starting number. Shown as 0; the real one is random.":"Het startnummer van deze kant. Getoond als 0; het echte is willekeurig.","Real sequence number":"Echt volgnummer",Acknowledgment:"Bevestiging","0 (not used yet)":"0 (nog niet gebruikt)","A first SYN has nothing to acknowledge.":"Een eerste SYN heeft niets te bevestigen.","Header length":"Headerlengte","20 bytes, plus 12 of options.":"20 bytes, plus 12 aan opties.",Window:"Venster","How much more data this side can take right now.":"Hoeveel data deze kant op dit moment nog kan aannemen.","Covers the header, the data and the IP addresses, so damage is caught.":"Dekt de header, de data en de IP-adressen, zodat beschadiging opvalt.","Urgent pointer":"Urgent-pointer",Options:"Opties","Maximum segment size":"Maximale segmentgrootte","The most data this side wants in one segment.":"De meeste data die deze kant in één segment wil.","Spacing, so the next option lines up.":"Opvulling, zodat de volgende optie goed uitlijnt.","Window scale":"Vensterschaal","Window values are multiplied by this, so windows can be larger than 64 KB.":"Vensterwaarden worden hiermee vermenigvuldigd, zodat vensters groter dan 64 KB kunnen zijn.","SACK permitted":"SACK toegestaan",yes:"ja","This side understands selective acknowledgements.":"Deze kant begrijpt selectieve bevestigingen.","Started at 64; 12 routers on the way each took 1.":"Begon bij 64; 12 routers onderweg haalden er elk 1 af.","The next byte this side expects: everything before it has arrived.":"De volgende byte die deze kant verwacht: alles daarvoor is aangekomen.","Position of this segment’s first byte, counted from this side’s SYN.":"Positie van de eerste byte van dit segment, geteld vanaf de SYN van deze kant.","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 bytes)","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Ethernetframes zijn minstens 60 bytes (64 met de checksum die de kaart toevoegt), dus korte frames worden opgevuld.",Text:"Tekst","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 bytes)","covers bytes not shown here":"dekt bytes die hier niet getoond worden","12,500 bytes: the HTML page":"12,500 bytes: de HTML-pagina","The page itself; its contents are not part of the lesson.":"De pagina zelf; de inhoud ervan hoort niet bij de les.","Secure Web":"Beveiligd web","TLS handshake":"TLS-handshake","HTTP request":"HTTP-verzoek","HTTP response":"HTTP-antwoord","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS is HTTP verstuurd door een versleutelde TLS-verbinding. TLS bewijst met een certificaat dat de server is wie hij zegt te zijn, spreekt nieuwe sleutels af en beschermt daarna elk verzoek en antwoord tegen meelezen of wijzigen onderweg.","Application (HTTP over TLS)":"Applicatie (HTTP over TLS)",Security:"Beveiliging","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 nog veel gebruikt)",Proves:"Bewijst","Server identity (certificate)":"Identiteit van de server (certificaat)","Secure page delivered":"Beveiligde pagina afgeleverd","Encrypted, except the lookup":"Versleuteld, behalve het opzoeken","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"De browser zocht het adres op via gewone DNS, opende een TCP-verbinding, controleerde het certificaat van de server en sprak in één rondreis sleutels af. Elke HTTP-byte daarna reisde versleuteld. Druk op OPNIEUW om het nog eens te bekijken.",Cipher:"Versleuteling","Still visible":"Nog zichtbaar","IPs, server name, sizes":"IP’s, servernaam, groottes","Secure Request":"Beveiligd verzoek","Browser asks for https://":"Browser vraagt om https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Je typt https://www.example.com. De ‘s’ zegt de browser de verbinding met TLS te beschermen, standaard op poort 443. Voordat hij kan verbinden, moet hij nog steeds het IP-adres van de server vinden.",Port:"Poort","DNS Lookup":"DNS-opzoeking","Same lookup as HTTP, not encrypted":"Dezelfde opzoeking als bij HTTP, niet versleuteld","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"De opzoeking is precies dezelfde als bij gewoon HTTP: een vraag aan 8.8.8.8 via UDP-poort 53. Die is niet versleuteld, dus iedereen onderweg kan zien naar welke naam je vroeg, tenzij de browser DNS over HTTPS gebruikt.",Encrypted:"Versleuteld","No (plain DNS)":"Nee (gewone DNS)","TCP Handshake":"TCP-handshake","Opens a connection to port 443":"Opent een verbinding naar poort 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS draait boven op TCP, dus eerst komt dezelfde three-way handshake, deze keer naar poort 443. Nog niets is versleuteld.","TLS Handshake":"TLS-handshake","Agrees on keys, checks the certificate":"Spreekt sleutels af, controleert het certificaat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"De browser biedt versleutelingen en sleuteldelen aan, waaronder een post-quantum hybride. De server kiest die en stuurt zijn eigen deel, daarna zijn certificaat, al versleuteld. De browser controleert het aan de hand van autoriteiten die hij vertrouwt.",Version:"Versie","Key exchange":"Sleuteluitwisseling","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hybride)","Server name":"Servernaam","Sent in clear (SNI)":"Onversleuteld verstuurd (SNI)","key shares: hybrid + x25519":"sleuteldelen: hybride + x25519","cipher: AES_128_GCM_SHA256":"versleuteling: AES_128_GCM_SHA256","then encrypted: cert, Finished":"dan versleuteld: cert, Finished","CERTIFICATE VALID":"CERTIFICAAT GELDIG","handshake complete (encrypted)":"handshake voltooid (versleuteld)","Encrypted Exchange":"Versleutelde uitwisseling","HTTP inside TLS records":"HTTP in TLS-records","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"De GET en 200 OK zijn dezelfde HTTP-berichten als eerder, verzegeld in TLS-records die er op de lijn uitzien als willekeurige ‘application data’. De server geeft ook twee sessietickets mee, zodat een later bezoek een deel van de handshake kan overslaan.",Inside:"Binnenin","GET / and 200 OK":"GET / en 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, voor sneller opnieuw verbinden","APP DATA":"APP-DATA","inside: GET / HTTP/1.1":"binnen: GET / HTTP/1.1","outside: encrypted bytes":"buiten: versleutelde bytes","inside: HTTP/1.1 200 OK":"binnen: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"buiten: 12.9 KB, 9 segmenten","Browser shows the padlock":"Browser toont het slotje","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"De browser ontsleutelt het antwoord, tekent de pagina en toont een slotje: de verbinding is privé en de server heeft zijn identiteit bewezen. De header Strict-Transport-Security zegt hem voortaan HTTPS te gebruiken voor deze site.",Remembers:"Onthoudt","HTTPS only (HSTS), 1 year":"Alleen HTTPS (HSTS), 1 jaar","Server Hello + encrypted handshake, 3 segments":"Server Hello + versleutelde handshake, 3 segmenten","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (versleuteld)","Application Data (HTTP request)":"Application Data (HTTP-verzoek)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (versleuteld)","Application Data (HTTP response), 9 segments":"Application Data (HTTP-antwoord), 9 segmenten",Record:"Record","Content type":"Inhoudstype","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Het record van een Client Hello zegt TLS 1.0, zodat oude tussenapparatuur het doorlaat; de echte versies worden binnenin aangeboden.","Handshake type":"Handshaketype",Contents:"Inhoud","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Alles wat de browser ondersteunt. Browsers wisselen per verbinding een paar details af.","Server name (SNI)":"Servernaam (SNI)","Versions offered":"Aangeboden versies","Key shares":"Sleuteldelen","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 bytes), X25519","App protocols (ALPN)":"App-protocollen (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"TLS 1.3-records zeggen aan de buitenkant 1.2, voor compatibiliteit.","The server’s choices and its half of the hybrid key exchange.":"De keuzes van de server en zijn helft van de hybride sleuteluitwisseling.","Cipher suite":"Cipher suite","Key share":"Sleuteldeel","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 bytes)","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Heeft geen taak in TLS 1.3; wordt meegestuurd zodat tussenapparatuur een bekende handshake ziet.","Every encrypted record says Application Data on the outside; the real type is inside.":"Elk versleuteld record zegt aan de buitenkant Application Data; het echte type zit binnenin.","Encrypted data":"Versleutelde data","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Versleutelde tekst, eindigend op een tag van 16 bytes die elke wijziging verraadt. Alleen de twee uiteinden kunnen hem lezen.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (de keten), Certificate Verify (de handtekening), Finished","Finished: a check value over the whole handshake":"Finished: een controlewaarde over de hele handshake","The HTTP request":"Het HTTP-verzoek","New Session Ticket: lets a later visit resume":"New Session Ticket: laat een later bezoek hervatten","The HTTP response, then the 12,500-byte page":"Het HTTP-antwoord, daarna de pagina van 12,500 bytes","Reliable Delivery":"Betrouwbare aflevering","Handshake and ACKs":"Handshake en ACK’s","Data from laptop":"Data van de laptop","Data from server":"Data van de server","Closing (FIN)":"Afsluiten (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP maakt van de ‘best effort’-pakketbezorging van internet een betrouwbare, geordende stroom bytes. Het nummert elke byte, bevestigt wat aankomt, verstuurt opnieuw wat zoekraakt en doseert de afzender zodat de andere kant en het netwerk niet overspoeld raken.","Transport (Layer 4)":"Transport (laag 4)","Three-way handshake":"Three-way handshake",Reliability:"Betrouwbaarheid","Sequence numbers + ACKs":"Volgnummers + ACK’s",Recovery:"Herstel",Retransmission:"Hertransmissie",Header:"Header","20–60 bytes":"20–60 bytes","Connection closed":"Verbinding gesloten","Every byte accounted for":"Elke byte verantwoord","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP opende een verbinding, nummerde en bevestigde elke byte, zag een gat en verstuurde alleen het ontbrekende segment opnieuw, en sloot daarna beide richtingen netjes af. curl ontving elke byte op volgorde en merkte niets van het verlies. Druk op OPNIEUW om het nog eens te bekijken.",Segments:"Segmenten","14 (1 lost, 1 resent)":"14 (1 verloren, 1 opnieuw)","Bytes delivered":"Bytes afgeleverd","78 up, 2,920 down":"78 heen, 2,920 terug","Loss found by":"Verlies ontdekt via","Duplicate ACK + SACK":"Dubbele ACK + SACK","Open Connection":"Verbinding openen","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl kent het adres van de server al. Voordat er data gaat, kiezen beide kanten een startvolgnummer en bevestigen dat: SYN, SYN-ACK, ACK. De nummers hier zijn relatief; echte beginnen bij een willekeurige waarde.","203.0.113.10, port 80":"203.0.113.10, poort 80","Send Data":"Data versturen","Every byte is numbered":"Elke byte is genummerd","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl stuurt zijn HTTP-verzoek van 78 bytes: bytes 1 tot en met 78. Het ACK-nummer van de server, 79, is de volgende byte die hij verwacht, wat betekent dat alles daarvoor is aangekomen.",Sent:"Verstuurd","78 bytes (seq 1–78)":"78 bytes (seq 1–78)","79 = next byte expected":"79 = volgende verwachte byte","Two Segments Back":"Twee segmenten terug","One of them is lost":"Eén ervan raakt kwijt","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"De server antwoordt met 2,920 bytes: twee volle segmenten van 1,460 bytes, het meeste dat hier in één pakket past, direct na elkaar verstuurd. Het eerste wordt ergens op internet weggegooid; het tweede komt aan.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"bytes 1–1460 (verloren)","Segment 2":"Segment 2","bytes 1461–2920":"bytes 1461–2920","Segment size":"Segmentgrootte","1,460 bytes (MSS)":"1,460 bytes (MSS)","2 SEGMENTS":"2 SEGMENTEN","seq=1 and seq=1461":"seq=1 en seq=1461","the first is lost":"het eerste raakt kwijt","SEGMENT 1 LOST":"SEGMENT 1 VERLOREN","A Gap Is Noticed":"Een gat valt op","Duplicate ACK with SACK":"Dubbele ACK met SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Bytes 1461–2920 komen aan, maar 1–1460 nooit. Een ACK kan alleen bytes tellen die op volgorde binnenkwamen, dus de laptop herhaalt meteen ACK 1 en voegt een SACK-blok toe dat zegt dat hij 1461–2920 al heeft.","1 (still waiting for byte 1)":"1 (wacht nog op byte 1)","holds bytes 1461–2920":"heeft bytes 1461–2920","At once, not delayed":"Meteen, niet uitgesteld","DUP ACK":"DUBBELE ACK","sack: has 1461–2920":"sack: heeft 1461–2920","Resend the Gap":"Het gat opnieuw sturen","Only the missing bytes":"Alleen de ontbrekende bytes","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"De SACK vertelt de server precies wat ontbreekt, dus hij stuurt alleen segment 1 opnieuw en de laptop bevestigt alles. Was er helemaal geen ACK teruggekomen, dan grepen timers in: een probe na ongeveer twee rondreizen, daarna een hertransmissie-timeout (minstens 200 ms op Linux).",Resent:"Opnieuw verstuurd","bytes 1–1460 only":"alleen bytes 1–1460","Next ACK":"Volgende ACK","2921 (everything)":"2921 (alles)","curl saw":"curl zag","Every byte, in order":"Elke byte, op volgorde",RESEND:"OPNIEUW","just the missing segment":"alleen het ontbrekende segment","Close Connection":"Verbinding sluiten","Each side says goodbye":"Elke kant neemt afscheid","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl is klaar, dus sluit hij af. Elke richting sluit apart: de laptop stuurt FIN en de server bevestigt die, daarna stuurt de server zijn eigen FIN en bevestigt de laptop die. De laptop bewaart de gegevens van de verbinding nog even (TIME-WAIT).","Closed by":"Gesloten door","A FIN from each side":"Een FIN van elke kant",Order:"Volgorde",Then:"Daarna","Laptop waits (TIME-WAIT)":"Laptop wacht (TIME-WAIT)",Data:"Data","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 bytes: het HTTP-antwoord, bytes 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 bytes: het HTTP-antwoord, bytes 1461–2920","has 1461–2920":"heeft 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Bytes die na het gat aankwamen, dus alleen het gat moet opnieuw.","Fast Datagrams":"Snelle datagrammen","Your voice":"Jouw stem","Their voice":"Hun stem","Media Server":"Mediaserver","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP verstuurt data in losse pakketten, datagrammen, zonder verbinding, bevestigingen of herhalingen. Daardoor blijft het snel en licht: goed voor spraak, video, games en DNS, waar een laat antwoord erger is dan een ontbrekend antwoord.",None:"Geen","None (no ACKs, no resends)":"Geen (geen ACK’s, niets opnieuw)",Ordering:"Volgorde","Not guaranteed":"Niet gegarandeerd","Call keeps flowing":"Gesprek loopt door","Fast, simple, no guarantees":"Snel, eenvoudig, geen garanties","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Het geluid begon met het allereerste pakket, elk datagram reisde op zichzelf en het verloren datagram was gewoon weg: UDP merkte niets. De app verborg het gat en het gesprek ging door. Druk op OPNIEUW om het nog eens te bekijken.",Datagrams:"Datagrammen","11 (1 lost, never resent)":"11 (1 verloren, nooit opnieuw)","Setup time":"Opzettijd","0 ms (no handshake)":"0 ms (geen handshake)","8 bytes (TCP: 20+)":"8 bytes (TCP: 20+)",Shown:"Getoond","The first 0.2 s of a call":"De eerste 0.2 s van een gesprek","Send Right Away":"Meteen versturen","No handshake, data goes first":"Geen handshake, data gaat eerst","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Een bel-app kent het adres en de poort van de mediaserver al van het aanmelden. Hij opent geen verbinding: het allereerste datagram draagt al 20 ms van je stem, achter een UDP-header van 8 bytes.",Setup:"Opzet",Ports:"Poorten","VOICE 1":"STEM 1","92 B of audio, no setup":"92 B audio, geen opzet","A Stream of Datagrams":"Een stroom datagrammen","One every 20 ms, each on its own":"Eén per 20 ms, elk op zichzelf","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"De app blijft elke 20 ms een datagram sturen. Elk staat op zichzelf, met een eigen header en geen band met de andere. UDP nummert ze niet en er komt niets terug om te bevestigen dat ze aankwamen.",Rate:"Tempo","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Nummering","None in UDP itself":"Geen in UDP zelf",Confirmation:"Bevestiging","None (no ACKs)":"Geen (geen ACK’s)","4 DATAGRAMS":"4 DATAGRAMMEN","voice frames 2–5":"spraakframes 2–5","each with its own 8-byte header":"elk met een eigen header van 8 bytes","Lost on the Way":"Onderweg verloren","Nobody resends it":"Niemand stuurt het opnieuw","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Frame 7 wordt ergens op internet weggegooid. De mediaserver vraagt er nooit om en UDP zegt het de laptop nooit: er zijn geen bevestigingen die kunnen ontbreken. De datagrammen erna komen gewoon aan.",Lost:"Verloren","Voice frame 7":"Spraakframe 7","Never (no ACKs)":"Nooit (geen ACK’s)",Missing:"Ontbreekt","20 ms of audio":"20 ms audio","3 DATAGRAMS":"3 DATAGRAMMEN","voice frames 6–8":"spraakframes 6–8","frame 7 is lost":"frame 7 raakt kwijt","FRAME 7 LOST · NOT RESENT":"FRAME 7 VERLOREN · NIET OPNIEUW","Replies Come Back":"Antwoorden komen terug","The other voice comes back":"De andere stem komt terug","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"De stem van de ander komt op dezelfde manier binnen, als losse datagrammen naar poort 50000. Ze komen erin omdat je router de uitgaande poort onthield toen hij je adres vertaalde (NAT).",Direction:"Richting","Independent of ours":"Los van de onze","Through NAT":"Door NAT","Router remembers the port":"Router onthoudt de poort","the other person’s voice":"de stem van de ander","sent to port 50000":"gestuurd naar poort 50000","The App Decides":"De app beslist","Reliability is up to the app":"Betrouwbaarheid is aan de app","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"De bel-app nummert zijn eigen frames (RTP doet dat), dus hij ziet dat frame 7 ontbreekt en strijkt het gat van 20 ms glad in plaats van te wachten. Wachten op een herhaling zou het hele gesprek laten haperen.","App’s job (e.g. RTP)":"Taak van de app (bv. RTP)",Loss:"Verlies","Hidden by the app":"Verborgen door de app","Also on UDP":"Ook op UDP","DNS, games, QUIC":"DNS, games, QUIC","APP COVERS THE 20 MS GAP":"APP VERBERGT HET GAT VAN 20 MS","RTP + audio":"RTP + audio","Version etc.":"Versie enz.","2, no padding, no extension, no CSRCs":"2, geen opvulling, geen extensie, geen CSRC’s","Marker, payload type":"Marker, payloadtype","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, afgesproken bij het opzetten van het gesprek)","Counts up by one per packet, so the app can spot a missing or late one.":"Telt per pakket één op, zodat de app een ontbrekend of laat pakket kan opmerken.",Timestamp:"Tijdstempel","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Audioklok op 48,000 per seconde: +960 per frame van 20 ms.","Identifies this audio stream.":"Identificeert deze audiostroom.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 bytes Opus-audio (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, afgesproken bij het opzetten van het gesprek)","Addressing & Routing":"Adressering en routering","Outgoing packet":"Uitgaand pakket",Reply:"Antwoord","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP geeft elk apparaat een adres en verplaatst pakketten van netwerk naar netwerk. Elke router kijkt alleen naar het bestemmingsadres om de volgende hop te kiezen. IP is ‘best effort’: het belooft geen aflevering of volgorde. TCP voegt die er bovenop toe.","Network (Layer 3)":"Netwerk (laag 3)",Address:"Adres","32 bits (IPv4), 128 (IPv6)":"32 bits (IPv4), 128 (IPv6)","20–60 bytes (IPv4)":"20–60 bytes (IPv4)","Lowered by 1 at each router":"Bij elke router 1 lager",Delivery:"Aflevering","Best effort":"Best effort","There and back":"Heen en terug","Twelve routers each way":"Twaalf routers per richting","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"De laptop stuurde het pakket naar zijn router, die zijn publieke adres erin zette. In totaal gaven twaalf routers het door op alleen het bestemmingsadres, en het antwoord vond op dezelfde manier de weg terug. Druk op OPNIEUW om het nog eens te bekijken.",Routers:"Routers","12 each way (1 home + 11)":"12 per richting (1 thuis + 11)","TTL at server":"TTL bij de server","116 (sent with 128)":"116 (verstuurd met 128)","Rewritten by NAT":"Herschreven door NAT","Source out, destination back":"Bron heen, bestemming terug","IPv4 (IPv6 works alike)":"IPv4 (IPv6 werkt net zo)","Local or Not?":"Lokaal of niet?","Compare the address with the subnet":"Vergelijk het adres met het subnet","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"De laptop is 192.168.1.10 met een /24-masker, dus zijn eigen netwerk loopt van 192.168.1.0 tot 192.168.1.255. De server, 203.0.113.10, valt daarbuiten, dus het pakket moet naar de standaardgateway: de thuisrouter.",Laptop:"Laptop","Local range":"Lokaal bereik",Gateway:"Gateway","203.0.113.10 IS NOT LOCAL":"203.0.113.10 IS NIET LOKAAL","Find the Router":"Vind de router","ARP turns an IP into a MAC":"ARP maakt van een IP een MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Op het lokale netwerk worden frames afgeleverd op MAC-adres. Staat de MAC van de router niet in de ARP-cache van de laptop, dan roept die naar iedereen ‘wie heeft 192.168.1.1?’ en antwoordt de router met zijn MAC-adres.",Asks:"Vraagt","Who has 192.168.1.1?":"Wie heeft 192.168.1.1?","Sent to":"Gestuurd naar","Everyone (broadcast)":"Iedereen (broadcast)",Learns:"Leert","Router’s MAC address":"MAC-adres van de router","ARP REQUEST":"ARP-VERZOEK","who has 192.168.1.1?":"wie heeft 192.168.1.1?","tell 192.168.1.10":"meld aan 192.168.1.10","ARP REPLY":"ARP-ANTWOORD","Send the Packet":"Het pakket versturen","Addresses, TTL and protocol":"Adressen, TTL en protocol","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"De IP-header draagt het bron- en bestemmingsadres, een TTL en het protocol dat erin zit. Hier is dat een TCP SYN naar poort 443. Windows begint de TTL bij 128 (Linux en macOS gebruiken 64).","From → to":"Van → naar","IP PACKET":"IP-PAKKET","TTL 128 · protocol TCP":"TTL 128 · protocol TCP","NAT, Then Hop by Hop":"NAT, dan hop voor hop","The router rewrites and forwards":"De router herschrijft en stuurt door","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"De router vervangt de privébron door zijn publieke adres 198.51.100.7 (en hier poort 52344 door 40112), noteert de koppeling en verlaagt de TTL naar 127. Daarna kiezen 11 routers op internet elk de volgende hop op bestemming en verlagen de TTL opnieuw.","New source":"Nieuwe bron","Leaves home":"Verlaat het huis","At the server":"Bij de server","TTL 116 (11 more hops)":"TTL 116 (nog 11 hops)","TTL 127 · after NAT":"TTL 127 · na NAT","ARRIVED WITH TTL 116":"AANGEKOMEN MET TTL 116","The Reply Comes Back":"Het antwoord komt terug","NAT translates it for the laptop":"NAT vertaalt het voor de laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"De server antwoordt aan het adres dat hij zag, 198.51.100.7:40112. De router zoekt dat op in zijn NAT-tabel, herschrijft de bestemming terug naar 192.168.1.10:52344 en geeft het door. Het antwoord begon met TTL 64 en komt aan met 52.","Delivered to":"Afgeleverd bij","64 → 52 (12 routers)":"64 → 52 (12 routers)",REPLY:"ANTWOORD","TTL 52 · after NAT":"TTL 52 · na NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (na NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (na NAT)","ARP request · 28 bytes":"ARP-verzoek · 28 bytes","Broadcast: every device on the network receives it.":"Broadcast: elk apparaat op het netwerk ontvangt het.","The sender’s network card.":"De netwerkkaart van de afzender.","Hardware type":"Hardwaretype","1 (Ethernet)":"1 (Ethernet)","Protocol type":"Protocoltype","Address sizes":"Adresgroottes",Operation:"Bewerking","1 (request: who has …?)":"1 (verzoek: wie heeft …?)","Sender MAC":"MAC van afzender","Sender IP":"IP van afzender","Target MAC":"Doel-MAC","All zeros: this is what the request wants to find out.":"Allemaal nullen: dit wil het verzoek juist te weten komen.","Target IP":"Doel-IP","ARP reply · 28 bytes":"ARP-antwoord · 28 bytes","Straight back to the device that asked.":"Direct terug naar het apparaat dat het vroeg.","2 (reply: … is at …)":"2 (antwoord: … zit op …)","Seen as it leaves the router’s internet side":"Gezien terwijl het de internetkant van de router verlaat","The internet provider’s router, the next hop.":"De router van de internetprovider, de volgende hop.","The router’s internet-facing port.":"De poort van de router aan de internetkant.","As sent: this system starts at 64.":"Zoals verstuurd: dit systeem begint bij 64.","The router’s NAT swapped in its own port for the laptop’s.":"De NAT van de router zette zijn eigen poort in plaats van die van de laptop.","The sender’s next router; each hop puts the packet in a new frame.":"De volgende router van de afzender; elke hop stopt het pakket in een nieuw frame.","Name Resolution":"Naamresolutie",Query:"Vraag",Referral:"Verwijzing","DNSSEC not requested here":"DNSSEC hier niet gevraagd","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS zet namen als www.example.com om in de IP-adressen waarmee computers elkaar bereiken. Geen enkele server kent elke naam: het systeem is een hiërarchie van servers, en antwoorden worden onderweg in caches bewaard, zodat de meeste opzoekingen nooit ver hoeven.","53, UDP (TCP if large)":"53, UDP (TCP als het groot is)",Turns:"Zet om","Names into IP addresses":"Namen in IP-adressen",Hierarchy:"Hiërarchie","Root → TLD → authoritative":"Root → TLD → gezaghebbend",Caching:"Caching","For each record’s TTL":"Voor de TTL van elk record","Name resolved":"Naam opgelost","And remembered for an hour":"En een uur onthouden","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Vanuit een lege cache liep de resolver van de root naar .com naar de eigen server van example.com, en antwoordde daarna de laptop. Tot de TTL afloopt, wordt de volgende opzoeking van deze naam rechtstreeks uit een cache beantwoord. Druk op OPNIEUW om het nog eens te bekijken.",Queries:"Vragen","4 (laptop 1, resolver 3)":"4 (laptop 1, resolver 3)","Cached for":"In cache voor","Ask the Resolver":"Vraag de resolver","The laptop hands the question off":"De laptop geeft de vraag door","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"De browser heeft het IP-adres van www.example.com nodig en noch hij noch Windows heeft het in de cache. De laptop stuurt één vraag naar de recursieve resolver die hij kreeg, 8.8.8.8, en vraagt die de hele opzoeking te doen (recursie gewenst).","www.example.com, type A":"www.example.com, type A",Asked:"Gevraagd aan","8.8.8.8 (recursive)":"8.8.8.8 (recursief)","RD (recursion desired)":"RD (recursie gewenst)","flags: RD":"vlaggen: RD","Points the way to .com":"Wijst de weg naar .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"De cache van de resolver is leeg (hij is net gestart), dus hij begint bovenaan. Een rootserver kent het adres niet, maar weet welke servers .com afhandelen en antwoordt met een verwijzing. Veel resolvers sturen hem alleen ‘com’, niet de volledige naam.","Root servers":"Rootservers","13 names, 1,000+ anycast sites":"13 namen, 1,000+ anycastlocaties","Referral (13 .com servers)":"Verwijzing (13 .com-servers)","NOT IN CACHE":"NIET IN CACHE",REFERRAL:"VERWIJZING","no answer: ask .com":"geen antwoord: vraag .com","Points the way to example.com":"Wijst de weg naar example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"De resolver vraagt een van de .com-servers. Die bewaren ook niet de adressen van elke site, maar weten welke nameservers elk .com-domein gebruikt, dus dit antwoord is weer een verwijzing, met de adressen van die servers (glue) erbij.",Knows:"Kent","Name servers of .com domains":"Nameservers van .com-domeinen","Referral + glue addresses":"Verwijzing + glue-adressen","no answer: ask example.com":"geen antwoord: vraag example.com","Gives the actual answer":"Geeft het echte antwoord","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Ten slotte vraagt de resolver de eigen nameserver van example.com, die de records van het domein bewaart. Die antwoordt met het A-record en markeert het antwoord als gezaghebbend. De eigenaar van het domein bepaalt hoelang het in de cache mag: hier 3600 seconden.","AA (authoritative), TTL 3600":"AA (gezaghebbend), TTL 3600",ANSWER:"ANTWOORD","TTL 3600 · flag AA":"TTL 3600 · vlag AA","Answer & Cache":"Antwoord en cache","The laptop gets its address":"De laptop krijgt zijn adres","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"De resolver stuurt het antwoord terug naar de laptop en houdt een kopie. Het komende uur kan hij deze naam meteen beantwoorden, en daarom duurde de opzoeking in de HTTP-les maar 24 ms. De laptop bewaart het ook in de cache.","RD, RA (recursion available)":"RD, RA (recursie beschikbaar)","Cached by":"In cache bij","Resolver and laptop":"Resolver en laptop","flags: RD RA":"vlaggen: RD RA","CACHED · TTL 3600 S":"IN CACHE · TTL 3600 S","Referral: com. NS ×13 (with glue)":"Verwijzing: com. NS ×13 (met glue)","Referral: example.com. NS ×2 (with glue)":"Verwijzing: example.com. NS ×2 (met glue)","Response A 203.0.113.10 (authoritative)":"Antwoord A 203.0.113.10 (gezaghebbend)","As sent: this system starts at 128.":"Zoals verstuurd: dit systeem begint bij 128.","0x0000: query":"0x0000: vraag","UDP size 1232, DNSSEC OK = 0":"UDP-grootte 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Zegt hoe groot een UDP-antwoord mag zijn. DNSSEC-handtekeningen worden hier niet gevraagd om de les kort te houden; een validerende resolver als 8.8.8.8 vraagt er wel om.","0x8000: response":"0x8000: antwoord",Authority:"Autoriteit",Additional:"Extra","0x8400: response, AA (authoritative)":"0x8400: antwoord, AA (gezaghebbend)","Getting an Address":"Een adres krijgen","From the laptop":"Van de laptop","From the DHCP server":"Van de DHCP-server","No IP address":"Geen IP-adres","192.168.1.1 · DHCP server":"192.168.1.1 · DHCP-server","Dynamic Host Configuration Protocol":"Dynamic Host Configuration Protocol","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP geeft een apparaat alles wat het nodig heeft om een netwerk te gebruiken: een IP-adres, het subnetmasker, de router waarlangs verkeer gaat en de DNS-servers om te vragen. Adressen worden voor een vaste tijd uitgeleend en verlengd zolang het apparaat op het netwerk blijft.","UDP 67 (server), 68 (client)":"UDP 67 (server), 68 (client)","Hands out":"Deelt uit","IP, mask, gateway, DNS":"IP, masker, gateway, DNS",Exchange:"Uitwisseling",Lease:"Lease","Renewed at half its time":"Verlengd op de helft van de tijd","On the network":"Op het netwerk","Leased, and kept up to date":"Geleased, en bijgehouden","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Vier berichten brachten de laptop van geen adres naar een werkende configuratie, en halverwege de lease van 24 uur verlengde hij die met een direct verzoek aan de router. Druk op OPNIEUW om het nog eens te bekijken.",Messages:"Berichten","4 to join, 2 per renewal":"4 om mee te doen, 2 per verlenging","24 h, renewed at 12 h":"24 h, verlengd na 12 h","No Address Yet":"Nog geen adres","The laptop joins the network":"De laptop komt op het netwerk","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"De laptop is net verbonden. Hij heeft een ingebouwd MAC-adres, maar geen IP-adres, geen gateway en geen DNS-server, dus hij kan nog met niets buiten zijn eigen netwerk praten. Hij vraagt erom met DHCP.","IP address":"IP-adres","None (uses 0.0.0.0)":"Geen (gebruikt 0.0.0.0)","MAC address":"MAC-adres",Needs:"Heeft nodig","NO IP ADDRESS YET":"NOG GEEN IP-ADRES",Discover:"Discover","Shout to the whole network":"Roep naar het hele netwerk","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Zonder eigen adres stuurt de laptop vanaf 0.0.0.0 naar het broadcastadres 255.255.255.255, zodat elk apparaat op het lokale netwerk het ontvangt. Alleen DHCP-servers antwoorden.",From:"Van","0.0.0.0, UDP port 68":"0.0.0.0, UDP-poort 68","255.255.255.255, port 67":"255.255.255.255, poort 67",Carries:"Bevat","MAC, transaction ID":"MAC, transactie-ID","any DHCP server out there?":"is daar een DHCP-server?",Offer:"Offer","The router proposes an address":"De router stelt een adres voor","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"De DHCP-server van de router kiest een vrij adres en biedt het aan met de rest van de instellingen. De laptop kan nog geen IP-adres gebruiken, dus het aanbod gaat rechtstreeks naar zijn MAC-adres (sommige clients vragen in plaats daarvan om een broadcast).",Offered:"Aangeboden","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"aanbod: 192.168.1.10/24","gateway, DNS, lease 24 h":"gateway, DNS, lease 24 h","Accept, out loud":"Hardop accepteren","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"De laptop vraagt om het aangeboden adres en noemt de server die hij koos. Hij broadcast nog steeds, zodat elke andere DHCP-server die een aanbod deed weet dat hij niet gekozen is en zijn adres kan vrijgeven.",Requests:"Vraagt om","Chosen server":"Gekozen server","I’ll take 192.168.1.10":"ik neem 192.168.1.10","from server 192.168.1.1":"van server 192.168.1.1",Acknowledge:"Bevestigen","The address is the laptop’s":"Het adres is van de laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"De server bevestigt, en de laptop stelt zijn adres, masker, gateway en DNS-server in. Veel systemen controleren eerst met ARP dat geen ander apparaat het adres al gebruikt.","DNS server":"DNS-server","192.168.1.10 is yours":"192.168.1.10 is van jou","for 24 hours":"voor 24 uur","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · LEASE 24 H",Renew:"Verlengen","Halfway through the lease":"Halverwege de lease","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Twaalf uur later is de helft van de lease voorbij. De laptop heeft nu een adres, dus hij vraagt de router direct de lease te verlengen, en de router zet die terug op 24 uur. Als de router niet antwoordde, zou hij bij 87.5% broadcasten.",When:"Wanneer","50% of lease (T1 = 12 h)":"50% van de lease (T1 = 12 h)","The router (unicast)":"De router (unicast)","If unanswered":"Zonder antwoord","Broadcast at 87.5% (T2)":"Broadcast bij 87.5% (T2)","renew 192.168.1.10":"verleng 192.168.1.10","sent straight to 192.168.1.1":"rechtstreeks naar 192.168.1.1","lease renewed":"lease verlengd","another 24 hours":"nog eens 24 uur",Message:"Bericht","1 (request, from a client)":"1 (verzoek, van een client)",Hardware:"Hardware","Ethernet, 6-byte addresses":"Ethernet, adressen van 6 bytes",Hops:"Hops","Chosen by the client; every reply repeats it.":"Gekozen door de client; elk antwoord herhaalt het.",Seconds:"Seconden","0x0000 (unicast replies are fine)":"0x0000 (unicast-antwoorden zijn prima)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Broadcastvlag uit: de server mag rechtstreeks naar het MAC-adres van de client sturen.","Client address":"Clientadres","Filled in only when the client already has an address (renewing).":"Alleen ingevuld als de client al een adres heeft (verlengen).","Your address":"Jouw adres","The address the server is giving out.":"Het adres dat de server uitdeelt.","Next server":"Volgende server","Relay agent":"Relay-agent","Client MAC":"Client-MAC","Server name, boot file":"Servernaam, opstartbestand",empty:"leeg","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Markeert de opties die volgen als DHCP.","Message type: 1 (Discover)":"Berichttype: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Client-ID: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Hostnaam: alice-laptop","Vendor class: MSFT 5.0":"Leveranciersklasse: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Gevraagde parameters: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252",End:"Einde","2 (reply, from a server)":"2 (antwoord, van een server)","Message type: 2 (Offer)":"Berichttype: 2 (Offer)","Server identifier: 192.168.1.1":"Server-ID: 192.168.1.1","Lease time: 86,400 s (24 h)":"Leasetijd: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Verlengtijd (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Herbindtijd (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Subnetmasker: 255.255.255.0","Broadcast address: 192.168.1.255":"Broadcastadres: 192.168.1.255","Router: 192.168.1.1":"Router: 192.168.1.1","DNS server: 8.8.8.8":"DNS-server: 8.8.8.8","Message type: 3 (Request)":"Berichttype: 3 (Request)","Requested address: 192.168.1.10":"Gevraagd adres: 192.168.1.10","Client FQDN: alice-laptop":"Client-FQDN: alice-laptop","Message type: 5 (ACK)":"Berichttype: 5 (ACK)","Network Diagnostics":"Netwerkdiagnose","Ping / probe":"Ping / probe","Echo reply":"Echo-antwoord","Error report":"Foutmelding","Internet Control Message Protocol":"Internet Control Message Protocol","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP is hoe het netwerk terugmeldt: een router zegt dat de tijd van een pakket op is, een server zegt dat er niets op een poort luistert. Tools als ping en traceroute zijn uit deze berichten opgebouwd. Het reist binnen IP, maar draagt geen applicatiedata.","Carried in":"Vervoerd in","IP (protocol 1)":"IP (protocol 1)","A type and a code":"Een type en een code",Tools:"Tools",Often:"Vaak","Filtered by firewalls":"Gefilterd door firewalls","The network answered":"Het netwerk antwoordde","Replies, expiries and errors":"Antwoorden, verlopen en fouten","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Een echo-verzoek mat de rondreis, pakketten met een kleine TTL lieten elke router op het pad zich bekendmaken, en een gesloten poort werd meteen teruggemeld. Druk op OPNIEUW om het nog eens te bekijken.","Round trip":"Rondreis",Path:"Pad","12 routers, server at hop 13":"12 routers, server bij hop 13","Types used":"Gebruikte types","8, 0, 11 and 3":"8, 0, 11 en 3","Reply TTL":"TTL van antwoord","52 (64 − 12 routers)":"52 (64 − 12 routers)",Ping:"Ping","Echo request":"Echo-verzoek","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"‘ping -n 1 203.0.113.10’ stuurt één ICMP-echo-verzoek (gewoon ping stuurt er vier, een seconde uit elkaar): type 8, code 0, met een identificatie, een volgnummer en 32 bytes opvulling. Het systeem van de server antwoordt zelf, er is geen applicatie nodig.","Type, code":"Type, code","8, 0 (echo request)":"8, 0 (echo-verzoek)","32 bytes (Windows)":"32 bytes (Windows)","ECHO REQUEST":"ECHO-VERZOEK","type 8 · seq 1":"type 8 · seq 1","32 bytes of data":"32 bytes data","Echo Reply":"Echo-antwoord","Round-trip time":"Rondreistijd","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"De server stuurt een echo-antwoord terug, type 0, met dezelfde identificatie, hetzelfde volgnummer en dezelfde data. Ping toont de tijd die het duurde en de TTL waarmee het antwoord binnenkwam: ‘bytes=32 time=34ms TTL=52’.","0, 0 (echo reply)":"0, 0 (echo-antwoord)","TTL on arrival":"TTL bij aankomst","ECHO REPLY":"ECHO-ANTWOORD","type 0 · seq 1":"type 0 · seq 1","same 32 bytes back":"dezelfde 32 bytes terug","TIME=34MS TTL=52":"TIME=34MS TTL=52","The first router answers":"De eerste router antwoordt","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"‘ping -n 1 -i 1’ stuurt hetzelfde verzoek met een TTL van 1. De thuisrouter verlaagt die naar 0, moet het pakket dus weggooien, en stuurt een Time Exceeded-bericht terug vanaf zijn eigen adres: ‘Reply from 192.168.1.1: TTL expired in transit.’","Sent with":"Verstuurd met","Dropped by":"Weggegooid door","11, 0 (time exceeded)":"11, 0 (tijd verlopen)","echo request":"echo-verzoek","expires at the first router":"verloopt bij de eerste router","TIME EXCEEDED":"TIJD VERLOPEN","type 11 · from 192.168.1.1":"type 11 · van 192.168.1.1","quotes the dropped header":"citeert de weggegooide header","The next router answers":"De volgende router antwoordt","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Met ‘-i 2’ verlaagt de thuisrouter de TTL naar 1 en stuurt het door. De eerste router bij de internetprovider verlaagt hem naar 0 en meldt terug vanaf 198.51.100.1. De thuisrouter vertaalt de melding terug naar de laptop zoals elk antwoord.","ISP router 198.51.100.1":"Providerrouter 198.51.100.1","expires at the second router":"verloopt bij de tweede router","HOP 2 · 198.51.100.1":"HOP 2 · 198.51.100.1","type 11 · from 198.51.100.1":"type 11 · van 198.51.100.1","That’s Traceroute":"Dat is traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … tot het aankomt","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert automatiseert dit: hij verhoogt de TTL telkens met één, stuurt drie probes per hop en toont wie terugmeldt. Hops 3 tot en met 12 werken net zo, en met TTL 13 bereikt het verzoek eindelijk de server, die gewoon antwoordt.","12 routers, then the server":"12 routers, dan de server","Per hop":"Per hop","3 probes":"3 probes","On Linux":"Op Linux","traceroute sends UDP":"traceroute stuurt UDP","enough hops to arrive":"genoeg hops om aan te komen","the server itself answers":"de server zelf antwoordt","end of the route":"einde van de route",Unreachable:"Onbereikbaar","Nothing listening on that port":"Niets luistert op die poort","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Een app stuurt een UDP-datagram naar poort 9999, waar niets luistert. De server kan het niet afleveren en antwoordt met Destination Unreachable, code 3 (poort onbereikbaar), met het begin van het datagram erin. Veel firewalls gooien zulke pakketten in plaats daarvan stil weg.","3, 3 (port unreachable)":"3, 3 (poort onbereikbaar)","Other codes":"Andere codes","0 net, 1 host, 4 too big":"0 net, 1 host, 4 te groot",Firewalls:"Firewalls","Often silent instead":"Vaak in plaats daarvan stil","to port 9999":"naar poort 9999","nothing listening there":"daar luistert niets",UNREACHABLE:"ONBEREIKBAAR","type 3 · code 3":"type 3 · code 3","port unreachable":"poort onbereikbaar","ICMP · Echo request":"ICMP · Echo-verzoek",Code:"Code","Covers the whole ICMP message.":"Dekt het hele ICMP-bericht.",Identifier:"Identificatie","Matches replies to this ping program.":"Koppelt antwoorden aan dit pingprogramma.","Windows counts up across every ping it sends.":"Windows telt op over elke ping die het stuurt.",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)',"Windows ping’s filler: the alphabet, a to w, then again.":"De opvulling van Windows-ping: het alfabet, a tot w, en dan opnieuw.","ICMP · Echo reply":"ICMP · Echo-antwoord","Sent back exactly as it came.":"Precies teruggestuurd zoals het kwam.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Tijd verlopen (TTL bereikte 0)","Time exceeded (TTL reached 0)":"Tijd verlopen (TTL bereikte 0)",Unused:"Ongebruikt","Original packet":"Oorspronkelijk pakket","Its source, destination":"De bron en bestemming ervan","its IP header and first 8 bytes (28 bytes)":"de IP-header en de eerste 8 bytes (28 bytes)","App data":"App-data",'"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 bytes)',"What the app sent; nothing on the server is listening for it.":"Wat de app stuurde; niets op de server luistert ernaar.","ICMP · Destination unreachable (port unreachable)":"ICMP · Bestemming onbereikbaar (poort onbereikbaar)","Destination unreachable (port unreachable)":"Bestemming onbereikbaar (poort onbereikbaar)","Sending Email":"E-mail versturen","SMTP command":"SMTP-opdracht","SMTP reply":"SMTP-antwoord","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP verplaatst e-mail: van je mailapp naar de server van je provider, en van die server naar die van de ontvanger. Het is een gesprek van korte tekstopdrachten, elk beantwoord met een antwoordcode van drie cijfers. Mail lezen is een andere taak, gedaan met IMAP of POP3.","465/587 submit, 25 relay":"465/587 indienen, 25 relay","TCP, usually with TLS":"TCP, meestal met TLS",Commands:"Opdrachten",Replies:"Antwoorden","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx ga door, 4/5xx fout","Mail delivered":"Mail afgeleverd","Two hops, one message":"Twee hops, één bericht","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Alice’ app gaf het bericht aan haar provider via een versleutelde, aangemelde verbinding. De provider vond Bobs mailserver in DNS en stuurde het daarheen, waarbij die verbinding naar TLS werd opgewaardeerd. Het wacht nu in Bobs mailbox tot hij het leest met IMAP of POP3.","Laptop → provider → Bob’s":"Laptop → provider → Bob",Submission:"Indienen","Port 465, TLS, login":"Poort 465, TLS, aanmelden",Relay:"Relay","Port 25, STARTTLS":"Poort 25, STARTTLS","Checks at Bob’s":"Controles bij Bob","Connect Securely":"Veilig verbinden","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice drukt op Verzenden. Haar mailapp verbindt met de indieningsserver van haar provider, smtp.example.com, op poort 465. Op deze poort start TLS meteen, dus het hele SMTP-gesprek, inclusief haar wachtwoord, is versleuteld.","TLS from the start":"TLS vanaf het begin","SMTP inside TLS":"SMTP in TLS","Greeting & Login":"Begroeting en aanmelden","EHLO, then AUTH":"EHLO, dan AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"De server begroet met code 220. De app zegt EHLO en de server somt op wat hij ondersteunt, waaronder AUTH. De app meldt zich aan met AUTH PLAIN (gebruikersnaam en wachtwoord, base64-gecodeerd) en krijgt 235: aangemeld.",Greeting:"Begroeting",Capabilities:"Mogelijkheden","Login result":"Resultaat aanmelden","user and password, base64":"gebruiker en wachtwoord, base64","Send the Message":"Het bericht versturen","Envelope, then content":"Envelop, dan inhoud","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM en RCPT TO vormen de envelop: afzender en ontvanger. Met PIPELINING passen alle drie de opdrachten in één pakket. Na 354 komt het bericht, afgesloten met een regel met alleen een punt.",Envelope:"Envelop","Content ends":"Inhoud eindigt","A line with only “.”":"Een regel met alleen ‘.’",Result:"Resultaat",MESSAGE:"BERICHT","… message …":"… bericht …","250 QUEUED":"250 IN WACHTRIJ","Find Bob’s Server":"Bobs server vinden","An MX lookup in DNS":"Een MX-opzoeking in DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Alice’ provider moet nu afleveren bij example.org. Hij vraagt DNS om het MX-record van dat domein, dat de server noemt die de mail aanneemt, en zoekt daarna het adres van die server op.","MX record":"MX-record","Asked by":"Gevraagd door","Alice’s provider":"Alice’ provider","Server to Server":"Server naar server","Port 25, upgraded with STARTTLS":"Poort 25, opgewaardeerd met STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"De provider verbindt met mx.example.org op poort 25. Dit gesprek begint onversleuteld: de begroeting en het EHLO-antwoord bieden STARTTLS aan, de provider vraagt erom, krijgt 220 en beide kanten schakelen over op TLS.","Starts as":"Begint als","Plain text":"Platte tekst",Upgrade:"Opwaarderen",Deliver:"Afleveren","The same transaction again":"Dezelfde transactie nog eens","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Met TLS aan herhaalt de provider EHLO, dan de envelop en het bericht, nu met een DKIM-handtekening en een Received-header erbij. Bobs server controleert SPF, DKIM en DMARC en neemt het aan.","Login needed":"Aanmelden nodig","No (server to server)":"Nee (server naar server)","1,316 bytes (signed)":"1,316 bytes (ondertekend)","IN BOB’S MAILBOX":"IN BOBS MAILBOX","Server Hello + encrypted handshake, 2 segments":"Server Hello + versleutelde handshake, 2 segmenten","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 mogelijkheden (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (inloggegevens)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (gepipelined)","Message (316 bytes), then “.”":"Bericht (316 bytes), dan ‘.’","250 capabilities (PIPELINING, STARTTLS …)":"250 mogelijkheden (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 mogelijkheden (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Bericht (1,316 bytes), dan ‘.’","What this client supports. Its exact contents vary from client to client; this is an example.":"Wat deze client ondersteunt. De precieze inhoud verschilt per client; dit is een voorbeeld.","up to 512 bytes":"tot 512 bytes","The server’s choices and its key share.":"De keuzes van de server en zijn sleuteldeel.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (de keten), Certificate Verify (de handtekening), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Het bericht van Alice (316 bytes), dan een regel met alleen ‘.’","example.org, type MX, class IN":"example.org, type MX, klasse IN","mx.example.org, type A, class IN":"mx.example.org, type A, klasse IN",Timestamps:"Tijdstempels","Used to measure round trips; both sides offered them.":"Gebruikt om rondreizen te meten; beide kanten boden ze aan.","The signed message (1,316 bytes), then a line holding only “.”":"Het ondertekende bericht (1,316 bytes), dan een regel met alleen ‘.’","Downloading Email":"E-mail downloaden","POP3 command":"POP3-opdracht","POP3 reply":"POP3-antwoord","Post Office Protocol, version 3":"Post Office Protocol, versie 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"Met POP3 downloadt een mailapp berichten uit een mailbox op een server. Het is bedoeld voor één apparaat dat mail ophaalt en daarna van de server verwijdert. Opdrachten zijn korte woorden, en elk antwoord begint met +OK of -ERR.",Model:"Model","Download, then delete":"Downloaden, dan verwijderen","+OK or -ERR":"+OK of -ERR","Mail downloaded":"Mail gedownload","And gone from the server":"En weg van de server","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Bobs app meldde zich aan, zag twee berichten, downloadde het eerste en verwijderde het, wat de server bij QUIT uitvoerde. Dat bericht staat nu alleen nog op deze laptop, en daarom past POP3 bij één apparaat en IMAP bij meerdere.","2 waiting, 1 downloaded":"2 wachtend, 1 gedownload",Deleted:"Verwijderd","At QUIT (UPDATE state)":"Bij QUIT (UPDATE-status)","Best for":"Ideaal voor","A single device":"Eén apparaat","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Bobs mailapp verbindt met pop.example.org op poort 995, waar TLS meteen start. Daarbinnen begroet de server met +OK. (Op poort 110 begint de sessie onversleuteld en wordt ze opgewaardeerd met de opdracht STLS.)","Log In":"Aanmelden","USER, then PASS":"USER, dan PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"De app stuurt de gebruikersnaam met USER en het wachtwoord met PASS. Elke opdracht krijgt een eigen +OK. Omdat de sessie in TLS zit, is het wachtwoord onderweg niet leesbaar.","Protected by":"Beschermd door","Check the Mailbox":"De mailbox bekijken","STAT and LIST":"STAT en LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT geeft het aantal berichten en hun totale grootte: 2 berichten, 5120 bytes. LIST geeft van elk bericht het nummer en de grootte, afgesloten met een regel met alleen een punt.","Message 1":"Bericht 1","Message 2":"Bericht 2",Download:"Downloaden","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 vraagt om het eerste bericht. De server antwoordt +OK met de grootte, dan het bericht en een afsluitende punt: 1904 bytes plus de antwoordregel, twee TCP-segmenten.",Command:"Opdracht","Delete & Quit":"Verwijderen en afsluiten","Deleted only at QUIT":"Pas verwijderd bij QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 markeert het bericht alleen. De server verwijdert het wanneer de app QUIT zegt: viel de verbinding eerder weg, dan zou er niets verwijderd worden. Veel apps bieden ‘kopie op de server laten staan’, wat DELE overslaat.","Marks message 1":"Markeert bericht 1",Removed:"Verwijderd","At QUIT":"Bij QUIT",Option:"Optie","Leave a copy on server":"Kopie op server laten staan","MESSAGE 1 DELETED":"BERICHT 1 VERWIJDERD","PASS (password)":"PASS (wachtwoord)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, bericht, ‘.’ (2 segmenten)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, het bericht van 1,904 bytes, dan een regel met alleen ‘.’","IMAP command":"IMAP-opdracht","IMAP response":"IMAP-antwoord","Internet Message Access Protocol":"Internet Message Access Protocol","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"Met IMAP werken mailapps met een mailbox die op de server blijft. Mappen, markeringen voor gelezen en gemarkeerd en verwijderingen worden daar bewaard, zodat een telefoon, een laptop en webmail allemaal dezelfde mailbox zien. De server kan een app ook nieuwe mail melden zodra die binnenkomt.","Mail stays on the server":"Mail blijft op de server",Syncs:"Synchroniseert","Folders and flags":"Mappen en markeringen","Mailbox in sync":"Mailbox in sync","Read once, read everywhere":"Eén keer gelezen, overal gelezen","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Bobs app opende zijn inbox en las een bericht, dat daardoor op de server voor al zijn apparaten \\Seen werd, en wachtte daarna met IDLE tot de server nieuwe mail meldde. Er werd niets verwijderd: de server bewaart nog alles.","2, then 3 (new mail)":"2, dan 3 (nieuwe mail)","Read mark":"Gelezen-markering","\\Seen, stored on server":"\\Seen, bewaard op server","New mail":"Nieuwe mail","Pushed during IDLE":"Gepusht tijdens IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Bobs app verbindt met imap.example.org op poort 993, waar TLS meteen start. De server begroet met een regel ‘* OK’ zonder tag die ook zijn mogelijkheden opsomt, zoals IDLE.","Commands carry tags":"Opdrachten hebben tags","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Elke opdracht begint met een tag die de app kiest, zoals a1, en de server sluit zijn antwoord af met dezelfde tag. Zo kunnen meerdere opdrachten tegelijk lopen en wordt elk antwoord gekoppeld. Regels die met * beginnen zijn data zonder tag.",Tags:"Tags","Match replies to commands":"Koppelen antwoorden aan opdrachten","Open the Inbox":"De inbox openen","SELECT a folder":"SELECT een map","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX opent de map. De server meldt het aantal berichten, de markeringen die hij ondersteunt en het eerste ongelezen bericht, en bevestigt dan dat de map open is voor lezen en schrijven.","First unread":"Eerste ongelezen",Access:"Toegang","Read a Message":"Een bericht lezen","FETCH, and the \\Seen flag":"FETCH en de markering \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] downloadt bericht 2 (drie TCP-segmenten). Dat zet de markering \\Seen op de server, zodat het ook op Bobs telefoon als gelezen staat, en het bericht blijft daar.","Flag set":"Markering gezet","\\Seen (on the server)":"\\Seen (op de server)","STILL ON SERVER · \\SEEN":"NOG OP SERVER · \\SEEN","Wait for New Mail":"Wachten op nieuwe mail","IDLE: the server pushes":"IDLE: de server pusht","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE zegt tegen de server ‘laat het weten als er iets verandert’. Zo’n 42 seconden later komt het bericht van Alice binnen en pusht de server meteen ‘* 3 EXISTS’. De app beëindigt IDLE met DONE en kan de nieuwe mail ophalen.","Server says":"Server zegt","* 3 EXISTS (new mail)":"* 3 EXISTS (nieuwe mail)","Ended by":"Beëindigd door","NEW MAIL ARRIVED":"NIEUWE MAIL ONTVANGEN","a1 LOGIN (user and password)":"a1 LOGIN (gebruiker en wachtwoord)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, het bericht van 3,216 bytes, dan a3 OK FETCH completed","Transferring Files":"Bestanden overzetten","FTP command":"FTP-opdracht","FTP reply":"FTP-antwoord","File data":"Bestandsdata","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP verplaatst bestanden tussen een client en een server. Het is ongewoon doordat het twee TCP-verbindingen gebruikt: één voor opdrachten en antwoorden, en een nieuwe voor elk bestand of elke lijst. Het stamt uit het begin van de jaren 70 en stuurt alles, wachtwoorden inbegrepen, als platte tekst.","21 control, data varies":"21 besturing, data wisselt",Connections:"Verbindingen","Control + one per transfer":"Besturing + één per overdracht",Encryption:"Versleuteling","None (plain text)":"Geen (platte tekst)","Safer options":"Veiligere opties","SFTP, or FTPS (FTP + TLS)":"SFTP, of FTPS (FTP + TLS)","File downloaded":"Bestand gedownload","Two connections, no encryption":"Twee verbindingen, geen versleuteling","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Opdrachten gingen over de besturingsverbinding, het bestand over een eigen dataverbinding, en het sluiten van die verbinding markeerde het einde van het bestand. Iedereen onderweg had het wachtwoord en het bestand kunnen lezen, en daarom gebruikt men nu SFTP of FTPS.","2 (control + data)":"2 (besturing + data)",File:"Bestand","4,000 bytes, 3 segments":"4,000 bytes, 3 segmenten",Password:"Wachtwoord","Sent in plain text":"Als platte tekst verstuurd","Use instead":"Gebruik liever","SFTP or FTPS":"SFTP of FTPS","Control Connection":"Besturingsverbinding","Port 21, plain text":"Poort 21, platte tekst","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"De FTP-app opent een TCP-verbinding naar ftp.example.com op poort 21. Deze besturingsverbinding draagt opdrachten en antwoorden voor de hele sessie. De server begroet met 220. Net als bij SMTP begint elk antwoord met een code van drie cijfers.","USER and PASS, readable by anyone":"USER en PASS, leesbaar voor iedereen","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"De app stuurt USER, de server vraagt met 331 om het wachtwoord, en PASS stuurt het. Niets is versleuteld, dus gebruikersnaam en wachtwoord gaan als leesbare tekst over elk netwerk onderweg.","Visible to":"Zichtbaar voor","Anyone on the path":"Iedereen onderweg","PASSWORD IN PLAIN TEXT":"WACHTWOORD ALS PLATTE TEKST","Passive Mode":"Passieve modus","The server names a data port":"De server noemt een datapoort","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I vraagt om een binaire kopie byte voor byte. PASV vraagt de server een poort te openen voor de dataverbinding. Het antwoord codeert adres en poort als zes getallen: 195 × 256 + 149 = poort 50069. De laptop verbindt naar buiten, en dat werkt door NAT heen.","Data port":"Datapoort","Active mode":"Actieve modus","Server dials in: NAT blocks":"Server belt in: NAT blokkeert","Data Connection":"Dataverbinding","A second TCP connection":"Een tweede TCP-verbinding","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"De app opent een tweede TCP-verbinding, naar poort 50069, en vraagt het bestand op de besturingsverbinding met RETR. De server antwoordt daar 150 en begint het bestand over de nieuwe verbinding te sturen.","Data to":"Data naar","The File Arrives":"Het bestand komt aan","Closing the connection ends it":"Het sluiten van de verbinding beëindigt het","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"De 4,000 bytes komen aan in 3 TCP-segmenten. FTP zet geen lengte in de data zelf: de server sluit de dataverbinding om het einde van het bestand te markeren. Zodra de laptop alles heeft bevestigd, bevestigt de server met 226 op de besturingsverbinding.","report.pdf, 4,000 bytes":"report.pdf, 4,000 bytes","End of file":"Einde bestand","Data connection closed":"Dataverbinding gesloten","3 SEGMENTS":"3 SEGMENTEN","4,000 bytes, readable by anyone":"4,000 bytes, leesbaar voor iedereen","end of file:":"einde bestand:","data connection closed":"dataverbinding gesloten",Quit:"Afsluiten","Close the control connection":"Sluit de besturingsverbinding","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT beëindigt de sessie en de server neemt afscheid met 221. Voor alles wat gevoelig is, doen SFTP (een ander protocol, over SSH) of FTPS (FTP in TLS) hetzelfde werk met versleuteling.","Encrypted cousins":"Versleutelde neven","FTP data":"FTP-data","The file itself, unencrypted: anyone on the path could read it.":"Het bestand zelf, onversleuteld: iedereen onderweg kan het lezen.","Secure Remote Login":"Veilig op afstand inloggen","Plain setup":"Onversleutelde opzet","From laptop":"Van de laptop","From server":"Van de server","Some packets not shown":"Sommige pakketten niet getoond","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH geeft je een versleutelde, geauthenticeerde verbinding met een andere computer, om er opdrachten op uit te voeren, bestanden te kopiëren (SFTP, scp) of andere verbindingen door te sturen. De server bewijst wie hij is met een hostsleutel; jij bewijst wie je bent met een sleutelpaar of een wachtwoord.","Server proves":"Server bewijst","Host key (known_hosts)":"Hostsleutel (known_hosts)","You prove":"Jij bewijst","Key pair or password":"Sleutelpaar of wachtwoord","Logged in securely":"Veilig ingelogd","Encrypted from the key exchange on":"Versleuteld vanaf de sleuteluitwisseling","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"De twee kanten spraken algoritmen af, maakten gedeelde sleutels met een post-quantum hybride uitwisseling, en de server bewees zijn identiteit met zijn hostsleutel. Alice bewees de hare door te ondertekenen met een privésleutel die de laptop nooit verliet, en typte daarna een opdracht, één pakket per toets.",Login:"Inloggen","Ed25519 key, no password":"Ed25519-sleutel, geen wachtwoord","Say Hello":"Hallo zeggen","Versions, in plain text":"Versies, als platte tekst","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice voert ‘ssh alice@server.example.com’ uit. Na de TCP-handshake op poort 22 stuurt elke kant één regel platte tekst met de SSH-protocolversie (2.0) en zijn software. Al het andere in SSH is binair.",VERSION:"VERSIE","Agree on Algorithms":"Algoritmen afspreken","KEXINIT lists, first match wins":"KEXINIT-lijsten, de eerste match wint","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Elke kant stuurt een KEXINIT met elk algoritme dat hij ondersteunt, op volgorde van voorkeur, voor sleuteluitwisseling, hostsleutels, versleuteling, integriteit en compressie. Per categorie wordt het eerste algoritme op de lijst van de laptop gekozen dat de server ook ondersteunt.","Host key":"Hostsleutel","server’s algorithm lists":"algoritmelijsten van de server","in order of preference":"op volgorde van voorkeur","laptop’s algorithm lists":"algoritmelijsten van de laptop","Key Exchange":"Sleuteluitwisseling","Shared keys, and a host key check":"Gedeelde sleutels en een hostsleutelcontrole","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"De laptop stuurt zijn helft van een hybride uitwisseling: een Streamlined NTRU Prime-sleutel, gekozen om toekomstige quantumcomputers te weerstaan, plus een X25519-sleutel. De server antwoordt met zijn helft, zijn hostsleutel en een handtekening over de uitwisseling. NEWKEYS zet de versleuteling aan.",Hybrid:"Hybride","Matches known_hosts":"Komt overeen met known_hosts","First visit":"Eerste bezoek","ssh asks you to confirm":"ssh vraagt je te bevestigen","public keys":"publieke sleutels","its half, its host key":"zijn helft, zijn hostsleutel","and a signature":"en een handtekening","HOST KEY MATCHES KNOWN_HOSTS":"HOSTSLEUTEL KLOPT MET KNOWN_HOSTS","Log In with a Key":"Inloggen met een sleutel","Sign, don’t send a secret":"Onderteken, stuur geen geheim","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"De server somt de inlogmethoden op die hij accepteert. De laptop biedt de publieke sleutel van Alice aan, en de server zegt dat hij die zou accepteren. Dan ondertekent de laptop deze sessie met de privésleutel, die de laptop nooit verlaat. De server controleert de handtekening aan de hand van authorized_keys.",Methods:"Methoden",Key:"Sleutel","Ed25519, private stays here":"Ed25519, privé blijft hier","Checked with":"Gecontroleerd met","AUTH FAILURE":"AUTH MISLUKT","OFFER KEY":"BIEDT SLEUTEL AAN","alice’s public key":"publieke sleutel van alice","would you accept it?":"zou je die accepteren?","yes, that key":"ja, die sleutel","is in authorized_keys":"staat in authorized_keys",SIGNED:"ONDERTEKEND","same key, plus a signature":"zelfde sleutel, plus een handtekening","made with the private key":"gemaakt met de privésleutel",SUCCESS:"GELUKT","logged in":"ingelogd","Open a Session":"Een sessie openen","Channels inside one connection":"Kanalen binnen één verbinding","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Eén SSH-verbinding kan veel kanalen dragen: een shell, bestandsoverdrachten, doorgestuurde poorten. De laptop opent een sessiekanaal, vraagt daarna om een terminal en een shell (niet getoond), en de server stuurt zijn welkomsttekst en een prompt.",Channel:"Kanaal",session:"session","Then asks for":"Vraagt daarna om","A terminal and a shell":"Een terminal en een shell","Also possible":"Ook mogelijk","SFTP, port forwarding":"SFTP, poorten doorsturen","CHANNEL OPEN":"KANAAL OPENEN","open a channel:":"open een kanaal:",CONFIRMED:"BEVESTIGD","channel open":"kanaal open","Type a Command":"Een opdracht typen","Every key is a packet":"Elke toets is een pakket","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice typt pwd. Elke toets gaat meteen weg in een eigen versleuteld pakket, en de server stuurt het teken terug om te tonen (de echo). Sinds 9.5 stuurt OpenSSH toetsen op een ritme van 20 ms en voegt het lokpakketten toe, zodat het typeritme moeilijker uit de timing af te lezen is.","Per key":"Per toets","1 packet, 90 bytes":"1 pakket, 90 bytes",Echo:"Echo","Sent back by the server":"Teruggestuurd door de server",Timing:"Timing","20 ms beat plus decoys":"Ritme van 20 ms plus lokpakketten",ECHO:"ECHO",ENTER:"ENTER","Enter key":"Entertoets",OUTPUT:"UITVOER","EACH KEY IS ITS OWN PACKET":"ELKE TOETS IS EEN EIGEN PAKKET","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (sntrup761x25519 publieke sleutels)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (hostsleutel, zijn helft, handtekening)","Encrypted (len=44): service request, ssh-userauth":"Versleuteld (len=44): serviceverzoek, ssh-userauth","Encrypted (len=44): service accept":"Versleuteld (len=44): service geaccepteerd","Encrypted (len=68): login with method none":"Versleuteld (len=68): inloggen met methode none","Encrypted (len=52): try publickey,password":"Versleuteld (len=52): probeer publickey,password","Encrypted (len=140): offer public key":"Versleuteld (len=140): biedt publieke sleutel aan","Encrypted (len=100): public key OK":"Versleuteld (len=100): publieke sleutel OK","Encrypted (len=308): public key + signature":"Versleuteld (len=308): publieke sleutel + handtekening","Encrypted (len=28): login success":"Versleuteld (len=28): inloggen gelukt","Encrypted (len=52): channel open: session":"Versleuteld (len=52): kanaal openen: session","Encrypted (len=44): channel open confirmed":"Versleuteld (len=44): kanaal openen bevestigd","Encrypted (len=36): keystroke":"Versleuteld (len=36): toetsaanslag","Encrypted (len=36): echo":"Versleuteld (len=36): echo","Encrypted (len=36): keystroke (Enter)":"Versleuteld (len=36): toetsaanslag (Enter)","Encrypted (len=132): output and a new prompt":"Versleuteld (len=132): uitvoer en een nieuwe prompt","Packet length":"Pakketlengte","Bytes after this field.":"Bytes na dit veld.","Padding length":"Opvullengte","Random padding brings the packet to a multiple of 8 bytes.":"Willekeurige opvulling brengt het pakket op een veelvoud van 8 bytes.",Cookie:"Cookie","Host keys":"Hostsleutels","Ciphers, out":"Versleutelingen, uit","Ciphers, in":"Versleutelingen, in","MACs, out":"MAC’s, uit","MACs, in":"MAC’s, in","Compression, out":"Compressie, uit","Compression, in":"Compressie, in","Languages, out":"Talen, uit","Languages, in":"Talen, in","First packet follows":"Eerste pakket volgt",Reserved:"Gereserveerd","Public keys":"Publieke sleutels","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 bytes (sntrup761 1,158 + X25519 32)","51 bytes: ssh-ed25519 public key":"51 bytes: ssh-ed25519 publieke sleutel","Server’s half":"Helft van de server","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 bytes (sntrup761-ciphertext 1,039 + X25519 32)",Signature:"Handtekening","83 bytes: ssh-ed25519 signature over the exchange":"83 bytes: ssh-ed25519-handtekening over de uitwisseling","From the next packet on, this side encrypts.":"Vanaf het volgende pakket versleutelt deze kant.","SSH · encrypted packet":"SSH · versleuteld pakket","Encrypted packet":"Versleuteld pakket","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Met chacha20-poly1305 is zelfs de lengte versleuteld; een tag van 16 bytes aan het eind verraadt elke wijziging.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): gebruiker ‘alice’, service ‘ssh-connection’, methode ‘none’","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): methoden om mee verder te gaan: ‘publickey,password’","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): methode ‘publickey’, geen handtekening, de ssh-ed25519 publieke sleutel","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): dezelfde ssh-ed25519-sleutel","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): methode ‘publickey-hostbound-v00@openssh.com’, de sleutel, de hostsleutel van de server en een handtekening","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): ‘session’, kanaal 0, venster 2 MB, pakketten tot 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): kanaal 0 is open","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘p’","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘p’, teruggestuurd om te tonen","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘w’","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘w’, teruggestuurd om te tonen","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘d’","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, ‘d’, teruggestuurd om te tonen","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 1 byte, een carriage return (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), kanaal 0: 94 bytes: een nieuwe regel, de terminalcodes van de shell, ‘/home/alice’ en de gekleurde prompt","From browser":"Van de browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS legt een beveiligd kanaal boven op TCP. Het bewijst de identiteit van de server met een certificaat, spreekt nieuwe sleutels af en versleutelt en authenticeert daarna alles wat verstuurd wordt. HTTPS, beveiligde e-mail en veel andere protocollen draaien erin. SSL was de naam van zijn voorganger.",Sits:"Zit","Between TCP and the app":"Tussen TCP en de app","OSI layer":"OSI-laag","Often placed at 6":"Vaak op 6 geplaatst",Current:"Huidig",Retired:"Afgeschaft","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 en 3, TLS 1.0 en 1.1","The app’s own (443, 993 …)":"Die van de app (443, 993 …)","Secure from start to finish":"Veilig van begin tot eind","One round trip to set up":"Eén rondreis om op te zetten","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Eén rondreis legde een versie, een versleuteling en een post-quantum hybride sleutel vast. De certificaatketen bewees wie de server was, en elke byte na de Server Hello werd versleuteld en geauthenticeerd, tot en met de close_notify. Druk op OPNIEUW om het nog eens te bekijken.","1 round trip":"1 rondreis","Everything the browser supports":"Alles wat de browser ondersteunt","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Na de TCP-handshake somt de browser op wat hij kan: TLS-versies, cipher suites en sleuteldelen voor de groepen die hij verwacht, waaronder de post-quantum hybride X25519MLKEM768. Hij noemt ook de site (SNI) en de protocollen die hij spreekt (ALPN).",Versions:"Versies","versions, ciphers, key shares":"versies, versleutelingen, sleuteldelen","Choices made, keys computed":"Keuzes gemaakt, sleutels berekend","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"De server kiest TLS 1.3, de cipher suite en de hybride groep, en stuurt zijn eigen sleuteldeel. Uit de twee delen berekenen beide kanten hetzelfde geheim zonder dat het ooit over het netwerk gaat. Alles na dit bericht is versleuteld.",Group:"Groep","From here on":"Vanaf hier","its key share":"zijn sleuteldeel","SHARED SECRET COMPUTED":"GEDEELD GEHEIM BEREKEND",Certificate:"Certificaat","Who the server is, proven":"Wie de server is, bewezen","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Nu versleuteld gaat de vlucht verder: het gekozen protocol (http/1.1), de certificaatketen, een handtekening gemaakt met de privésleutel van het certificaat, en Finished.",Chain:"Keten","Site → intermediate → root":"Site → tussenliggend → root","Proves the private key":"Bewijst de privésleutel",Checked:"Gecontroleerd","Name, dates, trusted root":"Naam, data, vertrouwde root","encrypted: http/1.1, certificates,":"versleuteld: http/1.1, certificaten,","signature, Finished":"handtekening, Finished","CHAIN LEADS TO A TRUSTED ROOT":"KETEN LEIDT NAAR EEN VERTROUWDE ROOT","One round trip, then data":"Eén rondreis, dan data","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"De browser stuurt zijn eigen Finished: een controlewaarde over alles wat beide kanten zeiden, berekend met het nieuwe geheim, zodat elk geknoei met de hello’s zou opvallen. TLS 1.3 heeft één rondreis nodig voordat data gaat stromen; TLS 1.2 had er twee nodig.",Covers:"Dekt","The whole handshake":"De hele handshake","For old middleboxes":"Voor oude tussenapparatuur","check value over":"controlewaarde over","the whole handshake":"de hele handshake","Encrypted Data":"Versleutelde data","Records, tags and tickets":"Records, tags en tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP reist nu in versleutelde records, elk met een tag van 16 bytes die elke wijziging blootlegt. De server stuurt ook twee sessietickets: de volgende keer kan de browser er met één hervatten en het certificaat overslaan.","Per record":"Per record","22 bytes of overhead":"22 bytes overhead","2, for resuming later":"2, om later te hervatten",Visible:"Zichtbaar","IPs, SNI, sizes, timing":"IP’s, SNI, groottes, timing","2 session tickets":"2 sessietickets","for resuming later":"om later te hervatten",Closing:"Afsluiten","close_notify, then TCP":"close_notify, dan TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Na 75 seconden zonder activiteit sluit de server de verbinding. Eerst stuurt hij een close_notify-melding, versleuteld zoals al het andere, zodat de browser weet dat de data opzettelijk eindigde en niet door een aanvaller werd afgekapt. Daarna sluit TCP zoals gewoonlijk.",Alert:"Melding",Why:"Waarom","Shows nothing was cut off":"Toont dat niets is afgekapt","TCP FIN from both sides":"TCP FIN van beide kanten","alert: close_notify":"melding: close_notify",encrypted:"versleuteld","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ versleuteld)","Encrypted handshake (continued)":"Versleutelde handshake (vervolg)","Encrypted handshake (certificate, verify, Finished)":"Versleutelde handshake (certificaat, verify, Finished)","Application Data (inside: close_notify alert)":"Application Data (binnenin: close_notify-melding)","Alert: close_notify (the data ends here, on purpose)":"Melding: close_notify (de data eindigt hier, opzettelijk)"},d={"Two-way web messaging":"Webberichten in twee richtingen","Browser video calls":"Videobellen in de browser","HTTP/3 over UDP":"HTTP/3 over UDP","Routing between networks":"Routering tussen netwerken","Address setup, neighbour discovery":"Adressen en buren vinden","Private DNS lookups":"Privé DNS-opzoekingen","Signed DNS answers":"Ondertekende DNS-antwoorden","Network Time Protocol":"Network Time Protocol","Joining a network (WPA2)":"Verbinden met een netwerk (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"Zakelijke wifi met 802.1X","Hotel and café Wi-Fi logins":"Wifi-aanmelding in hotel en café","Windows file sharing":"Bestanden delen in Windows","Forward proxy and CONNECT":"Forward proxy en CONNECT","Socket Secure proxy":"Socket Secure-proxy","TLS offloading":"TLS-offloading","A modern VPN":"Een moderne VPN","IKEv2 and ESP":"IKEv2 en ESP","Industrial control (OT)":"Industriële besturing (OT)",Proxy:"Proxy","App Server":"Appserver","File Server":"Bestandsserver","ISP Router":"Router van de provider","Transit Router":"Transitrouter","Hosting Router":"Hostingrouter","Their Router":"Router van de ander","Their Laptop":"Laptop van de ander",Transit:"Transit",Hosting:"Hosting","The router itself.":"De router zelf.","Mail in Sync":"Mail in sync","Live Updates":"Live-updates","From the browser":"Van de browser","From the server":"Van de server","The WebSocket Protocol":"The WebSocket Protocol","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"Een WebSocket houdt één verbinding open tussen een webpagina en een server, zodat elke kant op elk moment een bericht kan sturen: chat, live-uitslagen, games, gedeelde documenten. Het begint als een gewoon HTTP-verzoek om een upgrade; daarna reizen berichten in kleine frames met een header van maar een paar bytes.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Een HTTP-verzoek (Upgrade)","Frames both ways, any time":"Frames heen en terug, altijd","Frame header":"Frameheader","2–14 bytes":"2–14 bytes","One request, then messages":"Eén verzoek, dan berichten","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Eén HTTP-verzoek maakte van een gewone TCP-verbinding een kanaal in twee richtingen. Daarna kostte elk bericht een paar bytes header, en de server kon sturen wanneer hij iets te zeggen had. Druk op OPNIEUW om het nog eens te bekijken.","GET with Upgrade, then 101":"GET met Upgrade, dan 101","Smallest frame":"Kleinste frame","2 bytes (a ping)":"2 bytes (een ping)","Server push":"Server-push","Any time, unasked":"Altijd, ongevraagd","Real sites":"Echte sites","wss:// (inside TLS)":"wss:// (in TLS)","TCP to the server, as for HTTP":"TCP naar de server, net als bij HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'De chatpagina is al open, geladen van www.example.com. Het script roept new WebSocket("ws://www.example.com/chat") aan, en de browser begint met een gewone TCP-verbinding naar poort 80. (Echte sites gebruiken wss://, hetzelfde in TLS; met gewoon ws:// kun je elke byte lezen.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Vraag om een upgrade","An HTTP request with Upgrade: websocket":"Een HTTP-verzoek met Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"De browser stuurt een HTTP GET met Upgrade: websocket en Connection: Upgrade. Sec-WebSocket-Key bestaat uit 16 willekeurige bytes in base64, waarop de server correct moet antwoorden. De browser biedt ook aan berichten te comprimeren (permessage-deflate).","Asks for":"Vraagt om","16 random bytes, base64":"16 willekeurige bytes, base64",UPGRADE:"UPGRADE","Switch Protocols":"Protocol wisselen","101: from now on, WebSocket":"101: vanaf nu WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"De server antwoordt 101 Switching Protocols. Zijn Sec-WebSocket-Accept is de sleutel met een vaste tekenreeks erachter, gehasht met SHA-1 en in base64: het bewijs dat hij het verzoek begreep. Hij nam de compressie niet aan, dus berichten gaan als platte tekst. HTTP is klaar op deze verbinding; vanaf nu sturen beide kanten WebSocket-frames.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 van de sleutel + een vaste tekenreeks",Compression:"Compressie","Offered, not taken":"Aangeboden, niet aangenomen","NOW A WEBSOCKET":"NU EEN WEBSOCKET","Small frames, from either side":"Kleine frames, van beide kanten",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Je stuurt "Hello": een header van 2 bytes, een maskeersleutel van 4 bytes en de 5 gemaskeerde bytes, 11 bytes in totaal in plaats van een heel HTTP-verzoek. Seconden later pusht de server ongevraagd Bobs bericht: de verbinding is nog open, dus dat kan. Frames van de browser zijn altijd gemaskeerd; frames van de server nooit.',"You send":"Jij stuurt","Server pushes":"Server pusht",'"bob: hi there"':'"bob: hi there"',Masked:"Gemaskeerd","From the browser only":"Alleen van de browser",TEXT:"TEKST",masked:"gemaskeerd",unasked:"ongevraagd","Keeping It Alive":"In leven houden","Ping and pong":"Ping en pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Na een halve minuut zonder iets te zeggen stuurt de server een ping, zodat routers en firewalls onderweg de stille verbinding niet vergeten. De browser antwoordt zelf met een pong; het script van de pagina ziet geen van beide.","Opcode 9, from either side":"Opcode 9, van beide kanten",Pong:"Pong","Opcode 10, by itself":"Opcode 10, vanzelf","How often":"Hoe vaak","Up to the server (30 s)":"Aan de server (30 s)","A close frame each way":"Een close-frame in elke richting","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Als je de chat verlaat, sluit het script van de pagina de WebSocket met status 1000 (normale afsluiting): de browser stuurt een close-frame en de server antwoordt met het zijne. Daarna sluit de server de TCP-verbinding. (Gewoon het tabblad sluiten zou 1001 sturen, weggaan.)",Opcode:"Opcode","8 (close)":"8 (close)","1000 (normal closure)":"1000 (normale afsluiting)","TCP closes":"TCP sluit",CLOSE:"CLOSE","1000 normal closure":"1000 normale afsluiting","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: dit frame is een volledig bericht. De opcode zegt wat het draagt.","Mask, length":"Masker, lengte","Everything a browser sends is masked.":"Alles wat een browser stuurt, is gemaskeerd.","Masking key":"Maskeersleutel","Chosen at random for every frame.":"Voor elk frame willekeurig gekozen.",Payload:"Payload","Each byte XORed with the masking key in turn; the server XORs it back.":"Elke byte om de beurt ge-XOR’d met de maskeersleutel; de server XOR’t hem terug.","A server never masks what it sends.":"Een server maskeert nooit wat hij stuurt.","Status code":"Statuscode","Joining a Network":"Verbinden met een netwerk","From the access point":"Van het access point","4-way handshake":"4-way handshake","Access Point":"Access point","Wi-Fi (802.11) with WPA2":"Wifi (802.11) met WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Wifi draagt een netwerk via radio. Voordat een apparaat iets kan sturen, moet het het netwerk vinden, erbij komen en bewijzen dat het het wachtwoord kent. Bij WPA2-Personal is dat bewijs de 4-way handshake: vier korte berichten die van het wachtwoord nieuwe sleutels maken, zonder dat het wachtwoord ooit door de lucht gaat.","Data Link (Layer 2)":"Datalink (laag 2)",Standard:"Standaard",Joining:"Verbinden","Probe, authenticate, associate":"Probe, authenticatie, associatie","Keys from":"Sleutels uit","The 4-way handshake":"De 4-way handshake",Connected:"Verbonden","Eleven frames to a secure link":"Elf frames naar een veilige verbinding","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"De laptop vond het netwerk, kwam erbij met twee formaliteiten en bewees in een handshake van vier berichten dat hij het wachtwoord kende, zonder het ooit te sturen. Alles daarna werd versleuteld met sleutels die alleen voor deze verbinding gemaakt waren. Druk op OPNIEUW om het nog eens te bekijken.","Frames to join":"Frames om te verbinden","Password sent":"Wachtwoord verstuurd",Never:"Nooit","Session keys":"Sessiesleutels","New every time":"Elke keer nieuw",Next:"Daarna","DHCP, for an IP address":"DHCP, voor een IP-adres","Find the Network":"Het netwerk vinden","A beacon, then a probe":"Een beacon, dan een probe",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Zo’n tien keer per seconde stuurt de wifi van de router een beacon: hier is "HomeNet", beveiligd met WPA2, op kanaal 36. De laptop zou gewoon op zo’n beacon kunnen wachten; om sneller te zijn vraagt hij het ook hardop met een probe request, en het access point antwoordt met een probe response.',"WPA2-Personal (password)":"WPA2-Personal (wachtwoord)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · kanaal 36",PROBE:"PROBE","any networks here?":"zijn hier netwerken?","PROBE RESPONSE":"PROBE RESPONSE","Join the Network":"Bij het netwerk komen","Two formalities: hello, then join":"Twee formaliteiten: hallo, dan aansluiten","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"Open System-authenticatie laat iedereen tot hier komen: nog geen wachtwoord. Dan vraagt de laptop om te associëren, met herhaling van de gekozen beveiliging (CCMP, met een wachtwoord), en het access point geeft hem associatie-ID 1. De laptop is verbonden, maar het enige wat hij mag sturen is de handshake die nu volgt.",Authentication:"Authenticatie","Open System (no password)":"Open System (geen wachtwoord)","Association ID":"Associatie-ID","Allowed so far":"Tot nu toe toegestaan",success:"gelukt",ASSOCIATE:"ASSOCIËREN",'join "HomeNet"':'aansluiten bij "HomeNet"',"CCMP, password":"CCMP, wachtwoord",ASSOCIATED:"GEASSOCIEERD","association ID 1":"associatie-ID 1","Messages 1 and 2":"Berichten 1 en 2","The 4-way handshake: nonces":"De 4-way handshake: nonces","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Beide kanten hebben al dezelfde sleutel, berekend uit het wachtwoord en de netwerknaam (de PMK); die gaat nooit door de lucht. Het access point stuurt een willekeurig getal, de ANonce. De laptop stuurt zijn eigen, de SNonce, met een controlewaarde (MIC). Uit de PMK, de twee nonces en beide MAC-adressen berekent elke kant nu dezelfde sessiesleutels.","Shared key":"Gedeelde sleutel","PMK, from the password":"PMK, uit het wachtwoord",Exchanged:"Uitgewisseld","Two random nonces":"Twee willekeurige nonces","Worked out":"Berekend","Session keys (PTK)":"Sessiesleutels (PTK)","MESSAGE 1":"BERICHT 1","MESSAGE 2":"BERICHT 2","Messages 3 and 4":"Berichten 3 en 4","The 4-way handshake: keys":"De 4-way handshake: sleutels","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Bericht 3 laat zien dat het access point dezelfde sleutels heeft (zijn MIC klopt) en brengt de groepssleutel (GTK) voor broadcasts, versleuteld. Bericht 4 zegt dat de laptop klaar is, en beide kanten beginnen te versleutelen.","Group key":"Groepssleutel","GTK, sent encrypted":"GTK, versleuteld verstuurd",Install:"Installeren","Both ends at once":"Beide kanten tegelijk","MESSAGE 3":"BERICHT 3","group key, encrypted":"groepssleutel, versleuteld","MESSAGE 4":"BERICHT 4","keys installed":"sleutels geïnstalleerd","Encrypted Now":"Nu versleuteld","And what a listener could still do":"En wat een meeluisteraar nog kan","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Elk dataframe is nu versleuteld, zoals dit eerste met een DHCP Discover: iedereen in de buurt ziet alleen de MAC-adressen en de grootte. Maar wie de vier handshakeberichten heeft opgenomen, kan thuis wachtwoorden proberen te raden, zo snel als zijn computer toelaat: een gok is goed als die dezelfde MIC geeft. Een lang, willekeurig wachtwoord maakt dat kansloos; WPA3 haalt de zwakte weg.","Others see":"Anderen zien","MAC addresses, sizes, timing":"MAC-adressen, groottes, timing","Weak point":"Zwakke plek","Offline password guessing":"Offline wachtwoorden raden",Defence:"Verdediging","A long password, or WPA3":"Een lang wachtwoord, of WPA3","DHCP Discover inside":"DHCP Discover binnenin","ENCRYPTED FROM HERE ON":"VANAF HIER VERSLEUTELD","QoS Data (encrypted)":"QoS Data (versleuteld)","Seen over the air, on Wi-Fi channel 36":"Gezien door de lucht, op wifikanaal 36","Frame type":"Frametype","Management, Beacon":"Beheer, Beacon",Duration:"Duur","Nobody acknowledges a broadcast, so nothing is booked.":"Niemand bevestigt een broadcast, dus er wordt niets gereserveerd.",Receiver:"Ontvanger","Broadcast: every device in range listens.":"Broadcast: elk apparaat binnen bereik luistert.",Transmitter:"Zender","The access point.":"Het access point.","The access point’s own address: which network this is about.":"Het eigen adres van het access point: om welk netwerk het gaat.","Lets the receiver spot a repeat when a frame is sent again.":"Laat de ontvanger een herhaling herkennen als een frame opnieuw wordt verstuurd.","The access point’s clock; devices on the network keep theirs in step with it.":"De klok van het access point; apparaten op het netwerk houden die van hen daarmee gelijk.","Beacon interval":"Beacon-interval","A beacon goes out about ten times a second.":"Er gaat zo’n tien keer per seconde een beacon uit.","0x0011: access point network, encrypted":"0x0011: netwerk met access point, versleuteld","Privacy bit set: joining takes a key.":"Privacybit gezet: aansluiten vraagt een sleutel.","The network’s name.":"De naam van het netwerk.","Supported rates":"Ondersteunde snelheden","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Alleen de oudste, traagste snelheden; de snelle staan in de elementen die volgen.","DTIM count 0, period 1":"DTIM-teller 0, periode 1","Tells sleeping devices whether frames are waiting for them.":"Vertelt slapende apparaten of er frames voor hen klaarstaan.","Robust Security Network: how this network is protected.":"Robust Security Network: hoe dit netwerk beveiligd is.","Element ID, length":"Element-ID, lengte","48, 20 bytes":"48, 20 bytes","Group cipher":"Groepsversleuteling","Encrypts broadcasts, which every device on the network can read.":"Versleutelt broadcasts, die elk apparaat op het netwerk kan lezen.","Pairwise cipher":"Paarsgewijze versleuteling","Encrypts each device’s own traffic, with keys only it and the access point have.":"Versleutelt het eigen verkeer van elk apparaat, met sleutels die alleen dat apparaat en het access point hebben.","Key management":"Sleutelbeheer","1: PSK (a shared password)":"1: PSK (een gedeeld wachtwoord)","More elements":"Meer elementen","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Mogelijkheden en instellingen voor wifi 4, 5 en 6 (HT, VHT, HE: kanaal 36, 80 MHz breed), en extra’s van de fabrikant.","Management, Probe Request":"Beheer, Probe Request","The laptop’s Wi-Fi card.":"De wifikaart van de laptop.","empty (any network)":"leeg (elk netwerk)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Elk access point mag antwoorden. (Vroeger vroegen apparaten op naam naar elk netwerk waarmee ze ooit verbonden waren, en vertelden zo iedereen die meeluisterde waar ze geweest waren.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Wat de radio van de laptop kan: mogelijkheden voor wifi 4, 5 en 6, en extra’s van de fabrikant.","Management, Probe Response":"Beheer, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Hoelang het kanaal voor deze uitwisseling gereserveerd blijft; andere apparaten wachten.","The radio this frame is for.":"De radio waarvoor dit frame bedoeld is.","Authentication · Open System":"Authenticatie · Open System","Management, Authentication":"Beheer, Authentication",Algorithm:"Algoritme","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Open: iedereen mag tot hier komen. Het wachtwoord wordt later gecontroleerd, in de 4-way handshake.",Transaction:"Transactie","0 (success)":"0 (gelukt)","Management, Association Request":"Beheer, Association Request","Listen interval":"Luisterinterval","10 beacons":"10 beacons","How often the laptop wakes to check for waiting frames when saving power.":"Hoe vaak de laptop in energiebesparing wakker wordt om te kijken of er frames klaarstaan.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Wat de radio van de laptop kan (wifi 4, 5 en 6), en extra’s van de fabrikant.","Management, Association Response":"Beheer, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Het nummer van de laptop bij dit access point (de bovenste twee bits staan altijd aan).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"De instellingen die het access point gebruikt (wifi 4, 5 en 6), en extra’s van de fabrikant.","Data, QoS Data":"Data, QoS Data","0x02 (from the access point)":"0x02 (van het access point)","Sent by the access point itself.":"Verstuurd door het access point zelf.","QoS control":"QoS-besturing","Priority 7, the highest: the handshake goes first.":"Prioriteit 7, de hoogste: de handshake gaat voor.",Organization:"Organisatie","0x888e (802.1X authentication)":"0x888e (802.1X-authenticatie)","What follows: plays the part an Ethernet type field does on a cable.":"Wat volgt: speelt de rol die het Ethernet-typeveld op een kabel speelt.","Descriptor type":"Descriptortype","Key information":"Sleutelinformatie","0x008a: pairwise, ACK":"0x008a: paarsgewijs, ACK","ACK: the laptop must answer.":"ACK: de laptop moet antwoorden.","Key length":"Sleutellengte","The pairwise key is 16 bytes (AES-128).":"De paarsgewijze sleutel is 16 bytes (AES-128).","Replay counter":"Replay-teller","Counts up with each message from the access point; an old one sent again is ignored.":"Telt op bij elk bericht van het access point; een oud bericht dat opnieuw wordt gestuurd, wordt genegeerd.","A random number from the access point.":"Een willekeurig getal van het access point.","Key IV":"Sleutel-IV",zeros:"nullen","Key RSC":"Sleutel-RSC","No keys yet, so nothing to check with.":"Nog geen sleutels, dus niets om mee te controleren.","Key data length":"Lengte sleuteldata","0x01 (to the access point)":"0x01 (naar het access point)","The access point itself.":"Het access point zelf.","0x010a: pairwise, MIC":"0x010a: paarsgewijs, MIC","MIC: this message carries a check value.":"MIC: dit bericht draagt een controlewaarde.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Een willekeurig getal van de laptop. Uit beide getallen, beide MAC-adressen en de sleutel die uit het wachtwoord komt, berekent elke kant dezelfde sessiesleutels.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Berekend met de nieuwe sleutels: bewijst dat de afzender het wachtwoord kent en dat het bericht niet is gewijzigd.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: paarsgewijs, install, ACK, MIC, secure, sleuteldata versleuteld","Install: start using the keys. The group key comes encrypted.":"Install: begin de sleutels te gebruiken. De groepssleutel komt versleuteld.","Where the group key’s packet numbers start.":"Waar de pakketnummers van de groepssleutel beginnen.","Key data":"Sleuteldata","Encrypted with a key from the handshake.":"Versleuteld met een sleutel uit de handshake.","The access point’s RSN element":"Het RSN-element van het access point","GTK: the group key, for broadcasts":"GTK: de groepssleutel, voor broadcasts","0x030a: pairwise, MIC, secure":"0x030a: paarsgewijs, MIC, secure","Secure: the keys are in place.":"Secure: de sleutels staan klaar.","CCMP · encrypted":"CCMP · versleuteld","0x41 (protected, to the access point)":"0x41 (beschermd, naar het access point)","Protected: what follows the header is encrypted.":"Beschermd: wat na de header komt, is versleuteld.","Where the access point should pass it on to: everyone on the network.":"Naar wie het access point het moet doorgeven: iedereen op het netwerk.","CCMP header":"CCMP-header","packet number 1, key 0":"pakketnummer 1, sleutel 0","Counts up with every frame; one seen before is thrown away.":"Telt op bij elk frame; een frame dat al gezien is, wordt weggegooid.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: een IPv4-pakket","Shows any change to the frame.":"Verraadt elke wijziging aan het frame.","Safer Wi-Fi":"Veiligere wifi","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 is de huidige beveiligingsstandaard voor wifi. De Personal-modus houdt het simpele gedeelde wachtwoord, maar verandert hoe het gecontroleerd wordt: SAE, een wachtwoorduitwisseling die geen opname offline kan aanvallen, geeft elke verbinding een nieuwe sleutel. Het maakt ook beschermde beheerframes verplicht.","Password check":"Wachtwoordcontrole",Required:"Verplicht","Protected management frames":"Beschermde beheerframes",Since:"Sinds","Connected with WPA3":"Verbonden met WPA3","Same password, better protocol":"Zelfde wachtwoord, beter protocol","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"De laptop en het access point bewezen elkaar dat ze het wachtwoord kennen, zonder iemand een manier te geven om offline te raden, en maakten daarna nieuwe sleutels, precies zoals WPA2 doet. Druk op OPNIEUW om het nog eens te bekijken.","SAE frames":"SAE-frames","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 EAPOL-Key-frames","Offline guessing":"Offline raden","Not possible":"Niet mogelijk","Forged disconnects":"Vervalste verbrekingen",Ignored:"Genegeerd","A WPA3 Network":"Een WPA3-netwerk","The beacon asks for SAE":"De beacon vraagt om SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"De beacon lijkt op die van WPA2, met twee verschillen in het RSN-element: het sleutelbeheer is SAE in plaats van PSK, en beschermde beheerframes zijn verplicht. Iedereen gebruikt nog steeds één gedeeld wachtwoord.","Management frames":"Beheerframes","Protected (required)":"Beschermd (verplicht)","Still one for everyone":"Nog steeds één voor iedereen","SAE Commit":"SAE Commit","Each side commits to the password":"Elke kant legt zich vast op het wachtwoord","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"In plaats van Open System-authenticatie voeren de twee kanten SAE uit, een wachtwoorduitwisseling tussen gelijken. Elk kiest een willekeurig geheim en stuurt een scalar en een element, berekend uit dat geheim en het wachtwoord. Het wachtwoord is aan beide kanten hetzelfde, de geheimen niet, dus elke verbinding eindigt met een nieuwe sleutel.","19 (256-bit curve)":"19 (256-bits curve)","Each sends":"Elk stuurt","A scalar and an element":"Een scalar en een element",Replaces:"Vervangt","Open System authentication":"Open System-authenticatie",COMMIT:"COMMIT","scalar + element":"scalar + element","SAE Confirm":"SAE Confirm","Proof, without the password":"Bewijs, zonder het wachtwoord","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Elke kant berekent nu de gedeelde sleutel en stuurt een confirm, een waarde die alleen iemand met het juiste wachtwoord kan maken. Alle vier SAE-frames opnemen laat een aanvaller niet thuis raden: elke gok vraagt een live uitwisseling met het access point, dat hem kan afremmen of buitensluiten.","A new key (PMK) each time":"Elke keer een nieuwe sleutel (PMK)",Guessing:"Raden","Live only, never offline":"Alleen live, nooit offline","Password leaks":"Uitgelekt wachtwoord","Past traffic stays safe":"Eerder verkeer blijft veilig",CONFIRM:"CONFIRM","proof of the key":"bewijs van de sleutel","Join, Handshake":"Aansluiten, handshake","Then the 4-way handshake, as in WPA2":"Dan de 4-way handshake, net als bij WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"Associatie werkt als voorheen, met herhaling van de keuze voor SAE. De 4-way handshake die volgt is die van WPA2, vanaf de sleutel die SAE net maakte, behalve dat bericht 3 ook de IGTK meebrengt, een sleutel die broadcast-beheerframes ondertekent.","Message 3 adds":"Bericht 3 voegt toe","Why It’s Safer":"Waarom het veiliger is","Forged disconnects stop working":"Vervalste verbrekingen werken niet meer","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Bij WPA2 kon iedereen binnen bereik een ‘verbreek’-frame vervalsen en een apparaat van het netwerk gooien, vaak om zijn handshake op te nemen als het opnieuw verbond. WPA3 vereist beschermde beheerframes, dus vervalste verbrekingen worden genegeerd. Veel routers bieden ook een overgangsmodus waarin WPA2-apparaten ook mogen aansluiten; die apparaten houden de zwaktes van WPA2.",Protected:"Beschermd","Disconnects, other management":"Verbrekingen, ander beheer","WPA2/3 mode":"WPA2/3-modus","WPA2 devices stay at risk":"WPA2-apparaten blijven kwetsbaar","Stronger still":"Nog sterker","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 bits)","MANAGEMENT FRAMES PROTECTED":"BEHEERFRAMES BESCHERMD","0x00c0: management frame protection required":"0x00c0: bescherming van beheerframes verplicht","Disconnect messages and other management frames are signed, so they can’t be forged.":"Verbreekberichten en andere beheerframes zijn ondertekend, dus ze kunnen niet vervalst worden.","Authentication · SAE Commit":"Authenticatie · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: de wachtwoorduitwisseling van WPA3.","19 (256-bit elliptic curve)":"19 (256-bits elliptische curve)",Scalar:"Scalar","Worked out from a random secret and the password.":"Berekend uit een willekeurig geheim en het wachtwoord.",Element:"Element","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Een punt op de curve, ook gekoppeld aan het wachtwoord. Wie de scalar en het element opneemt, kan achteraf geen wachtwoordgokken testen.","Authentication · SAE Confirm":"Authenticatie · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Bewijst dat deze kant dezelfde sleutel berekende, zonder hem prijs te geven.","0x0088: pairwise, ACK":"0x0088: paarsgewijs, ACK","0x0108: pairwise, MIC":"0x0108: paarsgewijs, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: paarsgewijs, install, ACK, MIC, secure, sleuteldata versleuteld","IGTK: the key that signs broadcast management frames":"IGTK: de sleutel die broadcast-beheerframes ondertekent","0x0308: pairwise, MIC, secure":"0x0308: paarsgewijs, MIC, secure","Sign-In":"Aanmelden","From the router":"Van de router","From the test server":"Van de testserver","Hotel Router":"Hotelrouter","192.168.1.1 · captive portal":"192.168.1.1 · captive portal","Wi-Fi login pages":"Inlogpagina’s voor wifi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Hotels, cafés, vliegvelden en treinen zetten vaak een inlogpagina voor hun wifi. Tot je de voorwaarden accepteert (of betaalt), laat de router niets door naar internet. Hij vangt het eerste onversleutelde HTTP-verzoek van je apparaat op en beantwoordt het met een omleiding naar zijn eigen pagina; je apparaat merkt het omdat een testpagina die het kent verkeerd terugkomt.",Where:"Waar","Hotels, cafés, airports":"Hotels, cafés, vliegvelden",How:"Hoe","Catches plain HTTP requests":"Vangt onversleutelde HTTP-verzoeken op","Noticed by":"Opgemerkt door","Your system’s test page":"De testpagina van je systeem","Logging in":"Inloggen","Lets your MAC address through":"Laat je MAC-adres door","Newer way":"Nieuwere manier","DHCP option 114 (RFC 8910)":"DHCP-optie 114 (RFC 8910)","Described In":"Beschreven in",Online:"Online","Noticed, logged in, let through":"Opgemerkt, ingelogd, doorgelaten","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows vroeg een testpagina om een antwoord dat het kent en kreeg in plaats daarvan een omleiding, dus het wist dat er een portal tussen zat en opende de inlogpagina. Na het accepteren van de voorwaarden liet de router de laptop door, en dezelfde controle kwam goed terug. Druk op OPNIEUW om het nog eens te bekijken.","A plain HTTP test page":"Een onversleutelde HTTP-testpagina","Faked by":"Vervalst door","The router (TTL 64)":"De router (TTL 64)","Let through":"Doorgelaten","The laptop’s MAC address":"Het MAC-adres van de laptop","Open Wi-Fi":"Open wifi","Use HTTPS, or a VPN":"Gebruik HTTPS, of een VPN","Joined, Offline":"Verbonden, offline","An address, but no way out":"Een adres, maar geen uitweg","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"De laptop is verbonden met de hotelwifi, die geen wachtwoord heeft, en kreeg via DHCP een adres van de router. De router antwoordt de laptop zelf en geeft zijn DNS-opzoekingen door, maar gooit al het andere richting internet weg tot de gast is ingelogd. (Een open netwerk betekent ook dat iedereen in de buurt kan lezen wat niet door HTTPS beschermd is.)","192.168.1.10 (by DHCP)":"192.168.1.10 (via DHCP)","Wi-Fi password":"Wifiwachtwoord","None (open network)":"Geen (open netwerk)","Blocked until you log in":"Geblokkeerd tot je inlogt","CONNECTED, NO INTERNET YET":"VERBONDEN, NOG GEEN INTERNET","Internet Check":"Internetcontrole","Windows checks a test page":"Windows controleert een testpagina",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Na het verbinden met elk netwerk zoekt Windows www.msftconnecttest.com op (de router geeft de opzoeking door) en vraagt het via gewoon HTTP om /connecttest.txt; het juiste antwoord is de tekst "Microsoft Connect Test". De router vangt de verbinding op en beantwoordt de handshake zelf, uit naam van de testserver. De laptop merkt nog niets.',"Test page":"Testpagina","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Verwacht","Answered by":"Beantwoord door","The router, posing as the server":"De router, die zich voordoet als de server",'from "203.0.113.30"':'van "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Omgeleid","The wrong answer gives it away":"Het verkeerde antwoord verraadt het",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':"In plaats van de testtekst antwoordt de ‘server’ 302 Found, met een verwijzing naar de inlogpagina van de router. De TTL is 64, helemaal niet verlaagd, omdat het rechtstreeks van de router komt. Windows ziet het verkeerde antwoord, markeert het netwerk als ‘actie vereist’ en opent de browser, waarvan de router het eerste verzoek op dezelfde manier omleidt, naar zijn inlogpagina. Dit werkt alleen met gewoon HTTP: de router kan geen HTTPS-pagina vervalsen zonder certificaatfout.","302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Verraden door","TTL 64, from one hop away":"TTL 64, één hop verderop","Why HTTP":"Waarom HTTP","HTTPS can’t be faked":"HTTPS is niet te vervalsen","302 FOUND":"302 FOUND","ACTION NEEDED":"ACTIE VEREIST","The Login Page":"De inlogpagina","Served by the router itself":"Geleverd door de router zelf","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"De browser opent http://192.168.1.1/login, een pagina die de router zelf levert: de naam van het hotel, de gebruiksvoorwaarden en een knop Accepteren. Deze verbinding gaat echt naar de router.",Page:"Pagina","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Geleverd door","The router":"De router",Size:"Grootte","2,400 bytes of HTML":"2,400 bytes HTML","/login":"/login","the login page":"de inlogpagina","Accept the Terms":"Voorwaarden accepteren","The router lets the laptop out":"De router laat de laptop naar buiten","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Klikken op Accepteren stuurt een klein formulier terug naar de router. Die zet het MAC-adres van de laptop op de lijst van apparaten die naar buiten mogen, vaak voor de duur van het verblijf, en stuurt de browser door naar waar hij heen wilde.",Form:"Formulier","terms=accepted":"terms=accepted","Router allows":"Router staat toe","302 to where you were going":"302 naar waar je heen ging","you’re online":"je bent online","MAC ADDRESS ALLOWED":"MAC-ADRES TOEGESTAAN","The same check, now real":"Dezelfde controle, nu echt","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows controleert opnieuw. Deze keer laat de router de verbinding door naar de echte testserver, twaalf routers verderop (de antwoorden komen aan met TTL 52), en het antwoord is de verwachte tekst. Het netwerk wordt gemarkeerd als verbonden met internet.","Connected to the internet":"Verbonden met internet",ONLINE:"ONLINE","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, type A, klasse IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Verstuurd met 64 en helemaal niet verlaagd: het kwam van de router naast je, niet van een server 12 routers verderop.","2,400 bytes: the login page":"2,400 bytes: de inlogpagina","Via a Proxy":"Via een proxy","TLS, through the tunnel":"TLS, door de tunnel","Forward proxy, and CONNECT for HTTPS":"Forward proxy, en CONNECT voor HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Een forward proxy haalt webpagina’s voor je op. Bedrijven en scholen gebruiken er een om sites te filteren, kopieën van populaire pagina’s te bewaren en te loggen wat er naar buiten gaat; de sites die je bezoekt zien de proxy, niet jou. Gewoon HTTP gaat er leesbaar doorheen. Voor HTTPS vraagt de browser de proxy om een tunnel, en de versleutelde verbinding gaat er ongelezen doorheen.","Common ports":"Gangbare poorten","http:// pages":"http://-pagina’s","Fetched by the proxy":"Opgehaald door de proxy","https:// pages":"https://-pagina’s","Tunnelled with CONNECT":"Getunneld met CONNECT","Used for":"Gebruikt voor","Filtering, caching, logging":"Filteren, cachen, loggen","Two ways through":"Twee manieren erdoor","Fetched for you, or tunnelled":"Voor je opgehaald, of getunneld","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Bij de gewone pagina deed de proxy het werk: hij las het verzoek, haalde de pagina via zijn eigen verbinding op en had die kunnen bewaren, wijzigen of weigeren. Bij HTTPS opende hij alleen een tunnel en kopieerde versleutelde bytes, zonder meer te weten dan de naam van de site. Druk op OPNIEUW om het nog eens te bekijken.","Server sees":"Server ziet","The proxy (192.0.2.80)":"De proxy (192.0.2.80)","Plain HTTP":"Gewoon HTTP","The proxy reads it all":"De proxy leest alles","Name and sizes only":"Alleen naam en groottes","DNS for the site":"DNS voor de site","Done by the proxy":"Gedaan door de proxy","Proxy Settings":"Proxy-instellingen","The browser sends everything there":"De browser stuurt alles daarheen","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"De browser is ingesteld om alles via een proxy op 192.0.2.80, poort 8080, te sturen, zoals veel bedrijven en scholen eisen. Je opent http://www.example.com. De browser zoekt www.example.com niet zelf op: hij verbindt met de proxy en laat de rest aan hem over.","Left to the proxy":"Overgelaten aan de proxy","To the Proxy":"Naar de proxy","TCP to port 8080":"TCP naar poort 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"De laptop opent een gewone TCP-verbinding, niet naar de website, maar naar poort 8080 van de proxy.","192.0.2.80, port 8080":"192.0.2.80, poort 8080","Not to":"Niet naar","The Whole URL":"De volledige URL","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Gestuurd naar een proxy draagt de verzoekregel het volledige adres, niet alleen het pad: GET http://www.example.com/ HTTP/1.1. Zo weet de proxy waar hij heen moet. Chrome voegt Proxy-Connection: keep-alive toe, een header die alleen proxy’s lezen.","Request line":"Verzoekregel","To a server":"Naar een server","Readable by":"Leesbaar voor","The proxy (plain HTTP)":"De proxy (gewoon HTTP)","to the proxy":"naar de proxy","Proxy Fetches It":"Proxy haalt het op","Its own connection to the server":"Zijn eigen verbinding met de server","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"De proxy zoekt www.example.com zelf op (niet getoond) en opent zijn eigen verbinding met de server. Zijn verzoek is van het gewone soort, GET /, met eigen headers: Via noemt de proxy, en X-Forwarded-For geeft het adres waar het verzoek vandaan kwam (het publieke adres van de thuisrouter, want de laptop zit achter NAT).","The proxy’s own":"Die van de proxy","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Doorgestuurd voor","Page Passed On":"Pagina doorgegeven","The page, passed on":"De pagina, doorgegeven","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"De server antwoordt de proxy, en de proxy geeft de pagina door aan de laptop met een eigen Via-header. Hij zou een kopie kunnen bewaren en die aan de volgende vrager geven zonder de server lastig te vallen (X-Cache: MISS zegt dat hij er nog geen had), en hij kan sites weigeren die niet zijn toegestaan.","The proxy, not the laptop":"De proxy, niet de laptop",Cache:"Cache","MISS (first request)":"MISS (eerste verzoek)","Proxy can":"Proxy kan","Cache, filter, log, change":"Cachen, filteren, loggen, wijzigen","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Nu open je https://www.example.com. Een proxy kan geen HTTPS-pagina voor je ophalen zonder de versleuteling te breken, dus de browser vraagt in plaats daarvan om een tunnel: CONNECT www.example.com:443. De proxy opent een TCP-verbinding naar poort 443 en antwoordt 200 Connection established.","Proxy opens":"Proxy opent","TCP to port 443":"TCP naar poort 443","200 Connection established":"200 Connection established","Connection established":"Verbinding tot stand gebracht","In the Tunnel":"In de tunnel","The proxy copies, unread":"De proxy kopieert, ongelezen","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Vanaf nu kopieert de proxy bytes heen en weer zonder ze te lezen. De TLS Client Hello van de browser gaat erin via de verbinding van de laptop en komt er byte voor byte hetzelfde uit via de verbinding van de proxy met de server. TLS loopt van begin tot eind, dus de proxy leert de naam van de site en de groottes, nooit de pagina’s. (Sommige bedrijfsproxy’s openen HTTPS toch, met een certificaatautoriteit die op elke bedrijfslaptop staat; dan zien ze alles.)","Proxy sees":"Proxy ziet","Site name, sizes, timing":"Sitenaam, groottes, timing","Hidden from it":"Verborgen voor hem","Pages, passwords, cookies":"Pagina’s, wachtwoorden, cookies","TLS, laptop to server":"TLS, laptop naar server","the same bytes":"dezelfde bytes","COPIES BYTES, CAN’T READ THEM":"KOPIEERT BYTES, KAN ZE NIET LEZEN","Any Connection":"Elke verbinding","From the proxy":"Van de proxy","SOCKS Proxy":"SOCKS-proxy","Socket Secure, version 5":"Socket Secure, versie 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS is een proxy voor algemeen gebruik. Waar een HTTP-proxy webverzoeken begrijpt, opent een SOCKS-proxy gewoon een verbinding namens jou en kopieert de bytes, welk protocol het ook is: web, e-mail, games, SSH. Apps gebruiken het om via één gateway een netwerk te bereiken, of om hun eigen adres te verbergen; ssh -D en Tor bieden er allebei een.","Session (Layer 5)":"Sessie (laag 5)","Any TCP, and UDP":"Elke TCP, en UDP",Logins:"Inloggen","None, or user and password":"Geen, of gebruiker en wachtwoord","Offered by":"Aangeboden door","ssh -D, Tor, proxy servers":"ssh -D, Tor, proxyservers","Tunnel open":"Tunnel open","A few bytes, then just copying":"Een paar bytes, dan alleen kopiëren","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Vier piepkleine berichten vertelden de proxy waarheen hij moest verbinden; daarna kopieerde hij alleen nog bytes. De website zag het adres van de proxy, en omdat de laptop een naam stuurde in plaats van een adres, gebeurde zelfs de DNS-opzoeking bij de proxy. Druk op OPNIEUW om het nog eens te bekijken.","4 messages, 37 bytes":"4 berichten, 37 bytes","DNS lookup":"DNS-opzoeking","At the proxy":"Bij de proxy","Only the TLS inside":"Alleen de TLS erbinnen","TCP to port 1080":"TCP naar poort 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Een app die een SOCKS-proxy moet gebruiken (een browser, een gamelauncher of een tunnel gemaakt met ssh -D) opent er een TCP-verbinding naartoe, poort 1080. Het maakt SOCKS niet uit wat er doorheen gaat: het kan elke TCP-verbinding dragen.","Any TCP connection":"Elke TCP-verbinding","Wants to reach":"Wil bereiken","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Versie 5, en hoe in te loggen","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"De laptop stuurt drie bytes: versie 5, één aangeboden inlogmethode, en die methode, 0: geen login. De proxy antwoordt met twee: versie 5, methode 0. Had hij methode 2 gekozen, dan zou de app daarna een gebruikersnaam en wachtwoord sturen, als platte tekst.","Laptop sends":"Laptop stuurt","05 01 00 (3 bytes)":"05 01 00 (3 bytes)","Proxy answers":"Proxy antwoordt","05 00 (2 bytes)":"05 00 (2 bytes)","None needed here":"Hier niet nodig",GREETING:"BEGROETING","no login, please":"geen login, graag",METHOD:"METHODE","no login needed":"geen login nodig","Where To?":"Waarheen?","Connect to www.example.com:443":"Verbind met www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"De laptop vraagt de proxy te verbinden met www.example.com, poort 443. Hij geeft de naam in plaats van een adres, dus de proxy doet de DNS-opzoeking en de laptop hoeft er geen te doen. De proxy opent zijn eigen TCP-verbinding met de server en antwoordt dan: gelukt, met het adres en de poort waarvandaan hij verbond.","www.example.com (a name)":"www.example.com (een naam)","Succeeded, from 192.0.2.80:40220":"Gelukt, vanaf 192.0.2.80:40220",SUCCEEDED:"GELUKT","from 192.0.2.80:40220":"vanaf 192.0.2.80:40220","Copied both ways, unread":"Heen en terug gekopieerd, ongelezen","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Nu kopieert de proxy alleen nog. De app start TLS met de server: zijn Client Hello gaat erin via de verbinding van de laptop en komt ongewijzigd uit die van de proxy, en het antwoord van de server komt op dezelfde manier terug. De server ziet alleen ooit het adres van de proxy; de proxy ziet alleen versleutelde bytes.","The proxy’s address":"Het adres van de proxy","Encrypted bytes":"Versleutelde bytes","Same bytes":"Dezelfde bytes","On both connections":"Op beide verbindingen",unchanged:"ongewijzigd","+ encrypted handshake":"+ versleutelde handshake","Version 5, 1 method: no login":"Versie 5, 1 methode: geen login","Version 5, method chosen: no login":"Versie 5, gekozen methode: geen login","Succeeded, bound to 192.0.2.80:40220":"Gelukt, gebonden aan 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · begroeting","Methods offered":"Aangeboden methoden","0 (no login)":"0 (geen login)","SOCKS5 · method chosen":"SOCKS5 · gekozen methode","Method chosen":"Gekozen methode","SOCKS5 · connect request":"SOCKS5 · verbindingsverzoek","Open a TCP connection on my behalf.":"Open namens mij een TCP-verbinding.","Address type":"Adrestype","3 (domain name)":"3 (domeinnaam)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"De proxy zoekt de naam zelf op, dus de laptop hoeft zelf geen DNS-opzoeking te doen.","SOCKS5 · reply":"SOCKS5 · antwoord","0 (succeeded)":"0 (gelukt)","The address the proxy connects from.":"Het adres waarvandaan de proxy verbindt.",Offloading:"Offloading","Reverse Proxy":"Reverse proxy","TLS (SSL) offloading":"TLS (SSL) offloading","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Een reverse proxy staat voor de servers van een website: bezoekers verbinden met hem, en hij geeft hun verzoeken door aan een appserver erachter. Hij kan de last over veel servers verdelen, kopieën van pagina’s bewaren en aanvallen afslaan. Vaak doet hij ook het TLS-werk: HTTPS aan de rand ontsleutelen, zodat de servers erachter gewoon HTTP spreken. Dat is SSL- (of TLS-)offloading.","Visitors reach":"Bezoekers bereiken","The proxy, never the app":"De proxy, nooit de app","TLS ends":"TLS eindigt","At the proxy (offloading)":"Bij de proxy (offloading)","Plain HTTP (or TLS again)":"Gewoon HTTP (of weer TLS)",Adds:"Voegt toe","For example":"Bijvoorbeeld","nginx, HAProxy, cloud LBs":"nginx, HAProxy, cloud-load-balancers","Served from the edge":"Geleverd vanaf de rand","Encrypted outside, plain inside":"Buiten versleuteld, binnen leesbaar","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"De laptop zag één HTTPS-website. Daarachter ontsleutelde de reverse proxy het verzoek, vroeg een appserver via gewoon HTTP over het privénetwerk en versleutelde het antwoord voor de terugweg. Druk op OPNIEUW om het nog eens te bekijken.","Laptop ↔ proxy only":"Alleen laptop ↔ proxy","App learns visitor":"App kent bezoeker","From X-Forwarded-For":"Via X-Forwarded-For","Certificate kept":"Certificaat bewaard","On the proxy":"Op de proxy","The Front Door":"De voordeur","The proxy holds the certificate":"De proxy heeft het certificaat","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"De laptop opent https://www.example.com. Het adres dat DNS voor de naam geeft, is van de reverse proxy, die het certificaat van de site heeft en de TLS-handshake doet. Niets vertelt de laptop dat er nog een server achter zit.","Laptop connects to":"Laptop verbindt met","On the reverse proxy":"Op de reverse proxy","Also called":"Ook wel","Load balancer, edge":"Load balancer, edge","TLS Ends Here":"TLS eindigt hier","Offloading: the proxy does the TLS work":"Offloading: de proxy doet het TLS-werk","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"Het verzoek komt versleuteld binnen, en de reverse proxy ontsleutelt het. Dat is de offloading: het TLS-werk gebeurt hier, één keer, in plaats van op elke appserver. Nu kan de proxy de URL, headers en cookies lezen en daarop een server kiezen.","At the reverse proxy":"Bij de reverse proxy","Proxy can read":"Proxy kan lezen","URL, headers, cookies":"URL, headers, cookies","Then picks":"Kiest dan","An app server":"Een appserver","TLS ENDS HERE":"TLS EINDIGT HIER","In the Clear":"Onversleuteld","Passed on to the app server":"Doorgegeven aan de appserver","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"De proxy geeft het verzoek door over het privénetwerk van het datacenter, als gewoon HTTP naar poort 8080. Hij voegt X-Forwarded-For toe, het adres van de bezoeker, en X-Forwarded-Proto: https, hoe de bezoeker binnenkwam; anders zou de app alleen de proxy zien. Wie dit privénetwerk kan bekijken, kan alles lezen.","The App Answers":"De app antwoordt","In plain HTTP too":"Ook via gewoon HTTP","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"De appserver bouwt de pagina en antwoordt de proxy via gewoon HTTP: hij heeft nooit met TLS of certificaten te maken.","text/html, 12,500 bytes":"text/html, 12,500 bytes","readable inside":"binnen leesbaar","Encrypted Again":"Weer versleuteld","An ordinary HTTPS answer":"Een gewoon HTTPS-antwoord","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"De reverse proxy versleutelt het antwoord in de TLS-sessie die hij met de laptop heeft en stuurt het door. Van buiten is het een gewone HTTPS-site.","Laptop sees":"Laptop ziet","One HTTPS server":"Eén HTTPS-server","App servers":"Appservers","Never handle TLS":"Doen nooit TLS",Certificates:"Certificaten","Renewed in one place":"Op één plek vernieuwd","Three Options":"Drie opties","Offload, re-encrypt or pass through":"Offloaden, opnieuw versleutelen of doorlaten","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Offloading, zoals hier, is eenvoudig en snel, maar laat het verkeer binnen leesbaar. Opnieuw versleutelen opent een tweede TLS-verbinding van de proxy naar de appserver, zodat het ook binnen versleuteld blijft. Doorlaten stuurt de TLS-bytes door zonder ze te openen: het certificaat staat op de appservers, en de proxy kan alleen een server kiezen op adres en op de naam in de Client Hello, niet op URL.",Offload:"Offloaden","Plain HTTP inside":"Binnen gewoon HTTP","Re-encrypt":"Opnieuw versleutelen","TLS inside as well":"Ook binnen TLS","Pass through":"Doorlaten","Proxy can’t read it":"Proxy kan het niet lezen","PLAIN HTTP INSIDE":"BINNEN GEWOON HTTP","A Modern VPN":"Een moderne VPN","WireGuard (encrypted)":"WireGuard (versleuteld)","TCP beyond the VPN":"TCP voorbij de VPN",Keepalive:"Keepalive","VPN Server":"VPN-server","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"Een VPN draagt je verkeer in een versleutelde tunnel naar een VPN-server, die het doorstuurt naar internet. Op de wifi van een café zien anderen alleen versleutelde pakketten naar de VPN-server; websites zien het adres van de VPN-server in plaats van het jouwe. WireGuard is een moderne VPN: weinig code, één vaste set moderne algoritmen en een handshake van twee berichten.","UDP (51820 by default)":"UDP (standaard 51820)","2 messages, 1 round trip":"2 berichten, 1 rondreis",Crypto:"Cryptografie",Identity:"Identiteit","Public keys, like SSH":"Publieke sleutels, net als bij SSH","The WireGuard whitepaper":"De WireGuard-whitepaper","Tunnel up":"Tunnel actief","Encrypted to the VPN, plain beyond it":"Versleuteld tot de VPN, leesbaar daarna","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Twee handshakeberichten maakten de sleutels. Daarna werd elk pakket van de laptop in zijn geheel verzegeld in een UDP-pakket naar de VPN-server, en de website zag alleen het adres van de VPN-server. Voorbij de VPN-server is verkeer niet beter beschermd dan zonder VPN, dus HTTPS blijft belangrijk. Druk op OPNIEUW om het nog eens te bekijken.","Others nearby see":"Anderen in de buurt zien","UDP to 192.0.2.51":"UDP naar 192.0.2.51","Websites see":"Websites zien","The VPN server":"De VPN-server","Beyond the VPN":"Voorbij de VPN","Only HTTPS protects":"Alleen HTTPS beschermt",Overhead:"Overhead","60 bytes + padding":"60 bytes + opvulling","Set Up Once":"Eén keer instellen","Keys, not passwords":"Sleutels, geen wachtwoorden","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"De laptop draait de WireGuard-app met een korte configuratie: zijn eigen privésleutel, de publieke sleutel en het adres van de server (192.0.2.51, UDP-poort 51820), en AllowedIPs = 0.0.0.0/0, wat betekent dat alles door de tunnel gaat. In de tunnel is het adres van de laptop 10.8.0.2.","Inside address":"Adres binnen","Through the tunnel":"Door de tunnel","Everything (0.0.0.0/0)":"Alles (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"TUNNELADRES 10.8.0.2","Two messages, one round trip":"Twee berichten, één rondreis","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Zodra de laptop voor het eerst iets te sturen heeft, start hij een handshake: 148 bytes met een nieuwe publieke sleutel, zijn eigen vaste sleutel (versleuteld, zodat alleen de server weet wie belt) en de tijd (versleuteld, zodat een opname niet kan worden afgespeeld). De server antwoordt alleen sleutels die hij kent, hier met 92 bytes. Eén rondreis, en beide kanten hebben nieuwe sessiesleutels.",Initiation:"Initiatie","Server answers":"Server antwoordt","Only keys it knows":"Alleen bekende sleutels",INITIATION:"INITIATION","fresh key + identity":"nieuwe sleutel + identiteit",RESPONSE:"RESPONSE","keys agreed":"sleutels afgesproken","Into the Tunnel":"De tunnel in","A packet inside a packet":"Een pakket in een pakket","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Je opent https://www.example.com; ook het adres daarvan werd via de tunnel opgezocht (niet getoond). Het eerste pakket van de verbinding, een TCP SYN van 10.8.0.2 naar de webserver, wordt in zijn geheel versleuteld en in een UDP-pakket naar de VPN-server gestuurd. Op de wifi van het café is alleen het buitenste pakket te zien: van de laptop naar 192.0.2.51, poort 51820.",Outside:"Buiten","UDP to 192.0.2.51:51820":"UDP naar 192.0.2.51:51820","inside: TCP SYN to :443":"binnenin: TCP SYN naar :443","Out to the Web":"Het web op","Decrypted, then sent on":"Ontsleuteld, dan doorgestuurd","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"De VPN-server ontsleutelt het pakket, vervangt 10.8.0.2 door zijn eigen publieke adres (NAT) en stuurt de SYN door, één hop ouder (TTL 127). De SYN biedt een maximaal segment van 1380 bytes, niet 1460: de tunnel voegt aan elk pakket 60 bytes toe. De webserver ziet een bezoeker op 192.0.2.51 en antwoordt daarheen.","Website sees":"Website ziet","192.0.2.51 (the VPN)":"192.0.2.51 (de VPN)","Hidden from the site":"Verborgen voor de site","127 (one hop, the VPN)":"127 (één hop, de VPN)","from 192.0.2.51":"van 192.0.2.51","The Way Back":"De weg terug","Sealed again, for the laptop":"Opnieuw verzegeld, voor de laptop","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"Het antwoord gaat op dezelfde manier terug. De VPN-server verzegelt de SYN-ACK in een WireGuard-pakket voor de laptop, die het opent en aan Windows geeft alsof het rechtstreeks van de webserver kwam.",Counter:"Teller","Each side counts its own":"Elke kant telt zijn eigen",Replays:"Herhalingen","Thrown away":"Weggegooid","inside: TCP SYN-ACK":"binnenin: TCP SYN-ACK","Keeping It Open":"Openhouden","A keepalive, and new keys":"Een keepalive, en nieuwe sleutels","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Zonder iets te sturen wordt een WireGuard-tunnel stil. Omdat de laptop achter NAT zit, is hij ingesteld om elke 25 seconden een leeg pakket te sturen (PersistentKeepalive), een keepalive van 32 bytes, zodat de router de verbinding niet vergeet. Elke twee minuten maakt een nieuwe handshake nieuwe sleutels, en als de laptop naar een ander netwerk gaat, loopt de tunnel gewoon door vanaf zijn nieuwe adres.","Every 25 s, 32 bytes":"Elke 25 s, 32 bytes","New keys":"Nieuwe sleutels","Every 2 minutes":"Elke 2 minuten","New network":"Nieuw netwerk","The tunnel carries on":"De tunnel loopt door",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"leeg, 32 bytes","Message type":"Berichttype","Sender index":"Afzenderindex","A number this side picked for the session; the other side puts it in every packet it sends back.":"Een getal dat deze kant voor de sessie koos; de andere kant zet het in elk pakket dat hij terugstuurt.","Ephemeral key":"Tijdelijke sleutel","A new public key, made just for this handshake.":"Een nieuwe publieke sleutel, alleen voor deze handshake gemaakt.","Encrypted static key":"Versleutelde vaste sleutel","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"De vaste publieke sleutel van de laptop (32 bytes) en een tag van 16 bytes, versleuteld: alleen de server weet wie belt.","Encrypted timestamp":"Versleutelde tijdstempel","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"De tijd (12 bytes) en een tag, versleuteld. Een oude initiatie die opnieuw wordt gestuurd, wordt geweigerd.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Berekend met de publieke sleutel van de server: zonder die sleutel antwoordt de server helemaal niet.","Used only when the server is busy and asks for a cookie first.":"Alleen gebruikt als de server het druk heeft en eerst om een cookie vraagt.","Receiver index":"Ontvangerindex","The other side’s index: which session this packet belongs to.":"De index van de andere kant: bij welke sessie dit pakket hoort.","The server’s new public key for this handshake.":"De nieuwe publieke sleutel van de server voor deze handshake.","Encrypted nothing":"Versleuteld niets","Only a tag: it proves the server holds its private key.":"Alleen een tag: bewijst dat de server zijn privésleutel heeft.","Counts up with every packet; one seen before is thrown away.":"Telt op bij elk pakket; een pakket dat al gezien is, wordt weggegooid.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Het hele binnenste pakket, opgevuld tot een veelvoud van 16 bytes, dan een tag van 16 bytes.","then 12 bytes of padding, and the tag":"dan 12 bytes opvulling, en de tag","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"De laptop stuurde het met 128; de VPN-server haalde er 1 af toen hij het doorgaf.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Niets dan de tag van 16 bytes: een leeg pakket dat de tunnel openhoudt.","ESP (encrypted)":"ESP (versleuteld)","TCP beyond the gateway":"TCP voorbij de gateway","VPN Gateway":"VPN-gateway","IP Security":"IP Security","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec beschermt de IP-pakketten zelf. IKEv2 zet alles klaar: de twee kanten spreken algoritmen af, maken sleutels en bewijzen wie ze zijn met certificaten of andere inloggegevens. Daarna draagt ESP elk pakket versleuteld in een ander pakket. IPsec verbindt kantoren met elkaar en brengt laptops in bedrijfsnetwerken, en het zit ingebouwd in de meeste besturingssystemen en firewalls.","Behind NAT":"Achter NAT","ESP (IP protocol 50)":"ESP (IP-protocol 50)","Certificates, EAP, keys":"Certificaten, EAP, sleutels","IKE to set up, ESP to carry":"IKE om op te zetten, ESP om te dragen","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Vier IKE-berichten spraken algoritmen af, vonden de NAT, bewezen beide identiteiten en zetten de tunnel op. Daarna reisde elk pakket in zijn geheel in ESP, versleuteld en gecontroleerd, en verpakt in UDP om door de thuisrouter te komen. Druk op OPNIEUW om het nog eens te bekijken.","IKE messages":"IKE-berichten","4 (2 exchanges)":"4 (2 uitwisselingen)","NAT traversal":"NAT-traversal","One SPI each way":"Eén SPI per richting","Agree on algorithms, swap keys":"Algoritmen afspreken, sleutels wisselen","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"De VPN-client opent met IKE op UDP-poort 500. Zijn eerste bericht stelt de algoritmen voor (AES-GCM met 256-bits sleutels, SHA-256, Curve25519) en draagt een publieke sleutel en een willekeurige nonce; de gateway kiest het voorstel en stuurt zijn eigen sleutel en nonce. Beide delen nu een geheim, maar geen van beide heeft al bewezen wie hij is.",Proposed:"Voorgesteld","After this":"Hierna","Shared keys, no identities":"Gedeelde sleutels, geen identiteiten","proposal, key, nonce":"voorstel, sleutel, nonce","NAT detection":"NAT-detectie","chosen proposal, key, nonce":"gekozen voorstel, sleutel, nonce","A NAT in the Way":"Een NAT in de weg","So everything moves to port 4500":"Dus alles verhuist naar poort 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Beide berichten droegen ook hashes van het adres en de poort waarvandaan elke kant verstuurde. Bij de gateway komen ze niet overeen met wat aankwam: de thuisrouter herschreef onderweg het adres van de laptop (NAT). ESP heeft geen poortnummers, dus een NAT kan het niet doorlaten; beide kanten gaan over op UDP-poort 4500 en verpakken ESP vanaf nu in UDP.","Hashes of":"Hashes van","Address and port sent from":"Verzendadres en -poort",Mismatch:"Komt niet overeen","The router rewrote them":"De router herschreef ze",Fix:"Oplossing","Everything over UDP 4500":"Alles via UDP 4500","NAT DETECTED":"NAT GEDETECTEERD","Prove who you are, encrypted":"Bewijs wie je bent, versleuteld","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Nu versleuteld stuurt elke kant zijn identiteit, zijn certificaat en een handtekening over alles wat tot nu toe gezegd is, zodat iedereen ertussen betrapt zou worden. De laptop vraagt om een adres binnen het netwerk en krijgt 10.8.0.2. Dezelfde uitwisseling zet de ESP-tunnel zelf op, met eigen sleutels en een SPI per richting.","UDP 4500 (NAT traversal)":"UDP 4500 (NAT-traversal)","Identity, by certificate":"Identiteit, via certificaat","Laptop gets":"Laptop krijgt","10.8.0.2, and a DNS server":"10.8.0.2, en een DNS-server","identity, certificate":"identiteit, certificaat",signature:"handtekening","address 10.8.0.2":"adres 10.8.0.2","The whole packet, encrypted":"Het hele pakket, versleuteld","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Je opent https://www.example.com, opgezocht via de tunnel bij de DNS-server die de gateway gaf (niet getoond). De SYN van 10.8.0.2 wordt in zijn geheel versleuteld in een ESP-pakket: een SPI die de tunnel aanwijst, een volgnummer, dan het versleutelde pakket en een controlewaarde, alles binnen UDP-poort 4500. De UDP-checksum is nul: ESP controleert zijn eigen inhoud.","Names the tunnel":"Wijst de tunnel aan","The whole IP packet":"Het hele IP-pakket","62 bytes + padding":"62 bytes + opvulling","Out and Back":"Heen en terug","Through the gateway and home again":"Door de gateway en weer thuis","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"De gateway ontsleutelt het pakket en stuurt de SYN door vanaf zijn eigen adres, één hop ouder. Het antwoord komt terug bij de gateway en gaat door de tunnel terug als een nieuw ESP-pakket, met de SPI voor de richting van de laptop en eigen volgnummers.","192.0.2.51 (the gateway)":"192.0.2.51 (de gateway)","Each direction":"Elke richting","Its own SPI and keys":"Eigen SPI en sleutels","Which VPN?":"Welke VPN?","IPsec or WireGuard":"IPsec of WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec is ouder en heel flexibel: het onderhandelt over algoritmen, accepteert veel soorten inloggegevens en zit ingebouwd in Windows, macOS, iOS, Android en de meeste firewalls, en is daardoor de gebruikelijke manier om in een bedrijfsnetwerk te komen of twee kantoren te koppelen. WireGuard doet minder, met veel minder code en één vaste set algoritmen.","Built into":"Ingebouwd in","Also links":"Koppelt ook","Office to office":"Kantoor aan kantoor",Negotiates:"Onderhandelt over","Its algorithms (WireGuard: no)":"Zijn algoritmen (WireGuard: nee)","Initiator SPI":"Initiator-SPI","Picked by the laptop: which IKE session this is.":"Gekozen door de laptop: welke IKE-sessie dit is.","Responder SPI":"Responder-SPI","0 (not known yet)":"0 (nog niet bekend)","Next payload":"Volgende payload","Exchange type":"Uitwisselingstype","0x08 (initiator)":"0x08 (initiator)","Message ID":"Bericht-ID","Each request and its response share a number; the next exchange counts up.":"Elk verzoek en zijn antwoord delen een nummer; de volgende uitwisseling telt op.","SA payload":"SA-payload","Next payload, length":"Volgende payload, lengte",Proposal:"Voorstel","What the laptop offers; a real client often offers several.":"Wat de laptop aanbiedt; een echte client biedt er vaak meerdere aan.","KE payload":"KE-payload","DH group":"DH-groep","This side’s public key. From the two, both work out the same secret.":"De publieke sleutel van deze kant. Uit de twee berekenen beide hetzelfde geheim.","Nonce payload":"Nonce-payload","Notify payload":"Notify-payload",Notify:"Notify",Hash:"Hash","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Een hash van de SPI’s en het adres en de poort waarvandaan deze kant verstuurde. Klopt wat aankomt niet, dan heeft een NAT het onderweg gewijzigd.","The same for the address and port it sent to.":"Hetzelfde voor het adres en de poort waarnaar hij stuurde.","0x20 (response)":"0x20 (antwoord)","The one the server chose from the laptop’s offer.":"Het voorstel dat de server uit het aanbod van de laptop koos.","Non-ESP marker":"Non-ESP-marker","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Vier nulbytes: een IKE-bericht, geen ESP-pakket (ze delen poort 4500).","Encrypted payload":"Versleutelde payload","Encrypted payloads":"Versleutelde payloads","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Al het andere in dit bericht, versleuteld met de sleutels uit IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: wie de laptop is, bewezen","CP: asks for an inside address and DNS":"CP: vraagt om een intern adres en DNS","SA: what to use for ESP (AES-GCM)":"SA: wat te gebruiken voor ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: welk verkeer in de tunnel gaat","Integrity check":"Integriteitscontrole","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: wie de gateway is, bewezen","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: intern adres 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP met AES-GCM, en de SPI’s","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: alles (0.0.0.0/0)","0 (not used)":"0 (niet gebruikt)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP controleert zijn eigen inhoud, dus ESP in UDP laat dit op nul.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Bij welke tunnel (security association) dit hoort; de ontvangende kant koos hem tijdens IKE_AUTH.","Different for every packet.":"Voor elk pakket anders.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Het hele binnenste pakket, dan opvulling, de opvullengte en de volgende header (4: een IPv4-pakket).","then padding, pad length and next header (4)":"dan opvulling, opvullengte en volgende header (4)","Shows any change to the packet.":"Verraadt elke wijziging aan het pakket.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"De laptop stuurde het met 128; de gateway haalde er 1 af toen hij het doorgaf.","HTTP/3 over QUIC":"HTTP/3 over QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC is een nieuwer transport dat over UDP loopt en TLS 1.3 ingebouwd heeft. De eerste pakketten doen de transport- en de versleutelingshandshake tegelijk, zodat een paginaverzoek na één rondreis weg kan. Het draagt veel streams tegelijk, zodat één verloren pakket de rest niet ophoudt, en het overleeft een netwerkwissel. HTTP/3 is HTTP over QUIC.","Runs over":"Loopt over","UDP, port 443":"UDP, poort 443","TLS 1.3, always":"TLS 1.3, altijd","1 round trip (0 when returning)":"1 rondreis (0 bij terugkeer)",Streams:"Streams","Many, independent":"Veel, onafhankelijk","One round trip, then the request":"Eén rondreis, dan het verzoek","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC vouwde de transport- en TLS-handshakes samen tot één rondreis, zodat het verzoek 36 ms na het eerste pakket vertrok; over TCP en TLS had het twee keer zo lang gewacht. Alles na de eerste pakketten was versleuteld, zelfs het grootste deel van de header van elk pakket. Druk op OPNIEUW om het nog eens te bekijken.","1 before the request (TCP + TLS: 2)":"1 voor het verzoek (TCP + TLS: 2)","Lost packet":"Verloren pakket","Holds up one stream only":"Houdt maar één stream op","Choosing HTTP/3":"HTTP/3 kiezen","An earlier visit said it can":"Een eerder bezoek zei dat het kan",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Bij een eerder bezoek antwoordde de server met Alt-Svc: h3=":443", wat betekent dat hij ook HTTP/3 spreekt op UDP-poort 443 (DNS kan hetzelfde zeggen in een HTTPS-record). Dus deze keer slaat de browser TCP over en spreekt QUIC.',"Learned from":"Geleerd uit","Alt-Svc header, or DNS":"Alt-Svc-header, of DNS","QUIC over UDP 443":"QUIC over UDP 443","TLS 1.3, built in":"TLS 1.3, ingebouwd","Initial Packets":"Initial-pakketten","The Client Hello, straight away":"De Client Hello, meteen","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Er is geen aparte TCP-handshake: de allereerste pakketten dragen de TLS Client Hello. Met het post-quantum sleuteldeel is die 1,880 bytes, te groot voor één pakket, dus vult hij twee Initial-pakketten. Elk datagram wordt opgevuld tot minstens 1,200 bytes; een server mag maar drie keer zoveel terugsturen als hij ontving, zodat een vervalst afzenderadres hem geen versterker kan maken.","2 × 1,250 bytes":"2 × 1,250 bytes","The TLS Client Hello":"De TLS Client Hello","Readable?":"Leesbaar?","Yes (Initial keys are public)":"Ja (Initial-sleutels zijn openbaar)","Client Hello, part 1":"Client Hello, deel 1","Client Hello, part 2":"Client Hello, deel 2",padding:"opvulling","Then the certificate, encrypted":"Dan het certificaat, versleuteld","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"De server antwoordt met zijn Server Hello in een Initial-pakket. Beide kanten kunnen nu handshakesleutels berekenen, dus de rest (het certificaat, de handtekening en Finished) komt in Handshake-pakketten die alleen de laptop kan lezen. Vier datagrammen, ruim onder drie keer wat de laptop stuurde.","Certificate, signature, Finished":"Certificaat, handtekening, Finished","Server limit":"Serverlimiet","3× the bytes received":"3× de ontvangen bytes","certificate, Finished":"certificaat, Finished","The request, one round trip in":"Het verzoek, na één rondreis","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"De laptop controleert het certificaat en stuurt zijn Finished, en op hetzelfde moment zijn eerste HTTP/3-verzoek in een 1-RTT-pakket: een HEADERS-frame op stream 0, met headers gecomprimeerd met QPACK. Eén rondreis na het eerste pakket is het verzoek onderweg; TCP en TLS samen zouden er twee nodig hebben.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS op stream 0",Headers:"Headers","Compressed (QPACK)":"Gecomprimeerd (QPACK)","HTTP/3, stream 0":"HTTP/3, stream 0","The Response":"Het antwoord","On its own stream":"Op een eigen stream","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"De server bevestigt dat de handshake klaar is (HANDSHAKE_DONE) en antwoordt op stream 0: headers, dan de pagina. Elk verzoek krijgt een eigen stream, dus een verloren pakket houdt alleen de stream op waar het bij hoorde. Over TCP legt één ontbrekend segment alles erachter stil.","Frames on QUIC streams":"Frames op QUIC-streams","Holds up one stream":"Houdt één stream op","All but a few header bits":"Alles behalve een paar headerbits","the page":"de pagina","New Network":"Nieuw netwerk","Known by ID, not by address":"Herkend aan ID, niet aan adres","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Een QUIC-verbinding wordt herkend aan haar verbindings-ID’s, niet aan adressen en poorten. Als de laptop van wifi naar de hotspot van een telefoon gaat, verandert zijn adres maar loopt de verbinding door: de server controleert het nieuwe pad en gaat verder. En bij het volgende bezoek kan de browser zijn verzoek al in de allereerste pakketten sturen (0-RTT).","Known by":"Herkend aan","Connection ID":"Verbindings-ID","New address":"Nieuw adres","The connection carries on":"De verbinding loopt door","Next visit":"Volgend bezoek","0-RTT: request at once":"0-RTT: meteen een verzoek","SAME CONNECTION ON ANY NETWORK":"ZELFDE VERBINDING OP ELK NETWERK","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, deel 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, deel 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (Certificaat, deel 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (Certificaat, deel 2)","Initial packet":"Initial-pakket","Header type":"Headertype","long header, Initial":"lange header, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"De bovenste bits zeggen wat voor pakket dit is; de laatste bits zijn vermomd (headerbescherming).","Destination connection ID":"Bestemmings-verbindings-ID","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"Bij welke verbinding dit hoort. Elke kant kiest zijn eigen ID; de andere schrijft het hier.","Source connection ID":"Bron-verbindings-ID","Token length":"Tokenlengte","No token: the server hasn’t asked this client to prove its address first.":"Geen token: de server heeft deze client niet gevraagd eerst zijn adres te bewijzen.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Het pakketnummer en de payload. Wat volgt is een ander pakket in hetzelfde datagram.","Packet number":"Pakketnummer","Hidden by header protection, so nobody on the way can read or change it.":"Verborgen door headerbescherming, zodat niemand onderweg het kan lezen of wijzigen.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Versleuteld met sleutels die iedereen uit het verbindings-ID kan berekenen, dus het voorkomt ongelukken, geen meeluisteraars: de Client Hello erin is onderweg leesbaar.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, bytes 1–1,203 van 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, X25519MLKEM768-sleuteldeel","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, bytes 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, tot 1,250 bytes","ACK: packets 0–1 arrived":"ACK: pakketten 0–1 aangekomen","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, met zijn helft van de sleutel (1,120 bytes)","Handshake packet":"Handshake-pakket","long header, Handshake":"lange header, Handshake","Encrypted with keys from the key exchange so far.":"Versleuteld met sleutels uit de sleuteluitwisseling tot nu toe.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (begin)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (vervolg)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: de Initial van de server is aangekomen","ACK: the Handshake packets arrived":"ACK: de Handshake-pakketten zijn aangekomen","1-RTT packet":"1-RTT-pakket","short header":"korte header","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Alleen het ID van de ontvanger, en geen lengte: die kent de lengte van zijn eigen ID’s. Het blijft hetzelfde als de laptop van netwerk wisselt.","Encrypted with the session keys.":"Versleuteld met de sessiesleutels.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (de besturingsstream)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (QPACK-gecomprimeerd)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: de handshake is klaar","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, dan DATA: de pagina (1,000 bytes)","ACK: the response arrived":"ACK: het antwoord is aangekomen","Address Setup":"Adres instellen","No IPv6 address":"Geen IPv6-adres","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC en buren vinden","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"IPv6-adressen zijn 128 bits lang, genoeg om elk apparaat een eigen adres te geven. Een apparaat kan zichzelf meestal instellen zonder DHCP-server: het maakt een link-local adres, vraagt om een router en bouwt zijn globale adres uit het prefix dat de router aankondigt (SLAAC). Neighbour discovery, onderdeel van ICMPv6, vindt MAC-adressen en doet het werk dat ARP voor IPv4 doet.","128 bits":"128 bits",Addresses:"Adressen","SLAAC: no server needed":"SLAAC: geen server nodig","Replaces ARP":"Vervangt ARP","Neighbour discovery":"Neighbour discovery",Optional:"Optioneel","Two addresses, no DHCP":"Twee adressen, geen DHCP","Made by the laptop itself":"Gemaakt door de laptop zelf","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"De laptop maakte een link-local en een globaal adres, controleerde dat niemand anders ze had, en leerde zijn router, MTU en DNS-server uit één aankondiging. Toen er pakketten voor hem kwamen, vond neighbour discovery zijn MAC-adres. Druk op OPNIEUW om het nog eens te bekijken.","Link-local":"Link-local",Global:"Globaal","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + eigen ID","Router, DNS":"Router, DNS","From one advertisement":"Uit één aankondiging","6, all ICMPv6":"6, allemaal ICMPv6","Link-Local First":"Eerst link-local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Elke IPv6-interface krijgt een link-local adres, alleen bruikbaar op het eigen netwerk. De laptop maakt er een uit fe80:: en een willekeurig ogend interface-ID van 64 bits. Eerst controleert hij of niemand het al heeft: een Neighbor Solicitation die naar dat adres vraagt, gestuurd vanaf :: omdat hij het adres nog niet mag gebruiken. Niemand antwoordt, dus het is van de laptop.",Check:"Controle","Duplicate address detection":"Detectie van dubbele adressen","None: the address is free":"Geen: het adres is vrij","IS IT TAKEN?":"IS HET BEZET?","from ::":"vanaf ::","target fe80::8d2e:4f61:a9b0:7c13":"doel fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"GEEN ANTWOORD: ADRES IS VRIJ","Any Routers?":"Routers aanwezig?","A Router Solicitation":"Een Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Link-local adressen bereiken internet niet. De laptop stuurt een Router Solicitation naar ff02::2, het adres waar elke router op het netwerk naar luistert, met zijn eigen MAC-adres erbij.","ff02::2 (all routers)":"ff02::2 (alle routers)",Includes:"Bevat","ROUTERS?":"ROUTERS?","Router Answers":"Router antwoordt","Prefix, MTU and DNS in one message":"Prefix, MTU en DNS in één bericht","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"De router antwoordt naar ff02::1, elk apparaat op het netwerk, met een Router Advertisement: gebruik mij 30 minuten als uitgang, hier is mijn MAC-adres, de MTU is 1500, het prefix van het netwerk is 2001:db8:1234:5678::/64 en je mag er je eigen adres in maken, en vraag 2001:4860:4860::8888 voor DNS. Routers sturen deze ook uit zichzelf om de paar minuten.",Prefix:"Prefix","Make your own":"Maak je eigen","Yes (flag A)":"Ja (vlag A)",ADVERTISEMENT:"AANKONDIGING","prefix 2001:db8:1234:5678::/64":"prefix 2001:db8:1234:5678::/64","A Global Address":"Een globaal adres","Prefix + interface ID":"Prefix + interface-ID","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"De laptop voegt het prefix en zijn interface-ID samen tot een globaal adres, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, en controleert het op dezelfde manier. Windows maakt ook een tijdelijk adres met een willekeurig ID dat elke dag verandert, gebruikt voor uitgaande verbindingen zodat websites één apparaat niet aan zijn adres kunnen volgen.","Also made":"Ook gemaakt","A temporary address":"Een tijdelijk adres","target the global address":"doel het globale adres","Neighbour Lookup":"Buur opzoeken","Who has this address? (ARP’s job)":"Wie heeft dit adres? (het werk van ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Een antwoord van internet komt bij de router aan voor het globale adres van de laptop. Om het af te leveren heeft de router het bijbehorende MAC-adres nodig: hij stuurt een Neighbor Solicitation naar de solicited-node-groep van het adres, zodat alleen apparaten waarvan het adres op dezelfde manier eindigt überhaupt kijken. De laptop antwoordt met een Neighbor Advertisement met zijn MAC-adres.","Asked to":"Gevraagd aan","Instead of":"In plaats van","ARP broadcasts to everyone":"ARP-broadcasts naar iedereen","WHO HAS?":"WIE HEEFT?","the global address":"het globale adres","Ready, No DHCP":"Klaar, geen DHCP","And no NAT either":"En ook geen NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"De laptop staat op internet met zijn eigen globale adres, en geen NAT verandert het onderweg: het adres dat een website ziet, is dat van de laptop. De firewall van de thuisrouter weert nog steeds verbindingen waar niemand binnen om vroeg. Netwerken die adressen centraal willen uitdelen, kunnen in plaats daarvan DHCPv6 gebruiken.","Not needed":"Niet nodig",Incoming:"Inkomend","Blocked by the firewall":"Geblokkeerd door de firewall","Optional (flags M, O)":"Optioneel (vlaggen M, O)","ONLINE OVER IPv6":"ONLINE VIA IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Een multicast-MAC-adres: 33:33, dan de laatste vier bytes van het IPv6-adres.","Version, class, flow":"Versie, klasse, flow","IPv6, ordinary traffic, no flow label.":"IPv6, gewoon verkeer, geen flowlabel.","Payload length":"Payloadlengte","What follows this 40-byte header.":"Wat na deze header van 40 bytes komt.","Next header":"Volgende header","Hop limit":"Hoplimiet","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"Neighbour discovery moet met 255 aankomen, het bewijs dat geen router het doorgaf: het kwam van dit netwerk.","Unspecified: the laptop has no address it may use yet.":"Niet gespecificeerd: de laptop heeft nog geen adres dat hij mag gebruiken.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Solicited-node-multicast: alleen apparaten waarvan het adres op dezelfde 24 bits eindigt, luisteren.","Covers the message and both IPv6 addresses.":"Dekt het bericht en beide IPv6-adressen.",Target:"Doel","The address the laptop wants to use. If anyone answers, it’s taken.":"Het adres dat de laptop wil gebruiken. Antwoordt iemand, dan is het bezet.","A link-local address: usable only on this network.":"Een link-local adres: alleen bruikbaar op dit netwerk.","Every router on this network.":"Elke router op dit netwerk.","Source link-layer address":"Linklaagadres van bron","The sender’s MAC address, so nobody has to ask for it.":"Het MAC-adres van de afzender, zodat niemand ernaar hoeft te vragen.","Every device on this network.":"Elk apparaat op dit netwerk.","The hop limit devices here should put on their packets.":"De hoplimiet die apparaten hier op hun pakketten moeten zetten.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: neem adressen van DHCPv6. O: neem andere instellingen van DHCPv6. Beide uit: deze aankondiging bevat alles.","Router lifetime":"Routerlevensduur","How long the laptop may use this router as its way out.":"Hoelang de laptop deze router als uitgang mag gebruiken.","Reachable time":"Bereikbaarheidstijd","0 (not set)":"0 (niet ingesteld)","Retransmit timer":"Hertransmissietimer","The largest packet this network carries.":"Het grootste pakket dat dit netwerk vervoert.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, geldig 86,400 s, voorkeur 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Vlaggen L en A: adressen in dit prefix zitten op dit netwerk, en apparaten mogen hun eigen adres maken (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, voor 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Recursieve DNS-server: welke resolver te vragen, zodat daarvoor ook geen DHCP nodig is.","Whose MAC address is wanted.":"Wiens MAC-adres gezocht wordt.","The device this frame is for.":"Het apparaat waarvoor dit frame bedoeld is.","0x60000000: solicited, override":"0x60000000: solicited, override","Solicited: this answers a question. Override: replace any older entry for this address.":"Solicited: dit beantwoordt een vraag. Override: vervang elke oudere vermelding voor dit adres.","Target link-layer address":"Linklaagadres van doel","The answer: the MAC address that goes with the target.":"Het antwoord: het MAC-adres dat bij het doel hoort.","Setting the Clock":"De klok gelijkzetten","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Computerklokken lopen seconden per week uit de pas, en er hangt veel van af: certificaten hebben data, aanmeldingen en betalingen verlopen, logs van verschillende machines moeten op elkaar aansluiten. NTP zet een klok gelijk aan een tijdserver op internet. Eén klein verzoek en antwoord dragen vier tijdstempels, genoeg om uit te rekenen hoever de klok afwijkt en hoelang het netwerk erover deed.",Accuracy:"Nauwkeurigheid","A few milliseconds online":"Een paar milliseconden online","Clock set":"Klok gelijkgezet","Four timestamps, one answer":"Vier tijdstempels, één antwoord","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Eén verzoek en één antwoord leverden vier tijdstempels op. Daaruit rekende de laptop uit dat zijn klok 0.25 s achterliep en dat het netwerk heen en terug 24 ms nodig had, en begon zijn klok geleidelijk bij te trekken. Druk op OPNIEUW om het nog eens te bekijken.",Offset:"Afwijking","250.0 ms (slow)":"250.0 ms (achter)","Stratum 2":"Stratum 2","Next check":"Volgende controle","Minutes to days later":"Minuten tot dagen later","Clocks Drift":"Klokken lopen uit","The laptop’s clock is a little slow":"De klok van de laptop loopt iets achter","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Een computer houdt de tijd bij met een kwartskristal dat iets te snel of te traag loopt, dus klokken lopen seconden per week uit elkaar. De klok van deze laptop loopt een kwart seconde achter. Windows zet hem gelijk via time.windows.com, waarvan het adres al via DNS is opgezocht.","Laptop clock":"Klok van de laptop","0.25 s slow":"0.25 s achter","Time server":"Tijdserver","Why it matters":"Waarom het ertoe doet","Certificates, logins, logs":"Certificaten, aanmeldingen, logs","CLOCK 0.250 s SLOW":"KLOK 0.250 s ACHTER","Ask for the Time":"Vraag om de tijd","T1: when the request leaves":"T1: wanneer het verzoek vertrekt","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"De laptop stuurt een verzoek van 48 bytes naar poort 123. Hij schrijft de tijd volgens zijn eigen klok erin op het moment van vertrek: T1, 09:40:59.750. De rest is leeg.","T1 (laptop)":"T1 (laptop)",Mode:"Modus","3 (client)":"3 (client)","The Answer":"Het antwoord","T2 and T3 from the server, T4 on arrival":"T2 en T3 van de server, T4 bij aankomst","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"De server kopieert T1 terug en voegt T2 toe, wanneer het verzoek aankwam, en T3, wanneer zijn antwoord vertrekt, beide volgens zijn eigen nauwkeurige klok. Wanneer het antwoord aankomt, noteert de laptop T4 volgens zijn eigen klok. De server is stratum 2: hij zet zijn klok gelijk aan een stratum 1-server, die een gps-ontvanger of een atoomklok heeft.","T4 (laptop)":"T4 (laptop)",Stratum:"Stratum","The Offset":"De afwijking","Four times, two answers":"Vier tijden, twee antwoorden","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"De tijd op het netwerk, heen en terug, is (T4 − T1) − (T3 − T2) = 24.0 ms. De afwijking gaat ervan uit dat de reis heen en terug even lang duurt: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. De klok van de laptop loopt een kwart seconde achter. Een ongelijke route (de ene kant op trager dan de andere) zou het resultaat tot de helft van het verschil scheeftrekken.",Assumes:"Gaat uit van","Equal time each way":"Even lang heen als terug","OFFSET +250.0 ms":"AFWIJKING +250.0 ms","Ease It In":"Geleidelijk bijtrekken","No jumps backwards":"Geen sprongen terug","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Een kleine fout wordt niet in één sprong hersteld: de klok loopt een tijdje iets sneller tot hij is bijgetrokken, zodat de tijd voor draaiende programma’s nooit stilstaat of teruggaat. Alleen een grote fout wordt meteen rechtgezet. Naarmate een klok stabiliseert, vraagt een NTP-client minder vaak, van elke 64 seconden tot ongeveer elke 17 minuten; Windows zelf controleert time.windows.com veel minder vaak, eens per een aantal uur of minder.","Small offsets":"Kleine afwijkingen","Eased in gradually":"Geleidelijk bijgetrokken","Large offsets":"Grote afwijkingen","Set at once":"Meteen gezet","Asks again":"Vraagt opnieuw","Less often as it settles":"Minder vaak naarmate hij stabiliseert","CLOCK IN STEP":"KLOK GELIJK","Leap, version, mode":"Leap, versie, modus","Mode 3: a client asking for the time.":"Modus 3: een client die om de tijd vraagt.",Poll:"Poll","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Hoe vaak de client van plan is te vragen (2 tot de macht 6 seconden). Het groeit naarmate de klok stabiliseert.",Precision:"Precisie","How finely this clock can be read.":"Hoe fijn deze klok af te lezen is.","Root delay":"Root-vertraging","Root dispersion":"Root-spreiding","Reference ID":"Referentie-ID","Reference time":"Referentietijd","Origin time":"Oorsprongstijd","Receive time":"Ontvangsttijd","Transmit time":"Verzendtijd","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: wanneer het verzoek vertrok, volgens de eigen (verkeerde) klok van de laptop.","Mode 4: an answer from a server.":"Modus 4: een antwoord van een server.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Twee stappen van een referentieklok: hij volgt een stratum 1-server, die een eigen gps- of atoomklok heeft.","Round-trip time from this server to the reference clock.":"Rondreistijd van deze server naar de referentieklok.","How far off this server could be, at most.":"Hoeveel deze server hooguit kan afwijken.","192.0.2.123 (its own time source)":"192.0.2.123 (zijn eigen tijdbron)","When this server last set its own clock.":"Wanneer deze server zijn eigen klok voor het laatst gelijkzette.","T1, copied from the request: the client can match the answer to its question.":"T1, gekopieerd uit het verzoek: de client kan het antwoord aan zijn vraag koppelen.","T2: when the request arrived, by the server’s clock.":"T2: wanneer het verzoek aankwam, volgens de klok van de server.","T3: when this answer left.":"T3: wanneer dit antwoord vertrok.",Private:"Privé","Plain DNS":"Gewone DNS","DNS inside HTTPS":"DNS in HTTPS","DNS queries inside HTTPS":"DNS-vragen in HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"Gewone DNS reist onversleuteld: iedereen op dezelfde wifi, en je internetprovider, kan elke naam lezen die je opzoekt en zelfs de antwoorden veranderen. DNS over HTTPS (DoH) stuurt dezelfde DNS-berichten in een versleutelde HTTPS-verbinding naar de resolver, zodat ze er onderweg uitzien als elk ander webverkeer. Browsers en besturingssystemen kunnen het aanzetten.","Ordinary DNS messages":"Gewone DNS-berichten",Hides:"Verbergt","Which names you look up":"Welke namen je opzoekt",Similar:"Vergelijkbaar","DNS over TLS (port 853)":"DNS over TLS (poort 853)","Looked up in private":"Privé opgezocht","Same question, sealed":"Zelfde vraag, verzegeld","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"De gewone opzoeking kon door iedereen onderweg gelezen worden. Via HTTPS werd hetzelfde DNS-bericht in TLS verzegeld, alleen leesbaar voor de resolver. De resolver ziet nog steeds elke vraag, dus het vertrouwen verschuift naar hem, en de site die je daarna bezoekt is nog steeds aan zijn adres te zien. Druk op OPNIEUW om het nog eens te bekijken.","On the way":"Onderweg","Only “HTTPS to dns.google”":"Alleen ‘HTTPS naar dns.google’","The resolver":"De resolver","Still sees every name":"Ziet nog elke naam","The site’s address you then visit":"Het adres van de site die je daarna bezoekt","Can’t be changed on the way":"Kan onderweg niet gewijzigd worden","Readable by anyone on the way":"Leesbaar voor iedereen onderweg","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Dit is de opzoeking uit de andere lessen: een UDP-pakket naar poort 53 dat om www.example.com vraagt, en het antwoord. Geen van beide is versleuteld, dus iedereen op de wifi van het café, en de internetprovider, kan zien welke namen de laptop opzoekt, en zelfs met een vals adres antwoorden.","UDP port 53":"UDP-poort 53","Can be changed":"Te wijzigen","Yes, on the way":"Ja, onderweg",readable:"leesbaar","ANYONE HERE CAN READ IT":"IEDEREEN HIER KAN HET LEZEN","An HTTPS Link":"Een HTTPS-verbinding","TCP and TLS to dns.google":"TCP en TLS naar dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Met DNS over HTTPS aan opent de browser in plaats daarvan een HTTPS-verbinding naar de resolver: TCP naar poort 443 en een TLS-handshake voor dns.google. Hij houdt deze verbinding open en stuurt er elke opzoeking door.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, zoals elke website","Kept open":"Open gehouden","For every lookup":"Voor elke opzoeking","Sealed Question":"Verzegelde vraag","A DNS message in an HTTP request":"Een DNS-bericht in een HTTP-verzoek","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"De vraag is hetzelfde DNS-bericht als eerder. Het gaat in een HTTP/2-verzoek, GET /dns-query?dns= gevolgd door het bericht in base64url, met de vraag om een antwoord van het type application/dns-message. In TLS kan niemand onderweg het lezen.",Format:"Formaat","application/dns-message":"application/dns-message","Encrypted (TLS)":"Versleuteld (TLS)","DoH QUERY":"DoH-VRAAG","inside: GET /dns-query?dns=…":"binnenin: GET /dns-query?dns=…","Sealed Answer":"Verzegeld antwoord","The DNS answer in an HTTP response":"Het DNS-antwoord in een HTTP-antwoord","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"De resolver antwoordt 200 met een body van het type application/dns-message: hetzelfde DNS-antwoord als bij de gewone opzoeking, A 203.0.113.10. Omdat het via TLS van dns.google komt, kon niemand onderweg het wijzigen.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"Het DNS-antwoord (49 bytes)",Tampering:"Knoeien","Impossible on the way":"Onderweg onmogelijk","DoH ANSWER":"DoH-ANTWOORD","inside: A 203.0.113.10":"binnenin: A 203.0.113.10","What Still Shows":"Wat nog zichtbaar is","Hidden on the way, not from the resolver":"Verborgen onderweg, niet voor de resolver","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Onderweg zien de opzoekingen er nu uit als gewoon HTTPS-verkeer naar dns.google. Maar de resolver leest zelf elke vraag, dus je vertrouwt hem in plaats van wie je netwerk beheert. En de site die je daarna bezoekt, is nog steeds te zien aan zijn IP-adres, en aan zijn naam in de TLS Client Hello, tenzij hij Encrypted Client Hello ondersteunt. DNS over TLS doet hetzelfde werk op poort 853.","Sees every name":"Ziet elke naam","Then visible":"Daarna zichtbaar","The site’s IP, maybe its name":"Het IP van de site, misschien de naam",Alternative:"Alternatief","TRUST MOVES TO THE RESOLVER":"VERTROUWEN VERSCHUIFT NAAR DE RESOLVER","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: DNS-vraag)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: DNS-antwoord)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: de verbindingspreface en instellingen, dan het verzoek","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: instellingen, de antwoordheaders, dan het DNS-antwoord","Signed Answers":"Ondertekende antwoorden","Question and answer":"Vraag en antwoord","To the name servers":"Naar de nameservers","Signed answers":"Ondertekende antwoorden","DNS Security Extensions":"DNS Security Extensions","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Gewone DNS-antwoorden zijn te vervalsen: wie het eerst antwoordt, of ertussen zit, kan een vals adres sturen. Met DNSSEC kan een resolver controleren dat een antwoord echt van de eigenaar van het domein komt. Elke set records is ondertekend; de sleutel van elke zone wordt gegarandeerd door de bovenliggende zone, tot aan de root, waarvan de sleutel in resolvers is ingebouwd. DNSSEC bewijst dat antwoorden echt zijn; het verbergt ze niet.","Adds records":"Voegt records toe","Checked by":"Gecontroleerd door","Trust anchor":"Vertrouwensanker","The root’s key (built in)":"De sleutel van de root (ingebouwd)","Hides queries":"Verbergt vragen","No (that’s DoH)":"Nee (dat is DoH)","Answer checked":"Antwoord gecontroleerd","A chain of signatures to the root":"Een keten van handtekeningen tot de root","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"De resolver volgde een keten: het adres was ondertekend met de sleutel van example.com, die sleutel met de sleutelondertekeningssleutel, waarvoor .com instond met een ondertekend DS-record, en voor de sleutel van .com staat de root in, waarvan de sleutel in de resolver is ingebouwd. Een vervalst antwoord zou de keten gebroken hebben. Druk op OPNIEUW om het nog eens te bekijken.","Signatures checked":"Handtekeningen gecontroleerd","3 here (plus cached ones)":"Hier 3 (plus gecachete)","The AD flag":"De AD-vlag","Forged answer":"Vervalst antwoord","Fails the check":"Zakt voor de controle","Ask as Usual":"Vraag zoals altijd","The laptop’s question doesn’t change":"De vraag van de laptop verandert niet","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"De laptop vraagt zijn resolver zoals altijd naar www.example.com. De controle gebeurt bij de resolver, die de nameservers vraagt met de vlag DNSSEC OK aan: stuur de handtekeningen ook mee.","Checking done by":"Controle door","The resolver (8.8.8.8)":"De resolver (8.8.8.8)","Resolver sets":"Resolver zet","Signed Answer":"Ondertekend antwoord","An RRSIG comes with the A record":"Een RRSIG komt mee met het A-record","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"De resolver kent de nameserver van example.com al van eerdere opzoekingen. Die server stuurt het adres met een RRSIG-record: een handtekening over het A-record, gemaakt met de privésleutel van de zone. De RRSIG zegt welke sleutel ondertekende (sleutel 47362, de zoneondertekeningssleutel) en wanneer de handtekening verloopt. Om hem te controleren heeft de resolver die sleutel nodig.","RRSIG by key 47362":"RRSIG met sleutel 47362",Valid:"Geldig","31 Oct to 21 Nov 2026":"31 okt tot 21 nov 2026","signed by key 47362":"ondertekend met sleutel 47362","The Zone’s Keys":"De sleutels van de zone","DNSKEY records, signed too":"DNSKEY-records, ook ondertekend","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"De resolver vraagt om de sleutels van example.com. Het zijn er twee: de zoneondertekeningssleutel (vlaggen 256) die het A-record ondertekende, en de sleutelondertekeningssleutel (vlaggen 257), die alleen de set sleutels ondertekent. Daarmee controleert de resolver beide handtekeningen. Maar wie zegt dat deze sleutels van example.com zijn?","47362, zone-signing (256)":"47362, zoneondertekening (256)","61845, key-signing (257)":"61845, sleutelondertekening (257)","Keys signed by":"Ondertekenaar sleutels","The key-signing key":"De sleutelondertekeningssleutel","two keys":"twee sleutels","signed by key 61845":"ondertekend met sleutel 61845","Vouched by .com":"Gegarandeerd door .com","The parent’s DS record":"Het DS-record van de bovenliggende zone","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"De bovenliggende zone beantwoordt dat. De .com-servers hebben een DS-record voor example.com: een hash van zijn sleutelondertekeningssleutel, ondertekend met de eigen sleutel van .com. Klopt de hash met sleutel 61845, dan zijn de sleutels van example.com, wat .com betreft.","Hash of key 61845":"Hash van sleutel 61845","Signed by":"Ondertekend door",".com (key 19718)":".com (sleutel 19718)",Matches:"Komt overeen","hash of key 61845":"hash van sleutel 61845","signed by .com":"ondertekend door .com","Up to the Root":"Tot aan de root","Where the chain ends":"Waar de keten eindigt","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Daarboven gaat het net zo: voor de sleutels van .com staat een DS-record in de rootzone in, ondertekend met de sleutel van de root, en die sleutel is ingebouwd in elke validerende resolver: het vertrouwensanker. De resolver had die schakels in de cache, dus de keten is compleet: root → .com → example.com → het adres.",".com’s key":"Sleutel van .com","Vouched for by the root":"Gegarandeerd door de root","Root’s key":"Sleutel van de root","Built in (trust anchor)":"Ingebouwd (vertrouwensanker)","Root → .com → example.com":"Root → .com → example.com","CHAIN OF TRUST CHECKED":"VERTROUWENSKETEN GECONTROLEERD","A Checked Answer":"Een gecontroleerd antwoord","With the AD flag":"Met de AD-vlag","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"De resolver antwoordt de laptop met het adres en de AD-vlag: geauthenticeerde data. Was een handtekening mislukt, dan had de laptop een fout (SERVFAIL) gekregen in plaats van een vals adres. DNSSEC verbergt de vraag en het antwoord niet; daarvoor is er DNS over HTTPS.",Flag:"Vlag","AD (authenticated data)":"AD (geauthenticeerde data)","Bad signature":"Slechte handtekening","SERVFAIL, no address":"SERVFAIL, geen adres","AD: checked":"AD: gecontroleerd","UDP size 1232, DNSSEC OK = 1":"UDP-grootte 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Zegt hoe groot een UDP-antwoord mag zijn, en DNSSEC OK: stuur de handtekeningen ook mee.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, ondertekend met example.com-sleutel 47362, geldig 2026-10-31 tot 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Een handtekening over de records erboven, gemaakt met de privésleutel van de zone.","example.com, type DNSKEY, class IN":"example.com, type DNSKEY, klasse IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (zoneondertekeningssleutel 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Een van de publieke sleutels van de zone; wie een handtekening controleert, heeft hem nodig.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (sleutelondertekeningssleutel 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, ondertekend met example.com-sleutel 61845, geldig 2026-10-31 tot 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, type DS, klasse IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS sleutel 61845, SHA-256-digest (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Een hash van de sleutelondertekeningssleutel van de onderliggende zone, bewaard en ondertekend door de bovenliggende zone.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, ondertekend met com-sleutel 19718, geldig 2026-10-31 tot 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: antwoord, RD (recursie gewenst), RA (recursie beschikbaar), AD (geauthenticeerde data)","Wi-Fi Logins":"Wifi-aanmeldingen","EAP over Wi-Fi":"EAP via wifi","RADIUS Server":"RADIUS-server","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS en 802.1X (zakelijke wifi)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"Thuis deelt iedereen één wifiwachtwoord. Kantoren, universiteiten en eduroam gebruiken in plaats daarvan WPA2- of WPA3-Enterprise: elke persoon of elk apparaat meldt zich aan met een eigen account of certificaat, gecontroleerd door een RADIUS-server. Het access point kent geen wachtwoorden. Het geeft de aanmelding, een reeks EAP-berichten, door tussen de laptop en de server, en laat de laptop pas toe als de server ja zegt.","EAP (here EAP-TLS)":"EAP (hier EAP-TLS)",Keys:"Sleutels","Different for every login":"Elke aanmelding anders","Let in":"Toegelaten","Its own login, its own keys":"Eigen aanmelding, eigen sleutels","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"De laptop bewees met zijn certificaat wie hij was. De RADIUS-server controleerde het en zei het access point hem toe te laten, op VLAN 20, met een sleutel alleen voor deze aanmelding. Het access point zag nooit een wachtwoord: het gaf alleen de berichten door. Druk op OPNIEUW om het nog eens te bekijken.","EAP-TLS (certificates)":"EAP-TLS (certificaten)","17, then the 4-way handshake":"17, dan de 4-way handshake","20 (staff)":"20 (personeel)","A user leaves":"Iemand vertrekt","Disable one account":"Eén account uitschakelen","Who Are You?":"Wie ben je?","The access point asks for an identity":"Het access point vraagt om een identiteit","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"De laptop is verbonden met ‘Office’, een WPA2-Enterprise-netwerk, maar tot hij is aangemeld laat het access point niets door behalve aanmeldberichten. Het vraagt wie de laptop is met een EAP Identity-verzoek, en de laptop antwoordt alex@example.org. Het access point kent geen accounts: het geeft het antwoord door aan de RADIUS-server.","Before login":"Voor aanmelding","Only EAP gets through":"Alleen EAP komt erdoor","IDENTITY?":"IDENTITEIT?","EAP Identity request":"EAP Identity-verzoek",IDENTITY:"IDENTITEIT","Ask RADIUS":"Vraag RADIUS","The login goes to the server":"De aanmelding gaat naar de server","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Het access point kopieert het EAP-bericht in een RADIUS Access-Request en stuurt het naar de RADIUS-server op UDP-poort 1812, met het MAC-adres van de laptop en de naam van het netwerk. Een geheim dat alleen zij tweeën delen, beschermt elk pakket. De server antwoordt met een Access-Challenge: het volgende bericht voor de laptop, namelijk ‘start EAP-TLS’.","RADIUS server, UDP 1812":"RADIUS-server, UDP 1812","A shared secret":"Een gedeeld geheim","from the access point":"van het access point","EAP-TLS start":"EAP-TLS-start","TLS START":"TLS-START","TLS Inside EAP":"TLS in EAP","The server proves who it is":"De server bewijst wie hij is","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"De laptop en de server voeren nu een TLS 1.3-handshake uit binnen EAP; het access point verpakt elk bericht opnieuw, EAPOL door de lucht en RADIUS over de kabel. De server stuurt zijn certificaat en vraagt om dat van de laptop. De laptop controleert of het door de eigen certificaatautoriteit van het bedrijf aan radius.example.org is uitgegeven. Die controle voorkomt dat een nep-access point de aanmelding onderschept.","TLS 1.3, inside EAP":"TLS 1.3, binnen EAP","Its certificate":"Zijn certificaat","Laptop checks":"Laptop controleert","Issuer and name":"Uitgever en naam","TLS inside EAP":"TLS in EAP","certificate (encrypted)":"certificaat (versleuteld)","Laptop’s Proof":"Bewijs van de laptop","Its own certificate":"Zijn eigen certificaat","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"De laptop antwoordt met zijn eigen certificaat, door het bedrijf voor deze gebruiker uitgegeven, en een handtekening gemaakt met zijn privésleutel; de sleutel verlaat de laptop nooit. Er komt geen wachtwoord aan te pas. De server controleert het certificaat en de handtekening en zoekt het account op. Veel netwerken, waaronder eduroam, gebruiken in plaats daarvan een wachtwoord, verstuurd binnen de TLS-tunnel (PEAP of EAP-TTLS).","Its certificate, a signature":"Zijn certificaat, een handtekening","None with EAP-TLS":"Geen bij EAP-TLS","Or instead":"Of in plaats daarvan","PEAP: a password in TLS":"PEAP: een wachtwoord in TLS",CERTIFICATE:"CERTIFICAAT","laptop’s certificate":"certificaat van de laptop","Handshake Done":"Handshake klaar","Nothing more to send":"Niets meer te sturen","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Met TLS 1.3 stuurt de server daarna één piepklein versleuteld bericht, één byte 0, om te zeggen dat de handshake klaar is, en de laptop antwoordt met een leeg EAP-bericht. Beide kanten hebben nu dezelfde 64 bytes sleutelmateriaal, berekend tijdens de handshake. Niemand onderweg heeft het gezien, zelfs het access point niet.","Server sends":"Server stuurt","One encrypted 0 byte":"Eén versleutelde byte 0","An empty EAP-TLS reply":"Een leeg EAP-TLS-antwoord","Both hold":"Beide hebben","64 bytes of key material":"64 bytes sleutelmateriaal","handshake over":"handshake klaar","one encrypted byte":"één versleutelde byte",EMPTY:"LEEG","nothing more":"niets meer","empty EAP-TLS":"leeg EAP-TLS","And a key for the access point":"En een sleutel voor het access point","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"De server antwoordt Access-Accept. Daarin zitten EAP Success voor de laptop; de eerste 32 bytes van het sleutelmateriaal voor het access point, versleuteld met het gedeelde geheim (MS-MPPE-Recv-Key); en VLAN 20, zodat deze gebruiker op het personeelsnetwerk komt. Hetzelfde access point zou een andere gebruiker op een ander VLAN kunnen zetten.","AP gets":"AP krijgt","The key (MS-MPPE-Recv-Key)":"De sleutel (MS-MPPE-Recv-Key)","key, VLAN 20":"sleutel, VLAN 20","4-Way Handshake":"4-way handshake","As at home, from a different key":"Net als thuis, vanuit een andere sleutel","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Het access point en de laptop hebben nu dezelfde sleutel van 32 bytes, de PMK. Wat volgt is de 4-way handshake uit de wifiles; alleen de herkomst van de PMK verschilt. Thuis komt die uit het gedeelde wachtwoord, hier uit deze ene aanmelding, dus elke gebruiker krijgt andere sleutels.","PMK from":"PMK uit","This login":"Deze aanmelding","At home":"Thuis","From the shared password":"Uit het gedeelde wachtwoord","Encrypted data (CCMP)":"Versleutelde data (CCMP)","group key, MIC":"groepssleutel, MIC","Why Enterprise":"Waarom Enterprise","One account per person":"Eén account per persoon","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Als iemand vertrekt, wordt zijn account uitgeschakeld en hoeft niemand anders een wachtwoord te wijzigen. Elke aanmelding krijgt eigen sleutels, zodat gebruikers elkaars verkeer niet kunnen lezen, en de RADIUS-server registreert wie wanneer verbinding maakte. eduroam werkt net zo: de aanmelding van een bezoeker voor gebruiker@zijn-universiteit gaat van RADIUS-server naar RADIUS-server tot hij bij zijn eigen universiteit aankomt.","Different for every user":"Anders voor elke gebruiker",eduroam:"eduroam","Login passed home":"Aanmelding naar huis doorgegeven","ONE ACCOUNT PER PERSON":"EÉN ACCOUNT PER PERSOON","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, certificaat","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, versleutelde handshake","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: versleutelde handshake","Access-Request id=83: encrypted handshake":"Access-Request id=83: versleutelde handshake","0 (EAP packet)":"0 (EAP-pakket)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Draagt een EAP-bericht. Het access point kopieert het in een RADIUS-pakket voor de server, en terug.","A response carries the same number as the request it answers.":"Een antwoord draagt hetzelfde nummer als het verzoek waarop het antwoordt.","Who are you?":"Wie ben je?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Wie zich aanmeldt. Het realm na de @ vertelt de RADIUS-server (of de servers die verzoeken doorgeven) waar het account staat.","Seen on the office network":"Gezien op het kantoornetwerk","The server. It is on the same network, so the frame goes straight to it, not through the router.":"De server. Hij zit op hetzelfde netwerk, dus het frame gaat rechtstreeks naar hem, niet via de router.","The access point’s wired port.":"De bekabelde poort van het access point.","Should this device be let in?":"Moet dit apparaat worden toegelaten?","A reply carries the number of the request it answers.":"Een antwoord draagt het nummer van het verzoek waarop het antwoordt.",Authenticator:"Authenticator","Random, new in every request.":"Willekeurig, nieuw bij elk verzoek.",Attributes:"Attributen","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Een HMAC-MD5 van het hele pakket, berekend met het gedeelde geheim. Elk pakket met EAP moet er een hebben; sinds de Blast-RADIUS-aanval van 2024 staat hij vooraan.","The identity the laptop gave.":"De identiteit die de laptop gaf.","The access point asking.":"Het access point dat vraagt.","The access point’s MAC address and the network’s name.":"Het MAC-adres van het access point en de naam van het netwerk.","The laptop’s MAC address.":"Het MAC-adres van de laptop.","Keep each EAP message small enough for one frame.":"Houd elk EAP-bericht klein genoeg voor één frame.","The EAP packet, passed on unchanged.":"Het EAP-pakket, ongewijzigd doorgegeven.","The server’s network card.":"De netwerkkaart van de server.","Not yet: here is the next message for the device.":"Nog niet: hier is het volgende bericht voor het apparaat.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Een hash van dit antwoord, de authenticator van het verzoek en het gedeelde geheim: alleen de echte server kan hem gemaakt hebben.","A TLS handshake, carried inside EAP.":"Een TLS-handshake, gedragen binnen EAP.","0x20 (start)":"0x20 (start)","Start: the server is ready for the laptop’s Client Hello.":"Start: de server is klaar voor de Client Hello van de laptop.","The server’s bookmark for this login: the access point sends it back with the next request.":"De bladwijzer van de server voor deze aanmelding: het access point stuurt hem terug met het volgende verzoek.","0x80 (length included)":"0x80 (lengte inbegrepen)","TLS length":"TLS-lengte","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Langere TLS-berichten worden opgesplitst in stukken van ongeveer 1,000 bytes, elk bevestigd.","TLS records":"TLS-records","The same TLS records as over TCP, only carried in EAP.":"Dezelfde TLS-records als over TCP, alleen gedragen in EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, het sleuteldeel van de laptop","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Het EAP-pakket (1,008 bytes), verdeeld over 4 attributen van maximaal 253 bytes.","EAP-Message, continued":"EAP-Message, vervolg","TLS records, continued":"TLS-records, vervolg","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, het sleuteldeel van de server","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Versleuteld: certificaat voor radius.example.org, een verzoek om het certificaat van de laptop, handtekening, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Versleuteld: het certificaat van de laptop (voor alex@example.org), zijn handtekening, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Het EAP-pakket (822 bytes), verdeeld over 4 attributen van maximaal 253 bytes.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Versleuteld: één byte 0, het ‘commitment message’: geen handshakeberichten meer","0x00 (no data)":"0x00 (geen data)","Nothing to send: an empty answer that keeps the conversation going.":"Niets te sturen: een leeg antwoord dat het gesprek gaande houdt.","Yes: let it in.":"Ja: laat hem toe.","Put this device on VLAN 20, the staff network.":"Zet dit apparaat op VLAN 20, het personeelsnetwerk.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"De eerste 32 bytes van het sleutelmateriaal dat beide kanten van de TLS-handshake berekenden. Het access point gebruikt het als PMK, de startsleutel voor de 4-way handshake.","Salt, encrypted key":"Salt, versleutelde sleutel","Encrypted with the shared secret, so only the access point can read the key.":"Versleuteld met het gedeelde geheim, zodat alleen het access point de sleutel kan lezen.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"De volgende 32 bytes van het sleutelmateriaal. Wifi heeft ze niet nodig.","The RADIUS server accepted the login.":"De RADIUS-server heeft de aanmelding geaccepteerd.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (aanmeldingen gecontroleerd door een RADIUS-server)","Shared Folders":"Gedeelde mappen",Responses:"Antwoorden","nas (File Server)":"nas (bestandsserver)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB is hoe Windows bestanden en printers deelt: \\\\server\\share in Verkenner, een toegewezen netwerkstation, een NAS thuis. macOS en Linux spreken het ook. Over één TCP-verbinding naar poort 445 spreekt de client een versie af, meldt zich aan en verbindt met een share, en opent, leest, schrijft en sluit daarna bestanden met genummerde verzoeken.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM of Kerberos",Protection:"Bescherming","Signing, optional encryption":"Ondertekening, optioneel versleuteling","File read":"Bestand gelezen","Seven requests, one connection":"Zeven verzoeken, één verbinding","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Over één TCP-verbinding sprak de laptop SMB 3.1.1 af, meldde zich aan met NTLM zonder zijn wachtwoord te sturen, verbond met de share en las een bestand van 240 KB met één verzoek. Elk bericht na de aanmelding was ondertekend. Druk op OPNIEUW om het nog eens te bekijken.","7 on one connection":"7 op één verbinding","NTLMv2, no password sent":"NTLMv2, geen wachtwoord verstuurd","240 KB in 169 segments":"240 KB in 169 segmenten",Signed:"Ondertekend","Every message after login":"Elk bericht na aanmelding","Port 445":"Poort 445","A TCP connection to the NAS":"Een TCP-verbinding naar de NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"De laptop opent \\\\nas\\Documents, een gedeelde map op de NAS. Hij vindt het adres van nas met een lokale naamopzoeking en opent een TCP-verbinding naar poort 445. De pakketten gaan via de thuisrouter naar de NAS en verlaten het thuisnetwerk nooit.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Blijft","On the home network":"Op het thuisnetwerk",Negotiate:"Negotiate","Agree on a version":"Een versie afspreken","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"De laptop somt elke SMB-versie op die hij spreekt, van 2.0.2 tot 3.1.1, en zegt dat hij ondertekening vereist. De NAS kiest 3.1.1, de nieuwste. Beide kanten houden een SHA-512-hash bij van alles wat vanaf hier tot het einde van de aanmelding wordt uitgewisseld. Die gaat de sleutels in, dus als iemand deze berichten onderweg wijzigde, bijvoorbeeld om een oudere versie af te dwingen, zou de aanmelding mislukken.",Chosen:"Gekozen","Tamper check":"Knoeicontrole","SHA-512 of the exchange":"SHA-512 van de uitwisseling","signing required":"ondertekening vereist","NTLM Challenge":"NTLM-challenge","The NAS sends a random number":"De NAS stuurt een willekeurig getal","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"Een NAS thuis heeft geen domein, dus geen Kerberos: de laptop meldt zich aan met NTLM. Zijn eerste SESSION_SETUP zegt dat hij wil aanmelden, en de NAS antwoordt ‘meer verwerking nodig’ met een challenge van 8 willekeurige bytes. Hij geeft deze aanmelding ook een sessie-ID.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (in een domein: Kerberos)",Challenge:"Challenge","More processing required":"Meer verwerking nodig","NTLM: let me log in":"NTLM: laat me aanmelden","a session ID":"een sessie-ID","NTLM Response":"NTLM-antwoord","Proof, not the password":"Bewijs, niet het wachtwoord","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"De laptop antwoordt met de gebruikersnaam, alex, en een NTLMv2-antwoord: een HMAC van de challenge en een paar andere waarden, berekend met een hash van het wachtwoord. De NAS heeft dezelfde hash en berekent dezelfde waarde. Het wachtwoord zelf gaat nooit over het netwerk, en beide kanten hebben nu een sessiesleutel om berichten mee te ondertekenen.",User:"Gebruiker",alex:"alex",Sends:"Stuurt","An HMAC of the challenge":"Een HMAC van de challenge","Never sent":"Nooit verstuurd","user alex":"gebruiker alex","NTLMv2 response":"NTLMv2-antwoord","LOGGED IN":"AANGEMELD",signed:"ondertekend","Connect a Share":"Een share verbinden","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT vraagt om de share met zijn volledige naam, \\\\nas\\Documents. Het antwoord geeft hem een tree-ID en zegt wat deze gebruiker er mag doen. Elk bericht is nu ondertekend: elk draagt een tag over het hele bericht, gemaakt met een sleutel uit de aanmelding, zodat een gewijzigd of vervalst bericht zou opvallen.",Share:"Share","Every message":"Elk bericht","Signed (AES-GMAC)":"Ondertekend (AES-GMAC)","tree ID 0x2a51":"tree-ID 0x2a51","Open the File":"Het bestand openen","With CREATE":"Met CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB opent bestanden met CREATE, waarmee ook nieuwe gemaakt kunnen worden. Deze opent report.pdf om te lezen en mislukt als het niet bestaat. Het antwoord geeft de grootte en data van het bestand, en een bestands-ID dat het lezen en sluiten zullen gebruiken.",Handle:"Handle","A 16-byte file ID":"Een bestands-ID van 16 bytes","open to read":"openen om te lezen","file ID":"bestands-ID","Read It":"Het lezen","The whole file in one request":"Het hele bestand in één verzoek","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Eén READ vraagt om het hele bestand, 245,760 bytes vanaf offset 0. Het kost 4 credits, één per 64 KB. Het antwoord is 80 bytes headers en dan het bestand, in 169 TCP-segmenten. Een groter bestand wordt met meerdere verzoeken gelezen, veel tegelijk onderweg, zover de credits het toelaten.","245,760 bytes from 0":"245,760 bytes vanaf 0",Credits:"Credits","4 (one per 64 KB)":"4 (één per 64 KB)","Arrives in":"Komt aan in","from offset 0":"vanaf offset 0","Close the File":"Het bestand sluiten","And keep 445 at home":"En houd 445 thuis","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE geeft het bestands-ID terug; de verbinding blijft open voor het volgende bestand. SMB 3 kan ook elk bericht versleutelen met AES-GCM, voor één share of een hele server. Hier beschermt alleen ondertekening de berichten, dus iedereen op het netwerk kan het bestand lezen terwijl het voorbijkomt. Poort 445 mag nooit bereikbaar zijn vanaf internet: de WannaCry-worm (2017) verspreidde zich via een lek in het oude SMB1.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, optioneel","Switched off: old, unsafe":"Uitgeschakeld: oud, onveilig","Never open to the internet":"Nooit open naar internet",done:"klaar","KEEP PORT 445 OFF THE INTERNET":"HOUD POORT 445 WEG VAN INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Op poort 445 begint elk SMB-bericht met zijn lengte, een overblijfsel van NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 of 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'SMB1-berichten begonnen met 0xFF "SMB". SMB1 staat in Windows tegenwoordig uit.',"Header size":"Headergrootte","Credit charge":"Creditkosten","Channel sequence":"Kanaalvolgorde","Credits asked for":"Gevraagde credits","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Credits beperken hoeveel verzoeken de laptop tegelijk kan laten wachten. De server deelt ze uit.","Next command":"Volgende opdracht","0 (none chained)":"0 (geen gekoppeld)","Counts up with each request; the response carries the same number.":"Telt op bij elk verzoek; het antwoord draagt hetzelfde nummer.","0 (no share yet)":"0 (nog geen share)","Session ID":"Sessie-ID","0 (not logged in yet)":"0 (nog niet aangemeld)","zeros (not signed)":"nullen (niet ondertekend)","Structure size":"Structuurgrootte","Dialect count":"Aantal dialecten","Security mode":"Beveiligingsmodus","0x0002 (signing required)":"0x0002 (ondertekening vereist)","Recent versions of Windows 11 require signing by default.":"Recente versies van Windows 11 vereisen standaard ondertekening.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, leases, grote lees- en schrijfacties, multichannel, persistente handles, directory-leases, versleuteling.","Client GUID":"Client-GUID","A random ID for this computer.":"Een willekeurig ID voor deze computer.","Negotiate contexts":"Negotiate-contexten","at offset 112, 4 of them":"op offset 112, 4 stuks",Dialects:"Dialecten","Every version the laptop speaks. The server picks the newest it also knows.":"Elke versie die de laptop spreekt. De server kiest de nieuwste die hij ook kent.",Contexts:"Contexten","SMB 3.1.1 extras, each in its own small block.":"Extra’s van SMB 3.1.1, elk in een eigen klein blok.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Integriteit vóór authenticatie: SHA-512, en een willekeurige salt van 32 bytes","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Versleuteling: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Ondertekening: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"De naam van de server: nas","Credits granted":"Toegekende credits","0x00000001 (response)":"0x00000001 (antwoord)","0x0001 (signing enabled)":"0x0001 (ondertekening ingeschakeld)",Dialect:"Dialect","The newest version both sides speak.":"De nieuwste versie die beide kanten spreken.","Context count":"Aantal contexten","Server GUID":"Server-GUID","Leases, large reads and writes.":"Leases, grote lees- en schrijfacties.","Largest read, write":"Grootste lees-, schrijfactie","8 MB each":"8 MB elk","The most data one request may carry: transactions, reads and writes.":"De meeste data die één verzoek mag dragen: transacties, lees- en schrijfacties.","System time":"Systeemtijd","7 Nov 2026, 09:41:00":"7 nov 2026, 09:41:00","Security buffer":"Beveiligingsbuffer","Context offset":"Contextoffset","Security blob":"Beveiligingsblob","GSS-API and SPNEGO wrapping, around NTLMSSP.":"GSS-API- en SPNEGO-verpakking, rond NTLMSSP.","The login methods the server accepts: NTLMSSP":"De inlogmethoden die de server accepteert: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Integriteit vóór authenticatie: SHA-512, en de eigen salt van de server","Encryption: AES-128-GCM":"Versleuteling: AES-128-GCM","Signing: AES-GMAC":"Ondertekening: AES-GMAC","0x02 (signing required)":"0x02 (ondertekening vereist)","Previous session":"Vorige sessie","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: de NTLM-opties die de laptop ondersteunt","Not an error: the login needs another round.":"Geen fout: de aanmelding heeft nog een ronde nodig.","The server’s number for this login, from now on in every message.":"Het nummer van de server voor deze aanmelding, vanaf nu in elk bericht.","Session flags":"Sessievlaggen","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: een willekeurige challenge van 8 bytes","The NAS’s names and its clock":"De namen van de NAS en zijn klok","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: gebruiker alex, computer ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"NTLMv2-antwoord: een HMAC van de challenge, berekend met een hash van het wachtwoord","A key for signing, encrypted":"Een sleutel voor ondertekening, versleuteld","0x00000009 (response, signed)":"0x00000009 (antwoord, ondertekend)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC over het hele bericht, met een sleutel uit de aanmelding: een gewijzigd of vervalst bericht zou opvallen.","The login is complete.":"De aanmelding is voltooid.","0x00000008 (signed)":"0x00000008 (ondertekend)","Server and share name, in UTF-16.":"Server- en sharenaam, in UTF-16.","The number for this share; later requests carry it.":"Het nummer voor deze share; latere verzoeken dragen het.","Share type":"Sharetype","1 (disk)":"1 (schijf)","Share flags":"Sharevlaggen","Encryption not required for this share; signing still protects every message.":"Versleuteling niet vereist voor deze share; ondertekening beschermt nog steeds elk bericht.","0x001f01ff (full control)":"0x001f01ff (volledig beheer)","What this user may do in the share.":"Wat deze gebruiker in de share mag doen.","Oplock, impersonation":"Oplock, imitatie","none, 2 (impersonation)":"geen, 2 (imitatie)","Desired access":"Gewenste toegang","0x00120089 (read)":"0x00120089 (lezen)","Read the data, its attributes and its permissions.":"De data, de attributen en de rechten lezen.","File attributes":"Bestandsattributen","Share access":"Gedeelde toegang","0x00000001 (read)":"0x00000001 (lezen)","Others may read the file while it is open, but not change it.":"Anderen mogen het bestand lezen terwijl het open is, maar niet wijzigen.",Disposition:"Dispositie","1 (open, fail if missing)":"1 (openen, mislukken als het ontbreekt)","0x00000040 (a file, not a folder)":"0x00000040 (een bestand, geen map)",Name:"Naam","Create contexts":"Create-contexten","File name":"Bestandsnaam","Relative to the share.":"Ten opzichte van de share.","Oplock, flags":"Oplock, vlaggen","none, 0":"geen, 0",Action:"Actie","1 (opened)":"1 (geopend)",Times:"Tijden","created, accessed, written, changed":"gemaakt, geopend, geschreven, gewijzigd","Windows FILETIME: 100-nanosecond steps since 1601.":"Windows FILETIME: stappen van 100 nanoseconden sinds 1601.","Allocation size":"Toewijzingsgrootte","File size":"Bestandsgrootte","0x00000020 (archive)":"0x00000020 (archief)","File ID":"Bestands-ID","The handle for the open file: reads and the close name it.":"De handle voor het geopende bestand: lees- en sluitacties noemen hem.","A big read costs one credit per 64 KB.":"Een grote leesactie kost één credit per 64 KB.","Padding, flags":"Opvulling, vlaggen","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Waar de server de data in zijn antwoord moet zetten: 80 bytes vanaf het begin, direct na de headers.","The whole file in one request.":"Het hele bestand in één verzoek.","Minimum, channel, remaining":"Minimum, kanaal, resterend","Channel info":"Kanaalinfo","Data offset":"Data-offset","Data length":"Datalengte","Remaining, flags":"Resterend, vlaggen","The file itself; its contents are not part of the lesson.":"Het bestand zelf; de inhoud ervan hoort niet bij de les.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"De laptop vroeg niet om de details van het bestand, dus de rest is nul.","Times, sizes, attributes":"Tijden, groottes, attributen","Talking to a PLC":"Praten met een PLC",Switch:"Switch","Plant network":"Installatienetwerk","Modbus/TCP, for industrial control":"Modbus/TCP, voor industriële besturing","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus is een van de oudste en meest gebruikte protocollen in industriële besturing (OT, operationele technologie): PLC’s, sensoren, motoraandrijvingen en meters in fabrieken, waterbedrijven en gebouwen spreken het. Een client leest en schrijft genummerde registers en coils op een apparaat. Modbus/TCP draagt dezelfde kleine berichten over TCP-poort 502, zonder aanmelding en zonder versleuteling.","1979, by Modicon":"1979, door Modicon","16-bit registers, on/off coils":"16-bits registers, aan/uit-coils","None built in":"Niets ingebouwd","Modbus.org specifications":"Specificaties van Modbus.org","Pump running":"Pomp draait","Simple, and wide open":"Eenvoudig, en wagenwijd open","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"De laptop las vier registers, wijzigde een setpoint en startte een pomp, elk met een verzoek van 12 bytes en een kort antwoord. Geen enkel bericht droeg een wachtwoord en geen was versleuteld: Modbus vertrouwt iedereen die het kan bereiken, dus het netwerk eromheen moet de bescherming leveren. Druk op OPNIEUW om het nog eens te bekijken.","4 requests, 4 answers":"4 verzoeken, 4 antwoorden",Biggest:"Grootste","17 bytes (the read answer)":"17 bytes (het leesantwoord)","Protect with":"Beschermen met","Separate networks":"Gescheiden netwerken","Port 502":"Poort 502","A TCP connection to the PLC":"Een TCP-verbinding naar de PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Een PLC (programmable logic controller) bestuurt een klein pompstation: hij leest de sensoren en schakelt de pompen. De laptop van een technicus op het installatienetwerk praat er Modbus/TCP mee, dus hij opent een TCP-verbinding naar poort 502. In Modbus-termen is de laptop de client en de PLC de server.",Roles:"Rollen","Client asks, server answers":"Client vraagt, server antwoordt","Read Registers":"Registers lezen","Function 3: four numbers":"Functie 3: vier getallen","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"De laptop vraagt om 4 holding registers vanaf adres 0, met functiecode 3. De PLC antwoordt met 8 bytes: vier 16-bits getallen. Wat ze betekenen (het tankniveau in centimeters, de temperatuur in tienden van een graad) staat alleen in de documentatie van de PLC; het bericht draagt geen namen en geen eenheden. Een HMI-scherm stuurt zulke leesverzoeken ongeveer elke seconde.",Function:"Functie","4 registers from 0":"4 registers vanaf 0","function 3":"functie 3","registers 0–3":"registers 0–3",VALUES:"WAARDEN","Write a Setpoint":"Een setpoint schrijven","Function 6: one register":"Functie 6: één register","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"De technicus verhoogt het niveausetpoint van de tank van 4.50 m naar 5.00 m: functie 6, write single register, register 3, waarde 500. De PLC antwoordt door het verzoek te herhalen, wat betekent: gedaan. Vanaf nu houdt zijn programma de tank voller.","Register 3":"Register 3","The request, repeated":"Het verzoek, herhaald",WRITE:"SCHRIJVEN","register 3 = 500":"register 3 = 500","Start a Pump":"Een pomp starten","Function 5: a coil":"Functie 5: een coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Coils zijn losse aan/uit-uitgangen. Functie 5 schrijft er een: coil 0, pomp 2, waarde 0xFF00, wat aan betekent. De PLC zet de pomp aan en herhaalt het verzoek. In een echte installatie beslist meestal het eigen programma van de PLC dit, met veiligheidsvergrendelingen.","Coil 0":"Coil 0","Pump 2: on":"Pomp 2: aan","0xFF00 (off: 0x0000)":"0xFF00 (uit: 0x0000)","COIL ON":"COIL AAN","coil 0: pump 2":"coil 0: pomp 2","pump 2 on":"pomp 2 aan","PUMP 2 RUNNING":"POMP 2 DRAAIT","An Exception":"Een uitzondering","No such register":"Geen register daar","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Een verzoek om registers die niet bestaan, hier 100 en 101, krijgt een uitzondering: de functiecode met het hoogste bit gezet (3 + 128 = 131) en uitzonderingscode 2, ongeldig data-adres. Andere codes zeggen dat de functie niet wordt ondersteund of dat het apparaat bezet is.",Exception:"Uitzondering",Means:"Betekent","No register there":"Daar is geen register","registers 100–101":"registers 100–101",EXCEPTION:"UITZONDERING","code 2: no such register":"code 2: register bestaat niet","No Security":"Geen beveiliging","Anyone who can reach it":"Iedereen die het kan bereiken","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Niets in deze berichten zegt wie ze stuurde: Modbus, uit 1979, heeft geen aanmelding en geen versleuteling, dus elk apparaat dat poort 502 kan bereiken, kan de waarden lezen en de pomp starten. Installaties beschermen het met gescheiden netwerken, firewalls tussen kantoor en installatie, lijsten van wie met elke PLC mag praten, en monitoring. Modbus/TCP Security verpakt dezelfde berichten in TLS, op poort 802.","Separate networks, TLS":"Gescheiden netwerken, TLS","NO LOGIN, NO ENCRYPTION":"GEEN AANMELDING, GEEN VERSLEUTELING","Seen on the plant network":"Gezien op het installatienetwerk","Picked by the client; the answer carries the same number.":"Gekozen door de client; het antwoord draagt hetzelfde nummer.","Protocol ID":"Protocol-ID","The unit ID and everything after it.":"De unit-ID en alles daarna.","Unit ID":"Unit-ID","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Welk apparaat. Het doet ertoe als een gateway verzoeken doorgeeft aan apparaten op een seriële lijn.","Function code":"Functiecode","Starting address":"Startadres","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus telt vanaf 0, al nummeren handleidingen hetzelfde register vaak vanaf 40001.",Quantity:"Aantal","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, antwoord","The same number as the request.":"Hetzelfde nummer als het verzoek.","Byte count":"Aantal bytes","Register 0":"Register 0","412 (tank level, 4.12 m)":"412 (tankniveau, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Gewone 16-bits getallen. Wat elk betekent, staat in de documentatie van de PLC, niet in het bericht.","Register 1":"Register 1","183 (temperature, 18.3 °C)":"183 (temperatuur, 18.3 °C)","Register 2":"Register 2","1450 (pump speed, 1,450 rpm)":"1450 (pomptoerental, 1,450 tpm)","450 (level setpoint, 4.50 m)":"450 (niveausetpoint, 4.50 m)","Register address":"Registeradres","3 (level setpoint)":"3 (niveausetpoint)",Value:"Waarde","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, antwoord","The answer repeats the request: done.":"Het antwoord herhaalt het verzoek: gedaan.","Coil address":"Coiladres","0 (pump 2)":"0 (pomp 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Een coil is een losse aan/uit-uitgang. 0xFF00 zet hem aan.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, antwoord","Modbus/TCP · exception":"Modbus/TCP · uitzondering","131 (3 + 128: an exception)":"131 (3 + 128: een uitzondering)","The top bit set: the request failed.":"Het hoogste bit gezet: het verzoek is mislukt.","Exception code":"Uitzonderingscode","There is no register at that address.":"Op dat adres staat geen register.","Internet Routes":"Internetroutes",Routes:"Routes","The laptop’s packets":"De pakketten van de laptop","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Internet is een netwerk van netwerken: tienduizenden, beheerd door internetproviders, clouds, universiteiten en bedrijven, elk met een eigen AS-nummer. BGP is hoe hun grensrouters elkaar vertellen welke adressen ze kunnen bereiken. Elke router geeft door wat hij leert met zijn eigen nummer erbij, zodat elk netwerk zijn eigen kaart bouwt van de paden naar elk adres op internet.",Between:"Tussen","Networks (ASes)":"Netwerken (AS’en)",Table:"Tabel","About a million IPv4 routes":"Zo’n miljoen IPv4-routes","Path choice":"Padkeuze","Policy, then shortest":"Beleid, dan de kortste","Route learned":"Route geleerd","Announced, passed on, used":"Aangekondigd, doorgegeven, gebruikt","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Het hostingnetwerk kondigde zijn adressen aan, het transitnetwerk gaf ze door met zijn eigen nummer erbij, en de router van de provider gebruikte dat pad voor de pakketten van de laptop. Toen de route werd ingetrokken, verspreidde het nieuws zich op dezelfde manier. Er is geen centrale kaart: elk netwerk bouwt zijn eigen kaart uit wat zijn buren zeggen. Druk op OPNIEUW om het nog eens te bekijken.",Map:"Kaart","Each network makes its own":"Elk netwerk maakt zijn eigen","RPKI and filters":"RPKI en filters","Many Networks":"Veel netwerken","Each with its own number":"Elk met een eigen nummer","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Internet bestaat uit meer dan 75,000 aparte netwerken, autonome systemen (AS’en) genoemd: internetproviders, clouds, universiteiten, grote bedrijven, elk met een nummer. Hier zijn er drie: de provider van de laptop (AS 64500), een transitnetwerk dat verkeer van anderen vervoert (AS 64510), en het hostingnetwerk van www.example.com (AS 64511). BGP is hoe hun routers elkaar vertellen waar elk adres te bereiken is.",Networks:"Netwerken","More than 75,000 ASes":"Meer dan 75,000 AS’en",Here:"Hier","3 ASes, a router each":"3 AS’en, elk een router",Numbers:"Nummers","TCP to port 179":"TCP naar poort 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"BGP-routers vinden elkaar niet zelf: technici aan beide kanten stellen ze in als buren. De router van de provider opent een TCP-verbinding naar de transitrouter op poort 179. Ze zijn rechtstreeks verbonden, dus hun pakketten gaan weg met een TTL van 1: ze kunnen zelfs geen router verder, dus de sessie werkt alleen tussen directe buren.",Neighbours:"Buren","Set up by hand":"Met de hand ingesteld","1: the next router only":"1: alleen de volgende router","OPEN, then KEEPALIVE":"OPEN, dan KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Elke router stuurt een OPEN: zijn AS-nummer, een hold time van 180 seconden, zijn router-ID en wat hij ondersteunt, zoals AS-nummers van 4 bytes. Elk antwoordt met een KEEPALIVE, en de sessie staat. Vanaf nu gaat er elke 60 seconden een KEEPALIVE als er niets anders te sturen is; na 180 stille seconden zou de sessie worden verbroken.","AS, hold time, ID":"AS, hold time, ID","KEEPALIVE: established":"KEEPALIVE: tot stand gebracht","Hold time":"Hold time","hold 180 s":"hold 180 s","SESSION ESTABLISHED":"SESSIE TOT STAND GEBRACHT","Announce a Route":"Een route aankondigen","The hosting network: “I have these”":"Het hostingnetwerk: ‘ik heb deze’","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"De router van het hostingnetwerk kondigt 203.0.113.0/24 aan, de 256 adressen waaronder www.example.com, bij het transitnetwerk, dat hij betaalt om zijn verkeer te vervoeren. De UPDATE zegt hoe je er komt: AS_PATH 64511, tot nu toe alleen zijn eigen netwerk, en NEXT_HOP, zijn eigen adres op de verbinding tussen hen.","path 64511":"pad 64511","Passed On":"Doorgegeven","Each network adds its number":"Elk netwerk voegt zijn nummer toe","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"De transitrouter accepteert de route en geeft hem door aan zijn andere buren, waaronder de provider, met zijn eigen nummer vooraan erbij: AS_PATH 64510 64511, en zichzelf als volgende hop. De router van de provider kan hetzelfde prefix van meerdere buren horen. Hij kiest er eerst een op eigen beleid (routes via betalende klanten vóór andere, bijvoorbeeld), dan op het kortste AS-pad.","Best path":"Beste pad","path 64510 64511":"pad 64510 64511","ROUTE TO 203.0.113.0/24":"ROUTE NAAR 203.0.113.0/24","Follow the Route":"De route volgen","Packets go where BGP said":"Pakketten gaan waar BGP zei","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Als de laptop verbindt met www.example.com (het adres zoals gewoonlijk via DNS gevonden), komen zijn pakketten bij de provider, wiens router nu alles voor 203.0.113.0/24 naar de transitrouter stuurt, en de transitrouter stuurt het door naar het hostingnetwerk. Het antwoord komt terug via welke route het hostingnetwerk ook koos richting de provider van de laptop: op internet is de weg terug vaak anders dan de weg heen.","Way back":"Weg terug","Chosen separately":"Apart gekozen","the way back":"de weg terug",Withdrawn:"Ingetrokken","Routes can be taken back":"Routes kunnen worden teruggenomen","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Later neemt het hostingnetwerk het prefix terug, zoals het zou doen als een verbinding uitviel: een UPDATE die het onder ingetrokken routes noemt. De transitrouter geeft het door, en binnen seconden tot minuten vergeten netwerken overal het pad. Een sessie die langer dan haar hold time stil blijft, verliest al haar routes in één keer. In 2021 trok Facebook de routes naar zijn eigen DNS-servers in en verdween zes uur van internet.","Spreads in":"Verspreidt zich in","Seconds to minutes":"Seconden tot minuten","Session lost":"Sessie verloren","All its routes go":"Al haar routes verdwijnen",WITHDRAW:"INTREKKEN","Trust Problems":"Vertrouwensproblemen","BGP believes its neighbours":"BGP gelooft zijn buren","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Een router accepteert wat zijn buren aankondigen. Een netwerk dat adressen aankondigt die niet van hem zijn, per ongeluk of expres, trekt hun verkeer naar zich toe: in 2008 haalde een Pakistaanse provider YouTube zo wereldwijd offline. Met RPKI ondertekent de houder van een prefix welk AS het mag aankondigen, en routers die dat controleren gooien elk ander weg. Filters op wat elke buur mag aankondigen doen de rest.",Risk:"Risico","Hijacks and leaks":"Kapingen en lekken","Signed: who may announce":"Ondertekend: wie mag aankondigen",Also:"Ook","Filters per neighbour":"Filters per buur","CHECK WHO MAY ANNOUNCE":"CONTROLEER WIE MAG AANKONDIGEN","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: ingetrokken 203.0.113.0/24",Marker:"Marker","16 bytes of 0xFF":"16 bytes 0xFF","All ones: where a message starts.":"Allemaal enen: waar een bericht begint.","The first message on a session: who this router is and what it supports.":"Het eerste bericht in een sessie: wie deze router is en wat hij ondersteunt.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Het netwerk van deze router. (Een AS-nummer van 4 bytes staat in de capability hieronder, met hier 23456.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Komt er zo lang helemaal niets binnen, dan wordt de sessie verbroken. Beide kanten gebruiken het laagste aanbod.","BGP identifier":"BGP-identificatie","The router’s ID, usually one of its addresses.":"Het ID van de router, meestal een van zijn adressen.","Optional parameters":"Optionele parameters","parameter 2, 14 bytes":"parameter 2, 14 bytes","What this router can do beyond the basics.":"Wat deze router kan naast de basis.",Multiprotocol:"Multiprotocol","Which kinds of routes it will exchange on this session.":"Welke soorten routes hij in deze sessie uitwisselt.","Route refresh":"Route refresh","It can ask the other side to send all its routes again.":"Hij kan de andere kant vragen al zijn routes opnieuw te sturen.","4-byte AS numbers":"AS-nummers van 4 bytes","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"AS-nummers van 2 bytes raakten op, dus nieuwere zijn 4 bytes lang.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Alleen de header: ‘nog hier’. Verstuurd als er niets anders te zeggen is, elk derde van de hold time.","Routes: paths to new addresses, and ones taken back.":"Routes: paden naar nieuwe adressen, en teruggenomen paden.","Withdrawn routes":"Ingetrokken routes","Path attributes":"Padattributen","0 (IGP: from inside the network that announced it)":"0 (IGP: van binnen het netwerk dat hem aankondigde)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Elk netwerk waar de route doorheen ging, het laatste eerst. Als al het andere gelijk is, wint het kortere pad; een router die zijn eigen nummer hier vindt, gooit de route weg, zodat routes niet kunnen rondlopen.","Send packets for these addresses to this router.":"Stuur pakketten voor deze adressen naar deze router.",Reachable:"Bereikbaar","The addresses this route leads to: a prefix, here 256 addresses.":"De adressen waar deze route naartoe leidt: een prefix, hier 256 adressen.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (intrekking)","These addresses can no longer be reached through this router.":"Deze adressen zijn niet meer te bereiken via deze router.","A Video Call":"Een videogesprek",Signalling:"Signalering","STUN and ICE":"STUN en ICE",Media:"Media","STUN Server":"STUN-server","Sam’s Router":"Router van Sam","Sam’s Laptop":"Laptop van Sam","Web Real-Time Communication":"Web Real-Time Communication","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"Met WebRTC kunnen twee browsers elkaar bellen, met audio, video en data die rechtstreeks tussen hen gaan, niet via een server. Een server stelt ze alleen aan elkaar voor: ze wisselen beschrijvingen uit van wat ze kunnen sturen en waar ze te bereiken zijn (signalering), vinden met ICE en STUN een weg door beide thuisrouters, versleutelen met DTLS en sturen de media over UDP als SRTP.","Media over":"Media via","Always on":"Altijd aan","Works in":"Werkt in","Every major browser":"Elke grote browser","W3C; RFC 8825 and others":"W3C; RFC 8825 en andere","On the call":"In gesprek","Introduced by a server, then direct":"Voorgesteld door een server, dan rechtstreeks","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"De signaleringsserver gaf het aanbod en het antwoord door tussen de twee browsers, een STUN-server vertelde de laptop zijn publieke adres, en een ICE-controle vond een weg door beide thuisrouters. Na een DTLS-handshake gingen versleutelde audio en video rechtstreeks van de ene laptop naar de andere. Druk op OPNIEUW om het nog eens te bekijken.","Via call.example.com":"Via call.example.com","Media path":"Mediapad","Direct, through 2 NATs":"Rechtstreeks, door 2 NAT’s","DTLS, then SRTP":"DTLS, dan SRTP","If blocked":"Als het geblokkeerd is","A TURN relay":"Een TURN-relay","Join the Call":"Deelnemen aan het gesprek","Through a signalling server":"Via een signaleringsserver","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"De laptop opent een belpagina op call.example.com, en de pagina houdt een WebSocket naar de server open, binnen TLS. Hij gaat ruimte 42 in, waar Sam al wacht. De server zal berichten tussen de twee browsers doorgeven. WebRTC zegt niet hoe: elke app doet deze signalering op zijn eigen manier.","The app’s own server":"De eigen server van de app","A WebSocket in TLS":"Een WebSocket in TLS",Room:"Ruimte","42, with Sam":"42, met Sam",JOIN:"DEELNEMEN","room 42":"ruimte 42","SAM IS HERE":"SAM IS ER","peer: Sam":"deelnemer: Sam","Public Address?":"Publiek adres?","Ask a STUN server":"Vraag een STUN-server","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Achter zijn thuisrouter kent de laptop alleen zijn privéadres, 192.168.1.10, dat niemand op internet kan bereiken. Dus vraagt hij een STUN-server die in de instellingen van de belpagina staat, met één klein UDP-verzoek. Het antwoord zegt waar het verzoek vandaan leek te komen, 198.51.100.7 poort 61022: het publieke adres van de router en de poort die zijn NAT voor dit gesprek opende.",Public:"Publiek","what is my address?":"wat is mijn adres?","YOUR ADDRESS":"JOUW ADRES","The Offer":"Het aanbod","An SDP description, via the server":"Een SDP-beschrijving, via de server","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"De browser schrijft een aanbod in SDP: de media die hij wil sturen (Opus-audio; video in VP8, H.264 en andere), de vingerafdruk van zijn DTLS-certificaat, zijn ICE-gebruikersnaam en -wachtwoord, en zijn kandidaten, de adressen waarop hij misschien te bereiken is. Zijn privéadres zit verborgen achter een willekeurige .local-naam. De signaleringsserver geeft het aanbod door aan Sam.","SDP, in a JSON message":"SDP, in een JSON-bericht",Candidates:"Kandidaten",".local name, 198.51.100.7":".local-naam, 198.51.100.7","About 4.7 KB":"Ongeveer 4.7 KB","SDP: audio, video":"SDP: audio, video",candidates:"kandidaten","to Sam":"naar Sam","Sam’s browser replies":"De browser van Sam antwoordt","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam neemt het gesprek aan. De browser van Sam antwoordt met een eigen SDP: de codecs die hij uit het aanbod koos, de vingerafdruk van zijn certificaat, zijn ICE-gebruikersnaam en -wachtwoord, en zijn kandidaten, waaronder zijn publieke adres, 198.51.100.200 poort 49170, dat hij op dezelfde manier van een STUN-server leerde. Hij zegt ook dat hij de versleutelingshandshake zal starten. Nu weet elke browser waar de ander misschien te bereiken is.",Codecs:"Codecs","Sam’s address":"Adres van Sam","Starts DTLS":"Start DTLS","Sam’s browser":"De browser van Sam","from Sam":"van Sam","Punch Through":"Erdoorheen prikken","Checks straight to each other":"Controles rechtstreeks naar elkaar","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Nu proberen de browsers adresparen met STUN-controles die ze rechtstreeks naar elkaar sturen (ICE). Elke controle opent ook een weg terug door de eigen router van de afzender, dus zodra beide kanten er een hebben gestuurd, komen controles door beide NAT’s. Deze wordt beantwoord: het directe pad werkt. De laptop herhaalt de controle daarna met USE-CANDIDATE en kiest dit paar voor het gesprek.",Checks:"Controles","STUN, peer to peer":"STUN, peer-to-peer","The ICE password":"Het ICE-wachtwoord","A direct path":"Een direct pad",CHECK:"CONTROLE","IT WORKS":"HET WERKT","direct path":"direct pad","THROUGH BOTH ROUTERS":"DOOR BEIDE ROUTERS","DTLS Handshake":"DTLS-handshake","Keys for the media":"Sleutels voor de media","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Over hetzelfde pad voeren de browsers een DTLS-handshake uit: TLS voor UDP. Hun certificaten zijn zelfondertekend, dus elk controleert dat van de ander aan de hand van de vingerafdruk in de SDP, die binnen TLS via de signaleringsserver kwam. De handshake spreekt ook de sleutels af voor SRTP, dat de audio en video versleutelt. WebRTC stuurt nooit onversleutelde media.","1.2, TLS over UDP":"1.2, TLS over UDP","Checked by fingerprint":"Gecontroleerd via vingerafdruk",Gives:"Levert","The SRTP keys":"De SRTP-sleutels",certificate:"certificaat","Media Flows":"Media stromen","Audio and video, direct":"Audio en video, rechtstreeks","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"Audio gaat elke 20 ms in een SRTP-pakket, en video als frames verdeeld over meerdere pakketten. Elk pakket heeft een leesbare RTP-header (volgnummer, tijdstempel, stream-ID) en versleutelde media. Niets ervan gaat via call.example.com. Beide browsers letten op vertraging en verlies en passen de videokwaliteit daarop aan, en een datakanaal voor chat of bestanden kan hetzelfde pad delen.","Opus, a packet per 20 ms":"Opus, een pakket per 20 ms",Video:"Video","VP8, adapts to the network":"VP8, past zich aan het netwerk aan","None of it":"Niets ervan",AUDIO:"AUDIO","Opus, every 20 ms":"Opus, elke 20 ms",VIDEO:"VIDEO","VP8, a frame in 3 packets":"VP8, een frame in 3 pakketten","Peer to Peer":"Peer-to-peer","And when it can’t be":"En als dat niet kan","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"De server hielp de twee browsers elkaar te vinden en stapte toen opzij: het gesprek gaat rechtstreeks tussen de twee huizen. Als een netwerk geen directe pakketten doorlaat (sommige bedrijfsfirewalls, sommige mobiele netwerken), valt ICE terug op een TURN-server die de versleutelde media doorgeeft zonder ze te kunnen lezen. Groepsgesprekken sturen media meestal ook via een server, een SFU.","Laptop to laptop":"Laptop naar laptop",Fallback:"Terugval","TURN relay (encrypted)":"TURN-relay (versleuteld)","Group calls":"Groepsgesprekken","Usually via an SFU":"Meestal via een SFU","NO SERVER IN THE MIDDLE":"GEEN SERVER ERTUSSEN","A WebSocket text message":"Een WebSocket-tekstbericht","The attributes; the 20-byte header isn’t counted.":"De attributen; de header van 20 bytes telt niet mee.","Always this value: tells STUN apart from the other traffic on the same port.":"Altijd deze waarde: onderscheidt STUN van het andere verkeer op dezelfde poort.","Random; the response carries the same ID.":"Willekeurig; het antwoord draagt hetzelfde ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Waar het verzoek vandaan kwam, zoals de server het zag: het publieke adres van de thuisrouter, en de poort die zijn NAT voor dit gesprek koos.","Their internet provider’s router, the next hop.":"De router van hun internetprovider, de volgende hop.","Their router’s internet-facing port.":"De poort van hun router aan de internetkant.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"De ICE-gebruikersnamen uit het aanbod en het antwoord, die van de andere kant eerst: bewijst dat de controle bij dit gesprek hoort.","The priority a new candidate found by this check would get.":"De prioriteit die een nieuwe kandidaat, gevonden door deze controle, zou krijgen.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Deze kant, de beller, maakt de definitieve padkeuze. Het willekeurige getal beslist bij gelijkspel.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 van het bericht, berekend met een ICE-wachtwoord dat via de signaleringsserver is uitgewisseld, zodat een vreemde geen controle of antwoord kan vervalsen.","A CRC-32 of the message: marks it clearly as STUN.":"Een CRC-32 van het bericht: markeert het duidelijk als STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Waar de controle vandaan kwam, zoals de andere laptop het zag: het publieke adres en de poort van de thuisrouter.",Epoch:"Epoch","Counts this side’s records, so repeats and stale ones can be spotted.":"Telt de records van deze kant, zodat herhalingen en verouderde records opvallen.","Message length":"Berichtlengte","Message sequence":"Berichtvolgorde","Handshake messages are numbered, so they can be put back in order.":"Handshakeberichten zijn genummerd, zodat ze weer op volgorde gezet kunnen worden.",Fragment:"Fragment","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Cipher suites: ECDHE-ECDSA met AES-GCM, en andere","use_srtp: the SRTP protection it supports":"use_srtp: de SRTP-bescherming die hij ondersteunt","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Gekozen: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Een zelfondertekend certificaat dat de browser maakte; de vingerafdruk stond in het aanbod","Its half of an X25519 key exchange, signed":"Zijn helft van een X25519-sleuteluitwisseling, ondertekend","Asks Sam’s browser for its certificate too":"Vraagt de browser van Sam ook om zijn certificaat","Sam’s self-signed certificate; its fingerprint was in the answer":"Het zelfondertekende certificaat van Sam; de vingerafdruk stond in het antwoord","Its half of the X25519 key exchange":"Zijn helft van de X25519-sleuteluitwisseling","A signature that proves it holds the certificate’s key":"Een handtekening die bewijst dat hij de sleutel van het certificaat heeft","From the next record on, this side encrypts.":"Vanaf het volgende record versleutelt deze kant.","Finished (encrypted)":"Finished (versleuteld)","Epoch 1: protected with the keys just agreed.":"Epoch 1: beschermd met de net afgesproken sleutels.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Een nonce van 8 bytes, het Finished-bericht en een tag van 16 bytes (AES-128-GCM).","SRTP · audio":"SRTP · audio","2, no padding, extension, no CSRCs":"2, geen opvulling, extensie, geen CSRC’s","X set: a header extension follows the fixed header.":"X gezet: na de vaste header volgt een headerextensie.","One more for each packet, so a lost or late one shows.":"Eén hoger bij elk pakket, zodat een verloren of laat pakket opvalt.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Audioklok, 48,000 tikken per seconde: +960 per 20 ms.","Which stream this is; announced in the SDP.":"Welke stream dit is; aangekondigd in de SDP.","Header extension":"Headerextensie","0xbede, 2 words":"0xbede, 2 woorden","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Elementen van één byte: een ID (uit de a=extmap-regels van de SDP) en een lengte.","Audio level":"Audioniveau","How loud this packet is, so a group call can show who is talking without decrypting.":"Hoe luid dit pakket is, zodat een groepsgesprek kan tonen wie praat zonder te ontsleutelen.","Transport sequence":"Transportvolgnummer","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Nummert elk pakket van het gesprek; de ontvanger meldt wat wanneer aankwam, voor congestiebeheer.","Encrypted media":"Versleutelde media","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms Opus-audio, versleuteld met sleutels uit de DTLS-handshake (AES-128-GCM).","Authentication tag":"Authenticatietag","Proves the packet came from the other side unchanged; the header is covered too.":"Bewijst dat het pakket ongewijzigd van de andere kant kwam; ook de header valt eronder.","SRTP · video":"SRTP · video","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Videoklok, 90,000 tikken per seconde: +3,000 per frame bij 30 frames per seconde.","Absolute send time":"Absolute verzendtijd","When the packet was sent, so the receiver can tell when the network is filling up.":"Wanneer het pakket werd verstuurd, zodat de ontvanger merkt wanneer het netwerk volloopt.","1 byte":"1 byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Een deel van een VP8-videoframe, versleuteld met sleutels uit de DTLS-handshake (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker gezet: het laatste pakket van een videoframe.","8 ports":"8 poorten","Frames and switches":"Frames en switches","Broadband logins":"Breedband-inlog","The laptop sent it with 128; the router took 1 when it passed it on.":"De laptop stuurde het met 128; de router haalde er 1 af bij het doorsturen.","Frames & Switches":"Frames en switches","To the NAS":"Naar de NAS","To the internet":"Naar internet","Ethernet and Switches":"Ethernet en switches","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet draagt bijna elk bekabeld netwerk, en wifi-access points geven hun verkeer eraan door. Elke netwerkkaart heeft een 48-bits MAC-adres. Een frame zegt voor welke kaart het is en welke kaart het stuurde, en een switch bezorgt het: uit de frames die hij ziet leert hij achter welke poort elk adres zit, en hij stuurt elk frame alleen naar waar het heen moet.","48-bit MAC":"48-bits MAC","14 bytes, plus a 4-byte FCS":"14 bytes, plus een FCS van 4 bytes","Frame size":"Framegrootte","64 to 1,518 bytes":"64 tot 1.518 bytes",Speeds:"Snelheden",Switched:"Geschakeld","Learned, flooded, forwarded":"Geleerd, geflood, doorgestuurd","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"De switch leerde waar de laptop en de NAS zaten uit de frames die ze stuurden, floodde alleen de broadcast en stuurde elk ander frame alleen via de poort die nodig was. MAC-adressen brachten elk frame over één verbinding; bij de router ging het pakket in een nieuw frame. Druk op OPNIEUW om het nog eens te bekijken.",Learned:"Geleerd","2 addresses, 2 ports":"2 adressen, 2 poorten",Flooded:"Geflood","Only the broadcast":"Alleen de broadcast",Frame:"Frame","14-byte header, 4-byte FCS":"Header van 14 bytes, FCS van 4","Forgets after":"Vergeet na","5 minutes unused":"5 minuten ongebruikt","Who Has the NAS?":"Wie heeft de NAS?","A broadcast asks for a MAC address":"Een broadcast vraagt om een MAC-adres","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"De laptop wil de NAS op 192.168.1.20 bereiken. Op een lokaal netwerk worden frames bezorgd op MAC-adres, en de laptop kent dat van de NAS nog niet. Dus stuurt hij een ARP-verzoek naar ff:ff:ff:ff:ff:ff, het broadcastadres, poort 1 van de switch in.","Looking for":"Zoekt","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (iedereen)",Into:"Naar binnen via","Switch port 1":"Switchpoort 1","who has 192.168.1.20?":"wie heeft 192.168.1.20?","Learn, Then Flood":"Leren, dan flooden","The switch notes where the laptop is":"De switch noteert waar de laptop zit","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Een switch leest het bronadres van elk frame en noteert het in zijn MAC-tabel: 00:00:5e:00:53:10 zit op poort 1. Een broadcast is voor iedereen, dus stuurt hij een kopie via elke andere poort: naar de NAS op poort 2 en de router op poort 8. Frames voor onbekende adressen worden ook geflood.","…:53:10 is on port 1":"…:53:10 zit op poort 1",Copies:"Kopieën","Out of every other port":"Via elke andere poort","Unknown address":"Onbekend adres","Flooded the same way":"Net zo geflood","…:53:10 IS ON PORT 1":"…:53:10 ZIT OP POORT 1","copies out of ports 2 and 8":"kopieën via poort 2 en 8","Only the NAS Answers":"Alleen de NAS antwoordt","The reply goes to one port":"Het antwoord gaat naar één poort","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Elk apparaat leest het verzoek, maar alleen de NAS heeft 192.168.1.20, dus alleen die antwoordt, rechtstreeks naar het MAC van de laptop; de router negeert het. De switch leert dat 00:00:5e:00:53:20 op poort 2 zit. Waar de laptop zit, weet hij al, dus het antwoord gaat alleen via poort 1 naar buiten.","To the laptop only":"Alleen naar de laptop","…:53:20 is on port 2":"…:53:20 zit op poort 2","Out of":"Naar buiten via","Port 1":"Poort 1","…:53:20 IS ON PORT 2":"…:53:20 ZIT OP POORT 2","port 1 only":"alleen poort 1","Port to Port":"Poort naar poort","Frames go only where they must":"Frames gaan alleen waar ze moeten","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"De laptop maakt verbinding met de NAS. Elk frame begint met het MAC van de NAS, dan het eigen MAC, dan een type: 0x0800, een IPv4-pakket. Na het pakket voegt de kaart een controlesom van 4 bytes toe. De switch zoekt de bestemming op en stuurt elk frame alleen via poort 2. De router ziet ze nooit.","To, from, type: 14 bytes":"Aan, van, type: 14 bytes","4 bytes, added by the card":"4 bytes, door de kaart","Router sees":"Router ziet",Nothing:"Niets","type 0x0800 (IPv4)":"type 0x0800 (IPv4)","out of port 2 only":"alleen via poort 2","Off the Network":"Van het netwerk af","A frame for the router":"Een frame voor de router","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Daarna opent de laptop een website op 203.0.113.10. Dat adres zit niet op het lokale netwerk, dus het frame gaat naar de router: het MAC van de router, bekend van een eerdere ARP, is de bestemming, terwijl het pakket erin nog steeds 203.0.113.10 noemt. De switch stuurt het via poort 8.","Frame to":"Frame aan","The router’s MAC":"Het MAC van de router","Packet to":"Pakket aan","Port 8":"Poort 8","IP packet to 203.0.113.10":"IP-pakket aan 203.0.113.10","out of port 8":"via poort 8","A New Frame":"Een nieuw frame","Every hop rewraps the packet":"Elke hop verpakt het pakket opnieuw","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"De router haalt het pakket uit het frame, verlaagt de TTL en zet zijn publieke adres erin (NAT). Dan stopt hij het pakket in een nieuw frame voor de volgende verbinding: zijn MAC aan de internetkant als bron, de router van de provider als bestemming. MAC-adressen gaan nooit over meer dan één verbinding.","The router’s internet port":"De internetpoort van de router","The provider’s router":"De router van de provider","Still 203.0.113.10":"Nog steeds 203.0.113.10","NEW FRAME":"NIEUW FRAME","from the router’s internet port":"van de internetpoort van de router","IP still to 203.0.113.10":"IP nog steeds aan 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"In, poort 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Uit, poort 2 (geflood) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Uit, poort 8 (geflood) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"In, poort 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Alleen uit via poort 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"In, poort 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Uit, poort 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"In, poort 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Uit, poort 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"In, poort 1 · 52344 → 443 [SYN] (frame aan de router)","Out port 8 · 52344 → 443 [SYN]":"Uit, poort 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (nieuw frame, na NAT)","Seen going into the switch, port 1":"Gezien bij binnenkomst in de switch, poort 1","Seen leaving the switch, port 2":"Gezien bij het verlaten van de switch, poort 2","Seen leaving the switch, port 8":"Gezien bij het verlaten van de switch, poort 8","Seen going into the switch, port 2":"Gezien bij binnenkomst in de switch, poort 2","Seen leaving the switch, port 1":"Gezien bij het verlaten van de switch, poort 1","Broadband Logins":"Breedband-inlog",Discovery:"Discovery","PPP setup":"PPP opzetten","Home Router":"Thuisrouter","Access Server":"Toegangsserver","Point-to-Point Protocol over Ethernet":"Point-to-Point Protocol over Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Veel DSL- en glasvezelproviders laten de thuisrouter eerst inloggen voordat hij online mag. PPPoE regelt dat: de router vindt de toegangsserver van de provider en opent er een sessie mee, en draait daarin PPP: hij spreekt de instellingen van de verbinding af, logt in met de gebruikersnaam en het wachtwoord van de provider en krijgt zijn publieke IP-adres. Daarna draagt elk pakket een PPPoE-header van 8 bytes.","CHAP or PAP":"CHAP of PAP","From IPCP":"Via IPCP","8 bytes (MTU 1,492)":"8 bytes (MTU 1.492)","Logged in":"Ingelogd","Found, agreed, checked, addressed":"Gevonden, afgesproken, gecontroleerd, geadresseerd","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"De router vond de toegangsserver van de provider, kreeg een sessie, sprak de instellingen van de verbinding af, bewees zijn wachtwoord zonder het te sturen en kreeg zijn publieke adres. Elk pakket reist nu in die sessie, tot een PADT haar beëindigt. Druk op OPNIEUW om het nog eens te bekijken.","17 to get online":"17 tot online","Public IP":"Publiek IP","8 bytes per packet":"8 bytes per pakket","Anyone There?":"Iemand daar?","The router looks for an access server":"De router zoekt een toegangsserver","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"De thuisrouter zit aan de glasvezel- of DSL-lijn van de provider. Voordat hij kan inloggen, moet hij de toegangsserver van de provider vinden, dus stuurt hij een PADI als broadcast: ‘PPPoE Active Discovery Initiation’. Een toegangsserver antwoordt met een PADO, een aanbod met zijn naam: bng-1.example.net.","PADI, to everyone":"PADI, aan iedereen","PADO, from the server":"PADO, van de server","Ethernet type":"Ethernettype","0x8863 (discovery)":"0x8863 (discovery)","is there an access server?":"is er een toegangsserver?","and a cookie":"en een cookie","Pick a Server":"Een server kiezen","A session number for the line":"Een sessienummer voor de lijn","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Als meerdere servers antwoordden, kiest de router er één en vraagt die rechtstreeks met een PADR, met de cookie die hij kreeg. De server antwoordt met een PADS met een sessie-ID, 0x2f1c. Vanaf nu draagt elk frame tussen die twee dat nummer.",Confirmed:"Bevestigd","this server, please":"deze server, graag","with its cookie":"met zijn cookie","session ID 0x2f1c":"sessie-ID 0x2f1c","SESSION 0x2F1C":"SESSIE 0x2F1C","Link Settings":"Verbindingsinstellingen","LCP agrees on size and login":"LCP spreekt grootte en inloggen af","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Nu draait PPP in de sessie, te beginnen met LCP. Elke kant vraagt zijn instellingen: pakketten van hooguit 1.492 bytes, omdat de 8 bytes van PPPoE in de 1.500 van Ethernet moeten passen, en een willekeurig magic number om lussen te herkennen. De server vraagt ook om een CHAP-login. Beide stemmen in.","Largest packet":"Grootste pakket","1,492 bytes (MRU)":"1.492 bytes (MRU)","CHAP with MD5":"CHAP met MD5","0x8864 (session)":"0x8864 (sessie)","LCP REQUEST":"LCP-VERZOEK","magic number":"magic number","MRU 1492, log in with CHAP":"MRU 1492, inloggen met CHAP","LCP ACK":"LCP ACK","A password check without the password":"Een wachtwoordcheck zonder wachtwoord","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"De server stuurt een willekeurige challenge. De router antwoordt met zijn gebruikersnaam, alex@fibre.example, en een MD5-hash van de challenge en zijn wachtwoord, dus het wachtwoord zelf gaat nooit over de lijn. De server controleert het antwoord bij de RADIUS-server van de provider en zegt dan Success.",Username:"Gebruikersnaam","A hash, not the password":"Een hash, niet het wachtwoord","The provider’s RADIUS":"De RADIUS van de provider","MD5(id, password, challenge)":"MD5(id, wachtwoord, challenge)","CHECKED WITH RADIUS":"GECONTROLEERD VIA RADIUS","Get an Address":"Een adres krijgen","IPCP hands out the public IP":"IPCP deelt het publieke IP uit","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"De server vertelt de router eerst zijn eigen kant, 198.51.100.1. De router vraagt om een adres en DNS-servers en biedt 0.0.0.0 aan: ‘maakt niet uit’. De server weigert en stelt 198.51.100.7 en twee DNS-servers voor. De router vraagt opnieuw met die waarden, en de server stemt in.","Other end":"Andere kant","IPCP REQUEST":"IPCP-VERZOEK","my end: 198.51.100.1":"mijn kant: 198.51.100.1","address? 0.0.0.0":"adres? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"neem 198.51.100.7","198.51.100.7, please":"198.51.100.7, graag",agreed:"akkoord","Every packet in an 8-byte wrapper":"Elk pakket in een omhulsel van 8 bytes","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"De laptop opent een website. De router zet zijn publieke adres erin (NAT) en stuurt het pakket in de sessie: een PPPoE-header van 6 bytes, dan 2 bytes die ‘IPv4’ zeggen. Ook verlaagt hij de MSS die de laptop aanbood van 1460 naar 1452, zodat de antwoorden in 1.492 bytes passen.",Wrapper:"Omhulsel","6 + 2 bytes":"6 + 2 bytes","1460 → 1452 (clamped)":"1460 → 1452 (begrensd)","in session 0x2f1c":"in sessie 0x2f1c","MSS now 1452":"MSS nu 1452","Seen on the router’s line to the provider":"Gezien op de lijn van de router naar de provider","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 bytes","PADI, 2 tags":"PADI, 2 tags","Broadcast: everything on the line receives it.":"Broadcast: alles op de lijn ontvangt het.","0x8863 (PPPoE discovery)":"0x8863 (PPPoE-discovery)","Version, type":"Versie, type","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: is daar ergens een toegangsserver?","0 (none yet)":"0 (nog geen)","What follows this header.":"Wat er na deze header komt.","The service the router wants; empty means any.":"De dienst die de router wil; leeg betekent maakt niet uit.","Type, length":"Type, lengte","A value the router made up. Answers carry it back, so the router can match them to its request.":"Een waarde die de router zelf verzon. Antwoorden brengen haar terug, zodat de router ze aan zijn verzoek kan koppelen.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 bytes","PADO, 4 tags":"PADO, 4 tags","The access server’s port.":"De poort van de toegangsserver.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: een toegangsserver antwoordt.","The access server’s name.":"De naam van de toegangsserver.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Een waarde die de server herkent als de router er opnieuw om vraagt, zodat een stroom nepverzoeken hem niets kost.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 bytes","PADR, 3 tags":"PADR, 3 tags","The access server that answered.":"De toegangsserver die antwoordde.","Active Discovery Request: the router picks this server.":"Active Discovery Request: de router kiest deze server.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 bytes","PADS, 2 tags":"PADS, 2 tags","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: hier is de sessie-ID.","Given by the server in its PADS; every frame of the session carries it.":"Gegeven door de server in zijn PADS; elk frame van de sessie draagt het.","PPPoE · 6 bytes":"PPPoE · 6 bytes","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 bytes","0x8864 (PPPoE session)":"0x8864 (PPPoE-sessie)","0x00 (Session)":"0x00 (sessie)","Session data: one PPP packet.":"Sessiegegevens: één PPP-pakket.","Link Control Protocol: the link’s settings.":"Link Control Protocol: de instellingen van de verbinding.","The settings this side wants.":"De instellingen die deze kant wil.","The answer carries the same number.":"Het antwoord draagt hetzelfde nummer.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Het grootste pakket dat deze kant aanneemt: 1.500 bytes Ethernet min de 8 van PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Willekeurig. Komt het eigen nummer terug, dan loopt de lijn in een lus naar zichzelf.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 bytes","How the server wants the router to log in.":"Hoe de server wil dat de router inlogt.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 bytes","Every setting accepted, exactly as asked.":"Elke instelling aanvaard, precies zoals gevraagd.","The number of the request this answers.":"Het nummer van het verzoek waarop dit antwoordt.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 bytes","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 bytes","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: het inloggen.","A random value for the router to prove its password with.":"Een willekeurige waarde waarmee de router zijn wachtwoord bewijst.","The response must carry the same number.":"De response moet hetzelfde nummer dragen.","Value size":"Grootte van de waarde","Random, new for every login.":"Willekeurig, bij elke login nieuw.","The server’s name.":"De naam van de server.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 bytes","The proof, and who is logging in.":"Het bewijs, en wie er inlogt.","The number of the challenge this answers.":"Het nummer van de challenge waarop dit antwoordt.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 van de identifier, het wachtwoord en de challenge: het bewijst het wachtwoord zonder het te sturen.","The username the provider gave.":"De gebruikersnaam van de provider.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 bytes","The login worked.":"Het inloggen is gelukt.","Text for people to read; any words will do.":"Tekst voor mensen om te lezen; elke tekst mag.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 bytes","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: het IP-adres en de DNS-servers.","The address of the server’s end of the link.":"Het adres van de serverkant van de verbinding.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 bytes","Zero: “please give me an address”.":"Nul: ‘geef me alsjeblieft een adres’.","Zero: “which DNS server should I use?”":"Nul: ‘welke DNS-server moet ik gebruiken?’","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 bytes","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 bytes","Not these values: here are ones that would be accepted.":"Niet deze waarden: deze zouden wel aanvaard worden.","The address for the router.":"Het adres voor de router.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 bytes","PPP · 2 bytes":"PPP · 2 bytes","An IPv4 packet follows.":"Er volgt een IPv4-pakket.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Door de router verlaagd van 1460, zodat pakketten terug passen in de 1.492 bytes die PPPoE overlaat.","Internet phone calls":"Bellen via internet","IP camera streams":"Streams van IP-camera’s","Live streaming upload":"Livestreams uploaden","Multicast and TV channels":"Multicast en tv-zenders","IP Camera":"IP-camera","TV Box":"Tv-box",Camera:"Camera","Internet Phone Calls":"Bellen via internet","Voice (RTP)":"Spraak (RTP)","SIP Server":"SIP-server","Bob’s Router":"Router van Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP zet telefoongesprekken via internet op: bureautelefoons op kantoor, bel-apps en de providers erachter. Een telefoon meldt zich aan bij de SIP-server van zijn provider. Om iemand te bellen stuurt hij een INVITE; de andere telefoon gaat over en neemt op, en samen spreken ze af hoe de spraak verstuurd wordt, die daarna als RTP stroomt. De berichten zijn platte tekst, veel zoals HTTP.","UDP or TCP 5060":"UDP of TCP 5060","Call setup":"Gesprek opzetten",Voice:"Spraak","RTP, described by SDP":"RTP, beschreven met SDP","Codec here":"Codec hier","Call ended":"Opgehangen","Signed in, rang, talked, hung up":"Aangemeld, overgegaan, gepraat, opgehangen","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"De telefoon van Alice meldde zich aan met een wachtwoord dat hij nooit verstuurde, belde de telefoon van Bob via de SIP-server, hoorde hem overgaan en praatte via RTP tot Bob ophing met een BYE. SIP zette het gesprek alleen op en brak het af; de spraak reisde in eigen pakketten. Druk op OPNIEUW om het nog eens te bekijken.","50 packets a second each way":"50 pakketten per seconde per richting",Through:"Via","The provider’s server":"De server van de provider","No (SIPS and SRTP add it)":"Nee (SIPS en SRTP voegen het toe)","Sign In":"Aanmelden","The phone tells the server where it is":"De telefoon zegt de server waar hij is","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"De telefoon van Alice, een app op haar laptop, registreert zich bij de SIP-server van haar provider: alice@example.net is hier bereikbaar. De server antwoordt 401 met een challenge, dus vraagt de telefoon het opnieuw met een hash van de challenge en het wachtwoord. 200 OK: een uur geregistreerd.","Good for":"Geldig voor","3600 s, then again":"3600 s, dan opnieuw","is here":"is hier","with a challenge":"met een challenge","again, with a hash":"opnieuw, met een hash",registered:"geregistreerd","Call Bob":"Bob bellen","An INVITE, passed on by the server":"Een INVITE, doorgegeven door de server","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice belt bob@example.net. Haar INVITE bevat SDP: G.711-audio, te sturen naar haar telefoon. De server antwoordt 100 Trying, zoekt op waar de telefoon van Bob geregistreerd is en geeft de INVITE door, met een eigen Via en Record-Route en zijn eigen adres in de SDP: de spraak loopt via hem.","Offer (SDP)":"Aanbod (SDP)","G.711, port 49170":"G.711, poort 49170","Stops Alice resending":"Alice stuurt niet opnieuw","call bob@example.net":"bel bob@example.net","SDP: G.711 audio":"SDP: G.711-audio","passed on to Bob":"doorgegeven aan Bob","voice via the server":"spraak via de server",Ringing:"Gaat over","The answer retraces the route":"Het antwoord volgt de route terug","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"De telefoon van Bob gaat over en meldt dat: 180 Ringing. Antwoorden volgen de Via-headers terug langs de weg van het verzoek, dus het gaat naar de server, die zijn eigen Via weghaalt en het doorgeeft aan Alice. Haar telefoon laat de kiestoon horen.","Route back":"Route terug","The Via headers, in reverse":"De Via-headers, omgekeerd","Alice hears":"Alice hoort","The ringing tone":"De beltoon","Bob’s phone rings":"telefoon van Bob gaat over","to Alice":"naar Alice",Answered:"Opgenomen","200 OK, then ACK":"200 OK, dan ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob neemt op. Zijn 200 OK bevat zijn SDP-antwoord: G.711, te sturen naar zijn telefoon. De server zet er weer zijn eigen adres in voordat hij het aan Alice doorgeeft. Haar telefoon bevestigt met een ACK, die de server doorgeeft aan Bob. Het gesprek staat.","Answer (SDP)":"Antwoord (SDP)","G.711, port 49172":"G.711, poort 49172","Confirmed by":"Bevestigd met","Voice goes to":"Spraak gaat naar","The server, ports 40000, 40002":"De server, poorten 40000, 40002","Bob answers":"Bob neemt op",answered:"opgenomen",Talking:"In gesprek","Voice flows as RTP":"Spraak stroomt als RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Nu de spraak: elke 20 ms stuurt elke telefoon een RTP-pakket met 160 bytes G.711-geluid, een volgnummer en een tijdstempel, via UDP. Ze gaan naar de server, die ze doorgeeft aan de andere telefoon. SIP zwijgt zolang ze praten.",Every:"Elke","20 ms, 160 bytes of sound":"20 ms, 160 bytes geluid","Carried by":"Gedragen door","RTP over UDP":"RTP over UDP","SIP meanwhile":"SIP intussen","Nothing to say":"Niets te zeggen",VOICE:"SPRAAK","20 ms of Alice":"20 ms van Alice","20 ms of Bob":"20 ms van Bob","Hang Up":"Ophangen","BYE, and 200 OK":"BYE, en 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob hangt op: zijn telefoon stuurt BYE, via de server zoals de Record-Route vroeg, en de telefoon van Alice antwoordt 200 OK. Beide stoppen met spraak versturen. Het gesprek kostte vier soorten verzoeken; de spraak zelf was nooit deel van SIP.","No more RTP":"Geen RTP meer","Bob hangs up":"Bob hangt op","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 μ-law, de klassieke telefooncodec)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Audioklok op 8000 per seconde: +160 per 20 ms geluid.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 bytes G.711-audio (20 ms, één byte per sample)","IP Camera Streams":"Streams van IP-camera’s","Video (RTP)":"Video (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"Met RTSP halen videospelers, recorders en beveiligingsapps live beeld van IP-camera’s. Het werkt als een afstandsbediening: de speler vraagt wat de camera aanbiedt, zet een stream op en zegt PLAY en later TEARDOWN, in tekstberichten die veel op HTTP lijken. De video zelf gaat niet via RTSP: die stroomt apart als RTP, hier over UDP.",Controls:"Opdrachten",Watched:"Bekeken","Described, set up, played, stopped":"Beschreven, opgezet, afgespeeld, gestopt","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC vroeg de camera wat hij had, meldde zich aan met een hash van het wachtwoord, zette één videospoor op en drukte op PLAY. De video kwam als RTP-pakketten op eigen poorten, een keyframe in drie stukken, tot TEARDOWN de sessie beëindigde. Druk op OPNIEUW om het nog eens te bekijken.","6 on one TCP connection":"6 over één TCP-verbinding","Key frame":"Keyframe","Split into 3 packets":"In 3 pakketten","1185d200, 60 s timeout":"1185d200, verloopt na 60 s","What Can You Do?":"Wat kun je?","OPTIONS over a TCP connection":"OPTIONS over een TCP-verbinding","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC opent rtsp://192.168.1.64/stream1. Hij verbindt met de camera op TCP-poort 554 en begint met OPTIONS: welke opdrachten ondersteun je? De camera somt ze op. Net als bij HTTP is elk verzoek en antwoord tekst; een CSeq-header nummert ze.","Numbered by":"Genummerd met","what can you do?":"wat kun je?","Describe the Stream":"De stream beschrijven","SDP says what the video is":"SDP zegt wat de video is","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE vraagt om de beschrijving van de stream. De camera wil eerst een aanmelding: 401, met een digest-challenge. VLC vraagt opnieuw met een hash van het wachtwoord, en het antwoord bevat SDP: één H.264-videospoor, RTP-payloadtype 96, met een klok van 90 kHz.","Digest: a hash":"Digest: een hash","H.264, payload type 96":"H.264, payloadtype 96",Track:"Spoor","describe stream1":"beschrijf stream1","log in first":"eerst aanmelden","SDP: H.264 video":"SDP: H.264-video","track 1":"spoor 1","Set Up":"Opzetten","Agree on ports for the video":"Poorten voor de video afspreken","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP voor trackID=1 zegt hoe het geleverd wordt: RTP over UDP, naar poort 50000 (video) en 50001 (RTCP-rapporten) van de laptop. De camera stemt in, kiest eigen poorten, 6970 en 6971, en opent een sessie, 1185d200, die elk later verzoek noemt.","Laptop ports":"Laptoppoorten","track 1, RTP over UDP":"spoor 1, RTP over UDP","to ports 50000-50001":"naar poorten 50000-50001","session 1185d200":"sessie 1185d200","from ports 6970-6971":"vanaf poorten 6970-6971",Play:"Afspelen","The remote control’s PLAY button":"De PLAY-knop van de afstandsbediening","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY start de stream vanaf nu (npt=0.000-). Het antwoord vertelt VLC welk RTP-volgnummer en welke tijdstempel eerst komen, zodat het de video kan uitlijnen. Vanaf hier gaat de video helemaal niet meer via RTSP.",Range:"Bereik","From now":"Vanaf nu","First packet":"Eerste pakket","Video arrives":"Video komt binnen","On the UDP ports":"Op de UDP-poorten","play from now":"speel af vanaf nu",playing:"speelt af","Video Arrives":"De video komt","A key frame in RTP packets":"Een keyframe in RTP-pakketten","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"De camera stuurt een keyframe, een heel beeld, in drie RTP-pakketten: H.264-fragmenten gemarkeerd als eerste, middelste en laatste, met de markerbit op de laatste. Alle drie dragen dezelfde tijdstempel van 90 kHz. Daarna volgen kleinere frames met alleen de veranderingen, 25 per seconde.",Packets:"Pakketten","3 for one key frame":"3 voor één keyframe","Same for the whole frame":"Gelijk voor het hele frame",Frames:"Frames","25 a second":"25 per seconde","a key frame in 3 packets":"een keyframe in 3 pakketten",Stop:"Stoppen","TEARDOWN ends the session":"TEARDOWN beëindigt de sessie","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Als de kijker de stream sluit, stuurt VLC TEARDOWN met de sessie-ID. De camera stopt met video sturen en bevestigt. Was VLC gewoon verdwenen, dan stopte de camera toch, zodra er 60 seconden zonder een woord van hem voorbij waren.",Ended:"Beëindigd",Otherwise:"Anders","Timeout after 60 s":"Verloopt na 60 s","stop session 1185d200":"stop sessie 1185d200",stopped:"gestopt","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"De camera. Die zit op hetzelfde netwerk, dus het frame gaat er direct heen, niet via de router.","The camera’s network port.":"De netwerkpoort van de camera.","RTP + video":"RTP + video","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, zoals de beschrijving van de camera zei)","Marker clear: more of this frame follows.":"Marker uit: er volgt meer van dit frame.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Videoklok op 90.000 per seconde; elk pakket van één frame heeft dezelfde waarde.","Identifies this video stream.":"Identificeert deze videostream.","FU indicator":"FU-indicator","0x7c (fragment of a frame)":"0x7c (fragment van een frame)","Fragmentation unit: one piece of a frame too big for one packet.":"Fragmentatie-eenheid: een stuk van een frame dat te groot is voor één pakket.","FU header":"FU-header","0x85 (first piece of a key frame)":"0x85 (eerste stuk van een keyframe)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Type 5: een keyframe (IDR), een heel beeld waarmee de decoder kan beginnen.","1398 bytes of the key frame":"1398 bytes van het keyframe","0x05 (middle piece of a key frame)":"0x05 (middelste stuk van een keyframe)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, zoals de beschrijving van de camera zei)","Marker set: the last packet of a frame.":"Marker aan: het laatste pakket van een frame.","0x45 (last piece of a key frame)":"0x45 (laatste stuk van een keyframe)","900 bytes of the key frame":"900 bytes van het keyframe","Multicast TV":"Multicast-tv","Joins and leaves":"Aan- en afmeldingen","Channel 1":"Zender 1","TV channels":"Tv-zenders","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Multicast stuurt één stream naar een groepsadres, en het netwerk kopieert die alleen waar hij gewenst is: zo leveren internetproviders live tv-zenders. Met IGMP vertelt een apparaat zijn router welke groepen het wil. Switches luisteren mee (IGMP-snooping), dus elke stream bereikt alleen de poorten die erom vroegen.","IP protocol 2":"IP-protocol 2",Groups:"Groepen","Version here":"Versie hier","Tuned In":"Afgestemd","Joined, copied, checked, left":"Aangemeld, gekopieerd, gecontroleerd, afgemeld","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"De tv-box en daarna de laptop meldden zich met IGMP-rapporten aan voor zender 1. De router meldde zich maar één keer aan voor het hele huis, en de switch luisterde mee en kopieerde de zender alleen naar de poorten die hem wilden. Query’s hielden hem gaande, en toen de laptop vertrok, hield het antwoord van de tv-box hem aan. Druk op OPNIEUW om het nog eens te bekijken.",Upstream:"Naar de provider","One stream for the home":"Eén stream voor het hele huis","Copies to ports that joined":"Kopieert naar aangemelde poorten","Every 125 s":"Elke 125 s","Pick a Channel":"Een zender kiezen","The TV box joins a group":"De tv-box meldt zich aan bij een groep","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"De kijker kiest zender 1. Elke zender is een multicastgroep, hier 233.252.0.1, en de tv-box stuurt een IGMP Membership Report naar dat adres: ik wil deze groep. De switch luistert mee (IGMP-snooping), noteert poort 2 en geeft het rapport alleen aan de router door.","Switch notes":"Switch noteert","Port 2 wants it":"Poort 2 wil hem","233.252.0.1, please":"233.252.0.1, graag","to the router port only":"alleen naar de routerpoort","Ask the Provider":"Aan de provider vragen","The router joins for the home":"De router meldt zich aan voor het huis","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"De router is een IGMP-proxy: hij meldt zich aan zijn internetkant met een eigen rapport aan voor de groep, vanaf zijn publieke adres, en het netwerk van de provider begint zender 1 over de lijn te sturen. Hoeveel schermen thuis ook afstemmen, de router meldt zich maar één keer aan.","Router role":"Rol van de router","IGMP proxy":"IGMP-proxy",Joins:"Meldt zich aan","Once for the whole home":"Eén keer voor het hele huis","for the whole home":"voor het hele huis","The Channel Flows":"De zender stroomt","Sent only where it was asked for":"Alleen gestuurd waar erom gevraagd is","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"De tv-server van de provider stuurt zender 1 naar 233.252.0.1: UDP-datagrammen met elk zeven MPEG-TS-pakketten van 188 bytes vol video en audio. De router laat ze binnen, en de switch stuurt ze alleen poort 2 uit: alleen de tv-box meldde zich aan, dus de laptop krijgt er geen.",Datagram:"Datagram","UDP, 1,316 bytes of TV":"UDP, 1.316 bytes tv",Holds:"Bevat","7 MPEG-TS packets":"7 MPEG-TS-pakketten","CHANNEL 1":"ZENDER 1","MPEG-TS over UDP":"MPEG-TS over UDP","passed into the home":"het huis in gestuurd","port 2 only":"alleen poort 2","A Second Screen":"Een tweede scherm","The laptop tunes in too":"Ook de laptop stemt af","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"De laptop opent zender 1 in VLC en stuurt een eigen rapport. De switch voegt poort 1 toe en maakt nu twee kopieën van elk datagram. De router krijgt de zender al, dus vraagt hij de provider niets: over de lijn komt nog steeds één stream.","Switch sends to":"Switch stuurt naar","Ports 1 and 2":"Poorten 1 en 2","Still one stream":"Nog steeds één stream","Router asks":"Router vraagt","Nothing new":"Niets nieuws","the same one stream":"dezelfde ene stream","copied to ports 1 and 2":"gekopieerd naar poorten 1 en 2","Still Watching?":"Kijk je nog?","The router checks regularly":"De router controleert geregeld","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Elke 125 seconden stuurt de router een General Query naar 224.0.0.1, alle apparaten: welke groepen willen jullie nog? De switch geeft hem door aan elke poort. Elk lid antwoordt op een willekeurig moment binnen 10 seconden, zodat router en switch de zender laten doorstromen.","125 seconds":"125 seconden","224.0.0.1, all devices":"224.0.0.1, alle apparaten","Answer within":"Antwoord binnen","10 seconds":"10 seconden",QUERY:"QUERY","any groups wanted?":"welke groepen gewenst?","to every port":"naar elke poort",REPORT:"RAPPORT","still watching":"kijk nog",Leave:"Afmelden","The laptop stops watching":"De laptop stopt met kijken","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"VLC sluiten stuurt een Leave Group naar 224.0.0.2, alle routers. Anderen kijken misschien nog, dus vraagt de router alleen naar die groep en wacht 1 seconde. De tv-box antwoordt, dus de zender blijft; de switch stopt alleen met sturen naar poort 1.","Leave sent to":"Afmelding naar","224.0.0.2, all routers":"224.0.0.2, alle routers","About that group alone":"Alleen naar die groep","Stays: the TV box answered":"Blijft: de tv-box antwoordde",LEAVE:"AFMELDEN","done with 233.252.0.1":"klaar met 233.252.0.1","anyone for 233.252.0.1?":"iemand voor 233.252.0.1?","to the ports that joined":"naar de aangemelde poorten","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast: 01:00:5e, dan de laatste 23 bits van het groepsadres. Netwerkkaarten luisteren naar de groepen waarvoor hun systeem zich heeft aangemeld.","The TV box’s network port.":"De netwerkpoort van de tv-box.","4, 24 bytes":"4, 24 bytes","IPv4, with one 4-byte option.":"IPv4, met één optie van 4 bytes.","48 (network control), 0":"48 (netwerkbeheer), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Gemarkeerd als netwerkbeheer, dus verstuurd vóór gewoon verkeer.","Always 1: IGMP never goes past the first router.":"Altijd 1: IGMP komt nooit verder dan de eerste router.","A multicast group address.":"Een multicast-groepsadres.","Router Alert option":"Router Alert-optie","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Vraagt elke router onderweg om erin te kijken, ook al is het pakket niet aan hem gericht.","This device wants the group’s traffic.":"Dit apparaat wil het verkeer van de groep.","Max response time":"Maximale antwoordtijd","Only queries use it.":"Alleen query’s gebruiken het.","Covers the IGMP message.":"Dekt het IGMP-bericht.","Group address":"Groepsadres","The multicast group: one TV channel.":"De multicastgroep: één tv-zender.","Seen arriving on the router’s internet side":"Gezien bij aankomst aan de internetkant van de router","MPEG-TS · 7 packets":"MPEG-TS · 7 pakketten","The provider’s router, passing the channel on.":"De router van de provider, die de zender doorgeeft.","Sync byte":"Syncbyte","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Elk transport-streampakket begint met 0x47, zodat de ontvanger kan vinden waar pakketten beginnen.","Flags, PID":"Vlaggen, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: video)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Bij welke stream het pakket hoort: de video van de zender, de audio, of de tabellen die ze opsommen.","Payload, counter":"Payload, teller","0x14 (payload only, counter 4)":"0x14 (alleen payload, teller 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Telt per PID van 0 tot 15, dus een verloren pakket valt op als een gat.","184 bytes of the channel’s video":"184 bytes van de video van de zender","More packets":"Meer pakketten","6 × 188 bytes: video and audio":"6 × 188 bytes: video en audio","Six more transport stream packets, each with its own 4-byte header.":"Nog zes transport-streampakketten, elk met een eigen header van 4 bytes.","Seen going into the switch, port 8":"Gezien bij binnenkomst in de switch, poort 8","The router, passing the channel into the home.":"De router, die de zender het huis in stuurt.","0x19 (payload only, counter 9)":"0x19 (alleen payload, teller 9)","The router asks: which groups does anyone here still want?":"De router vraagt: welke groepen wil iemand hier nog?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Leden antwoorden op een willekeurig moment binnen deze tijd, zodat hun antwoorden niet allemaal tegelijk binnenkomen.","Zero in a general query: every group.":"Nul in een algemene query: alle groepen.","This device no longer wants the group.":"Dit apparaat wil de groep niet meer.","The router asks: does anyone still want this group?":"De router vraagt: wil iemand deze groep nog?","Live Streaming Upload":"Livestreams uploaden","RTMP handshake":"RTMP-handshake","Video and audio":"Video en audio","Ingest Server":"Ingestserver","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"Met RTMP sturen de meeste streamers live video naar een platform: OBS en andere apps duwen het naar een ingestserver, die er streams voor kijkers van maakt. Gemaakt voor Flash, heeft het Flash overleefd als manier om te uploaden. Alles deelt één TCP-verbinding: opdrachten, audio en video, in chunks gesneden.","H.264 video, AAC audio":"H.264-video, AAC-audio","Encoded in AMF0":"Gecodeerd in AMF0","Secure version":"Veilige versie","RTMPS, over TLS":"RTMPS, over TLS","Adobe specification (2012)":"Adobe-specificatie (2012)",Live:"Live","Connected, published, streamed":"Verbonden, gepubliceerd, gestreamd","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS deed de handshake met de ingestserver, verbond met diens app live, kreeg stream 1 en publiceerde daarop met de streamsleutel. Video en audio stroomden daarna in chunks over dezelfde TCP-verbinding tot de streamer stopte. Druk op OPNIEUW om het nog eens te bekijken.","One TCP, port 1935":"Eén TCP, poort 1935",Stream:"Stream",Chunks:"Chunks","Up to 4,096 bytes":"Tot 4.096 bytes","None: RTMPS adds TLS":"Geen: RTMPS voegt TLS toe","TCP, then RTMP’s own":"TCP, dan die van RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"De streamer klikt op Streamen starten. OBS verbindt met de ingestserver op TCP-poort 1935, en dan heeft RTMP een eigen handshake: versie 3 en 1.536 willekeurige bytes in elke richting, die elke kant terugstuurt. Het toont dat beide kanten RTMP spreken; er wordt niets versleuteld.","Each side":"Elke kant","Sends 3,073 bytes":"Stuurt 3.073 bytes","version 3":"versie 3","1,536 random bytes":"1.536 willekeurige bytes","version 3, its own bytes":"versie 3, eigen bytes","and C1 sent back":"en C1 terug","S1 sent back":"S1 terug",Connect:"Verbinden","To the server’s live app":"Met de app live van de server","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS verhoogt zijn chunkgrootte naar 4.096 bytes en stuurt connect voor de app die live heet, in AMF0, een compact binair formaat uit Flash. De server stelt zijn eigen venster, bandbreedte en chunkgrootte in en antwoordt _result: NetConnection.Connect.Success.",App:"App",Encoding:"Codering","chunk size 4,096":"chunkgrootte 4.096","window, bandwidth, chunks":"venster, bandbreedte, chunks","Make a Stream":"Een stream maken","createStream returns stream 1":"createStream geeft stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Elk bericht noemt een berichtstream; 0 is de verbinding zelf. OBS geeft zijn streamsleutel vrij en kondigt hem aan, en vraagt dan met createStream om een stream om op te sturen, alle drie opdrachten in één pakket. De server antwoordt met stream-ID 1.","3 in one packet":"3 in één pakket",Gets:"Krijgt","Stream ID 1":"Stream-ID 1","stream ID 1":"stream-ID 1",Publish:"Publiceren","The stream key goes live":"De streamsleutel gaat live","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish noemt de streamsleutel, het geheim dat zegt van wie het kanaal is. RTMP versleutelt niets, dus de sleutel gaat als platte tekst over de lijn; platforms geven de voorkeur aan RTMPS, hetzelfde over TLS. De server controleert de sleutel en antwoordt NetStream.Publish.Start.","The stream key":"De streamsleutel","None (RTMPS adds TLS)":"Geen (RTMPS voegt TLS toe)","on stream 1":"op stream 1","stream key, live":"streamsleutel, live","Video and Sound":"Beeld en geluid","Metadata, settings, then frames":"Metadata, instellingen, dan frames","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS beschrijft de stream: 1920×1080 met 30 frames per seconde, H.264-video, AAC-audio. Hij stuurt de instellingen voor de decoders, dan een keyframe van zo’n 30 KB, in chunks van 4.096 bytes gesneden. Daarna volgen frames zonder pauze, over dezelfde TCP-verbinding.","AAC, 48 kHz stereo":"AAC, 48 kHz stereo","30 KB in 8 chunks":"30 KB in 8 chunks",METADATA:"METADATA","H.264 + AAC settings":"H.264- en AAC-instellingen","KEY FRAME":"KEYFRAME","8 chunks":"8 chunks","Stop Streaming":"Stoppen met streamen","FCUnpublish and deleteStream":"FCUnpublish en deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Als de streamer op Streamen stoppen klikt, stuurt OBS FCUnpublish en deleteStream voor stream 1. De server antwoordt NetStream.Unpublish.Success en beëindigt de uitzending voor kijkers. Dan sluit OBS de TCP-verbinding.","C0: version":"C0: versie","RTMP version 3, the only one in use.":"RTMP-versie 3, de enige in gebruik.",Time:"Tijd","A timestamp; zero is allowed.":"Een tijdstempel; nul mag.",Zero:"Nul","Random data":"Willekeurige data","Random bytes the server must send back.":"Willekeurige bytes die de server moet terugsturen.","S0: version":"S0: versie","Random bytes the client must send back.":"Willekeurige bytes die de client moet terugsturen.","1,536 bytes: C1 back":"1.536 bytes: C1 terug","The timestamp from the block it echoes.":"De tijdstempel uit het blok dat hij terugstuurt.","Time read":"Gelezen tijd","C1’s random bytes, sent back unchanged.":"De willekeurige bytes van C1, ongewijzigd teruggestuurd.","1,536 bytes: S1 back":"1.536 bytes: S1 terug","S1’s random bytes, sent back unchanged.":"De willekeurige bytes van S1, ongewijzigd teruggestuurd.","RTMP · 2 messages":"RTMP · 2 berichten","First message":"Eerste bericht","Chunk header":"Chunkheader","type 0, chunk stream 2":"type 0, chunkstream 2","A full header follows: this chunk starts a message.":"Er volgt een volledige header: deze chunk begint een bericht.","Message stream":"Berichtstream","Stream 0: the connection itself. (This number alone is little-endian.)":"Stream 0: de verbinding zelf. (Alleen dit getal is little-endian.)","Chunk size":"Chunkgrootte","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Vanaf nu snijdt deze kant berichten in chunks tot deze grootte (128 tot hij iets anders zegt).","Second message":"Tweede bericht","type 0, chunk stream 3":"type 0, chunkstream 3","Matches a reply to its request.":"Koppelt een antwoord aan zijn verzoek.","Command object":"Opdrachtobject","object, 5 properties":"object, 5 eigenschappen","Which app on the server, and the address OBS was given.":"Welke app op de server, en het adres dat OBS kreeg.","End of object":"Einde van object","RTMP · 4 messages":"RTMP · 4 berichten","The other side should hear back after every this many bytes it sends.":"De andere kant moet na elk zo’n aantal verstuurde bytes iets terughoren.","Bandwidth, limit":"Bandbreedte, limiet","5,000,000 bytes, dynamic":"5.000.000 bytes, dynamisch","How much the sender may have unacknowledged at once.":"Hoeveel de afzender tegelijk onbevestigd mag hebben.","Third message":"Derde bericht","Fourth message":"Vierde bericht",Properties:"Eigenschappen","object, 2 properties":"object, 2 eigenschappen",Information:"Informatie","object, 4 properties":"object, 4 eigenschappen","RTMP · 3 messages":"RTMP · 3 berichten","Nothing: AMF0 null.":"Niets: AMF0-null.","Stream key":"Streamsleutel","Which channel this is. It works like a password, and here it travels unencrypted.":"Welk kanaal dit is. Hij werkt als een wachtwoord en reist hier onversleuteld.","Stream ID":"Stream-ID","The new stream: video and audio will go on it.":"De nieuwe stream: video en audio gaan erover.","type 0, chunk stream 4":"type 0, chunkstream 4","Stream 1, the one createStream made.":"Stream 1, die createStream maakte.","Publishing type":"Publicatietype","Live: not recorded by this request.":"Live: dit verzoek neemt niets op.","type 0, chunk stream 5":"type 0, chunkstream 5","object, 3 properties":"object, 3 eigenschappen",Handler:"Handler",Event:"Gebeurtenis",Metadata:"Metadata","array of 14":"array van 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"Codec-ID’s zoals in Flash-videobestanden: 7 is H.264, 10 is AAC.","type 0, chunk stream 6":"type 0, chunkstream 6","Frame, codec":"Frame, codec","0x17 (key frame, H.264)":"0x17 (keyframe, H.264)","AVC packet type":"AVC-pakkettype","0 (decoder settings)":"0 (decoderinstellingen)","The sequence header: the settings a decoder needs before the first frame.":"De sequence header: de instellingen die een decoder nodig heeft vóór het eerste frame.","Composition time":"Compositietijd","The H.264 profile, level and parameter sets.":"Het profiel, het niveau en de parametersets van H.264.","AAC; the other bits are fixed for AAC.":"AAC; de overige bits liggen vast voor AAC.","AAC packet type":"AAC-pakkettype","Sample rate and channels, for the decoder.":"Samplefrequentie en kanalen, voor de decoder.","1 (video)":"1 (video)","Compressed picture data.":"Gecomprimeerde beelddata.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Het keyframe: een heel beeld. Elke 4.096 bytes zet een chunkheader van 1 byte het voort."},r=n=>`${n} ${n==="1"?"record":"records"}`,h={strings:{...d,...i,...s},patterns:[[/^([\d,]+) bytes$/,"$&"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$&"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$&"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$&"],[/^(.+) h later$/,"$1 u later"],[/^(.+) min later$/,"$1 min later"],[/^(.+) s later$/,"$1 s later"],[/^(\S+) \(relative\)$/,"$1 (relatief)"],[/^(\d+) \(ephemeral\)$/,"$1 (tijdelijk)"],[/^(\d+) TCP segments$/,"$1 TCP-segmenten"],[/^(\d+) segments$/,"$1 segmenten"],[/^(.*), (\d+) segments$/,"$1, $2 segmenten"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(n,e,t,a)=>`TLS 1.3 · ${r(e)} · bytes ${t} van ${a}`],[/^TLS 1\.3 · (\d+) records?$/,(n,e)=>`TLS 1.3 · ${r(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Ethernet-opvulling · $1 bytes"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 nulbytes, tot het minimum van 300 bytes"],[/^(\d+) zero bytes$/,"$1 nulbytes"],[/^(\d+) random bytes$/,"$1 willekeurige bytes"],[/^Seen as it leaves (.+)$/,"Gezien bij het verlaten van $1"],[/^Option (\d+)$/,"Optie $1"],[/^value (\d+), echo (\d+)$/,"waarde $1, echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 bytes, plus $1 aan opties."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows begint bij $1. Hier met opzet op $2 gezet."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(n,e,t)=>t==="1"?`Begon bij ${e}; de router onderweg trok er 1 af.`:`Begon bij ${e}; elk van de ${t} routers onderweg trok er 1 af.`],[/^all (\d+) bytes of it$/,"alle $1 bytes ervan"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Het pakket dat dit veroorzaakte, zoals het meldende apparaat het ontving (TTL $1), zodat de afzender weet om welk pakket het ging."],[/^Port (\d+), TLS from the start$/,"Poort $1, meteen TLS"],[/^(\d+), TLS from the start$/,"$1, meteen TLS"],[/^type 79, (\d+) bytes$/,"type 79, $1 bytes"],[/^(\d+) of (\d+) bytes$/,"$1 van $2 bytes"],[/^(\d+) more bytes$/,"nog $1 bytes"],[/^offset (\d+), (\d+) bytes$/,"offset $1, $2 bytes"],[/^offset 0, (\d+) bytes \(all of it\)$/,"offset 0, $1 bytes (alles)"],[/^record, (\d+) bytes$/,"record, $1 bytes"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · bericht $1 van 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(n,e,t,a)=>`${e??""}${t}-${a==="request"?"verzoek":"antwoord"}`],[/^(\d+) registers$/,"$1 registers"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, spraak"],[/^"(.*)" \(([\d,]+) bytes\)$/,"$&"],[/^(masked|not masked), (\d+) bytes?$/,(n,e,t)=>`${e==="masked"?"gemaskeerd":"niet gemaskeerd"}, ${t} bytes`],[/^(\d+) \(disguised\)$/,"$1 (verhuld)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$&"],[/^0 \(none\), (\d+) bytes$/,"0 (geen), $1 bytes"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), type $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (register $2)"],[/^yes, AS (\d+)$/,"ja, AS $1"],[/^id 2, (\d+) bytes$/,"$&"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, zoals afgesproken in de SDP)"]],post:o};export{h as default};
